INSERT INTO `products` (`id`, `category_id`, `sku`, `name`, `description`, `picture_name`, `price`, `price_3`, `price_2`, `stock`, `current_discount`, `product_unit`, `product_unit_1`, `product_unit_2`, `product_unit_value`, `product_type`, `product_unit_weight`, `is_available`, `add_date`, `user_level`) VALUES
(1, 1, 'QOLS00001', 'Abado 50 WP 20 X 20 X 10 gr', 'ABADO 50 WP merupakan fungisida sistemik dan protektif berbentuk tepung yang dapat disuspensikan untuk mengendalikan penyakit busuk buah kakao dan penyakit hawar daun pada tanaman kentang.\r\nBahan Aktif : Dimetomorf 50%\r\nIsi Bersih: 10 gr', 'ABADO_50WP_10GRAM.jpg', 7350, 7140, 7000, 1748, 0, 'Pcs', 'Pcs', 'Box', '1', '', 16.3, 1, NULL, 0),
(2, 1, 'QOLS00002', 'Abado 50 WP 20 X 6 X 40 gr', 'ABADO 50 WP merupakan fungisida sistemik dan protektif berbentuk tepung yang dapat disuspensikan untuk mengendalikan penyakit busuk buah kakao dan penyakit hawar daun pada tanaman kentang.\nBahan Aktif : Dimetomorf 50%\r\nIsi Bersih: 40 gr', 'ABADO_50WP_40GRAM.jpg', 26250, 25500, 25000, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 60.8, 1, NULL, 0),
(3, 9, 'QOLS00003', 'Abenz 22 EC 100 X 100 ml', 'ABENZ 22 EC merupakan insektisida racun kontak dan lambung berbentuk pekatan yang dapat diemulsikan berwarna kuning kecoklatan, untuk mengendalikan hama ulat grayak pada tanaman jagung dan penggerek buah pada tanaman tomat.\nBahan Aktif : Emamektin benzoat 22 g/l\r\nIsi Bersih: 100 ml', 'ABENZ_22EC_100ML.jpg', 72450, 70380, 69000, 1000, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 126, 1, NULL, 0),
(4, 9, 'QOLS00004', 'Abenz 22 EC 40 X 250 ml', 'ABENZ 22 EC merupakan insektisida racun kontak dan lambung berbentuk pekatan yang dapat diemulsikan berwarna kuning kecoklatan, untuk mengendalikan hama ulat grayak pada tanaman jagung dan penggerek buah pada tanaman tomat.\nBahan Aktif : Emamektin benzoat 22 g/l\r\nIsi Bersih: 250 ml\r\n', 'ABENZ_22EC_250ML.jpg', 151200, 146880, 144000, 3046, 0, 'Pcs', 'Pcs', 'Box', '40', '1', 300, 1, NULL, 0),
(5, 15, 'QOLS00005', 'Abojo 60 WP 10 X 20 X 50 gr', 'ABOJO 60 WP merupakan moluskisida racun kontak berbentuk tepung yang dapat disuspensikan berwarna putih. ABOJO 60 WP dapat digunakan untuk mengendalikan hama siput murbei pada tanaman padi sawah.\r\nBahan Aktif: Fentin Asetat 60%\r\nIsi Bersih: 50 gr\r\n', 'ABOJO_60WP_50GRAM.jpg', 36750, 35700, 35000, 26302, 0, 'Pcs', 'Pcs', 'Box', '200', '', 65.8, 1, NULL, 0),
(6, 15, 'QOLS00006', 'Abojo 60 WP 100 X 100 gr', 'ABOJO 60 WP merupakan moluskisida racun kontak berbentuk tepung yang dapat disuspensikan berwarna putih. ABOJO 60 WP dapat digunakan untuk mengendalikan hama siput murbei pada tanaman padi sawah.\r\nBahan Aktif: Fentin Asetat 60%\r\nIsi Bersih: 100 gr\r\n', 'ABOJO_60WP_100GRAM.jpg', 71400, 69360, 68000, 15535, 0, 'Pcs', 'Pcs', 'Box', '100', '', 118, 1, NULL, 0),
(7, 1, 'QOLS00007', 'Acrobat WP 16 X 20 X 10 gr', 'ACROBAT 50 WP merupakan fungisida sistemik berbentuk tepung yang dapat disuspensikan berwarna putih digunakan untuk mengendalikan penyakit pada tanaman cabai, jagung, kentang, semangka, tembakau, dan tomat\nBahan aktif: Dimetomorf 50%\r\nIsi Bersih: 10 Gram', 'ACROBAT_50WP_10GRAM.jpg', 11550, 11220, 11000, 1000, 0, 'Pcs', 'Pcs', 'Box', '320', '1', 1, 1, NULL, 0),
(8, 1, 'QOLS00008', 'Acrobat WP 20 X 6 X 40 gr', 'ACROBAT 50 WP merupakan fungisida sistemik berbentuk tepung yang dapat disuspensikan berwarna putih digunakan untuk mengendalikan penyakit pada tanaman cabai, jagung, kentang, semangka, tembakau, dan tomat\nBahan aktif: Dimetomorf 50%\r\nIsi Bersih: 40 Gram\r\n', 'ACROBAT_50WP_40GRAM.jpg', 40950, 39780, 39000, 1000, 0, 'Pcs', 'Pcs', 'Box', '120', '1', 55.4, 1, NULL, 0),
(9, 9, 'QOLS00009', 'Afonil 50 SC 100 X 100 ml', 'AFONIL 50 SC merupakan insektisida sistemik racun kontak dan lambung berbentuk pekatan suspensi berwarna putih, untuk mengendalikan hama pada tanaman padi sawah.\nBahan Aktif : Fipronil 50 g/l\r\nIsi Bersih: 100 ml\r\n', 'AFONIL_50SC_100ML.jpg', 32550, 31620, 31000, 1072, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 154.8, 1, NULL, 0),
(10, 9, 'QOLS00010', 'Afonil 50 SC 100 X 50 ml', 'AFONIL 50 SC merupakan insektisida sistemik racun kontak dan lambung berbentuk pekatan suspensi berwarna putih, untuk mengendalikan hama pada tanaman padi sawah.\nBahan Aktif : Fipronil 50 g/l\r\nIsi Bersih: 50 ml\r\n', 'AFONIL_50SC_50ML.jpg', 19425, 18870, 18500, 1000, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 78, 1, NULL, 0),
(11, 9, 'QOLS00011', 'Afonil 50 SC 20 X 500 ml', 'AFONIL 50 SC merupakan insektisida sistemik racun kontak dan lambung berbentuk pekatan suspensi berwarna putih, untuk mengendalikan hama pada tanaman padi sawah.\nBahan Aktif : Fipronil 50 g/l\r\nIsi Bersih: 500 ml\r\n', 'AFONIL_50SC_500ML.jpg', 133350, 129540, 127000, 220, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 600, 1, NULL, 0),
(12, 9, 'QOLS00012', 'Afonil 50 SC 40 X 250 ml', 'AFONIL 50 SC merupakan insektisida sistemik racun kontak dan lambung berbentuk pekatan suspensi berwarna putih, untuk mengendalikan hama pada tanaman padi sawah.\nBahan Aktif : Fipronil 50 g/l\r\nIsi Bersih: 250 ml\r\n', 'AFONIL_50SC_250ML.jpg', 74550, 72420, 71000, 269, 0, 'Pcs', 'Pcs', 'Box', '40', '1', 336.3, 1, NULL, 0),
(13, 16, 'QOLS00013', 'Agridex 715 EC 12 X 1 ltr', 'AGRIDEX 715 EC adalah bahan perata dan penetran yang berbentuk larutan yang dapat diemulsikan, berwarna kuning jernih, untuk mengurangi tegangan permukaan larutan semprot Pestisida, meratakan dan meningkatkan daya penetrasi pestisida ke dalam jaringan tanaman\r\nBahan aktif : Minyak Parafinik 715 g/l\r\nIsi Bersih: 1 Liter\r\n', 'AGRIDEX_715EC_1LITER.jpg', 100800, 97920, 96000, 47, 0, 'Pcs', 'Pcs', 'Box', '12', '', 1, 1, NULL, 0),
(14, 9, 'QOLS00014', 'Agrimec 18 EC 40 X 250 ml', 'Agrimec merupakan Insektisida racun kontak berbentuk pekatan yang dapat diemulsikan, berwarna kuning pucat, untuk mengendalikan hama pada tanaman apel, cabai, jeruk, kacang hijau, kacang panjang, kelapa sawit, kentang, krisan, kubis, dan tomat.\nBahan Aktif:  18 g/l Abamektin\r\nKemasan : 250 ml\r\n', 'AGRIMEC_18EC_250ML.jpg', 99750, 96900, 95000, 5350, 0, 'Pcs', 'Pcs', 'Box', '40', '1', 302.5, 1, NULL, 0),
(15, 17, 'QOLS00015', 'Agristick 400 L 12 X 1 ltr', 'Agristick 400 L adalah merupakan bahan perata dan perekat non ionic berbentuk larutan tidak berwarna dengan, bahan aktif : Alkilaril poliglikol eter 400 g/L. Penyerapan perekat pestisida oleh petani akan tinggi menjelang menjelang hingga akhir hujan berlangsung. perekat penembus pestisida terbaik bisa anda buktikan dengan cara menyemprot daun talas atau tanaman bawang merah.\r\nBahan aktif: Alkilaril poliglikol eter 400 g/L\r\nIsi Bersih: 1 Liter\r\n', 'AGRISTICK_400L_1LITER.jpg', 112875, 109650, 107650, 0, 0, 'Pcs', 'Pcs', 'Box', '0', '', 1, 1, NULL, 0),
(16, 9, 'QOLS00016', 'Agus 500 SC 100 X 100 ml', 'AGUS 500 SC merupakan Insektisida yang juga bersifat akarisida bekerja sebagai racun kontak da perut, berbentuk pekatan suspensi berwarna putih keabu-abuan yang dapat larut dalam air untuk mengendalikan hama serangga pada tanaman cabai.\nBahan Aktif: Diafentiuron 500 g/l\r\nIsi Bersih: 100 ml\r\n', 'AGUS_500SC_100ML.jpg', 65625, 63750, 62500, 4720, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 152, 1, NULL, 0),
(17, 9, 'QOLS00017', 'Agus 500 SC 40 X 250 ml', 'AGUS 500 SC merupakan Insektisida yang juga bersifat akarisida bekerja sebagai racun kontak da perut, berbentuk pekatan suspensi berwarna putih keabu-abuan yang dapat larut dalam air untuk mengendalikan hama serangga pada tanaman cabai.\nBahan Aktif: Diafentiuron 500 g/l\r\nIsi Bersih: 250 ml\r\n', 'AGUS_500SC_250ML.jpg', 149100, 144840, 142000, 11083, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 331.3, 1, NULL, 0),
(18, 2, 'QOLS00018', 'Akalis 550 SC 10 X 1 ltr', 'AKALIS 550 SC merupakan Herbisida sistemik selektif pra tumbuh dan purna tumbuh berbentuk pekatan suspensi berwarna putih digunakan untuk mengendalikan dulma di tanaman jagung.\nBahan Aktif : Atrazin 500 g/l + Mesotrion 50 g/l\r\nIsi Bersih: 1 Liter\r\n', 'AKALIS_550SC_1 LITER.jpg', 257250, 249900, 245000, 1000, 0, 'Pcs', 'Pcs', 'Box', '10', '1', 2, 1, NULL, 0),
(19, 2, 'QOLS00019', 'Akalis 550 SC 20 X 500 ml', 'AKALIS 550 SC merupakan Herbisida sistemik selektif pra tumbuh dan purna tumbuh berbentuk pekatan suspensi berwarna putih digunakan untuk mengendalikan dulma di tanaman jagung.\nBahan Aktif : Atrazin 500 g/l + Mesotrion 50 g/l\r\nIsi Bersih: 500 ml\r\n', 'AKALIS_550SC_500ML.jpg', 136500, 132600, 130000, 101, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 1, 1, NULL, 0),
(20, 2, 'QOLS00020', 'Akalis 550 SC 40 X 250 ml', 'AKALIS 550 SC merupakan Herbisida sistemik selektif pra tumbuh dan purna tumbuh berbentuk pekatan suspensi berwarna putih digunakan untuk mengendalikan dulma di tanaman jagung.\nBahan Aktif : Atrazin 500 g/l + Mesotrion 50 g/l\r\nIsi Bersih: 250 ml\r\n', 'AKALIS_550SC_250ML.jpg', 75075, 72930, 71500, 994, 0, 'Pcs', 'Pcs', 'Box', '40', '1', 542.5, 1, NULL, 0),
(21, 9, 'QOLS00021', 'Alika 247 ZC 100 X 50 ml', 'Alika 247ZC merupakan insektisida racun kontak berbentuk pekatan suspensi, berwarna putih kecoklat - coklatan, berdaya kerja luas, untuk mengendalikan hama kutu - kutuan dan ulat - ulatan pada tanaman bawang merah, cabai, jagung jarak pagar, jeruk, kacang hijau, kacang panjang, kakao, kedelai, kelapa sawit, kentang, kopi, kubis, mangga, semangka, tembakau, terung, dan tomat\n\r\nBahan aktif: Lamda sihalotrin 106 g/l, tiametoksam 141 g/l\r\nisi kemasan: 50 ml', 'ALIKA_247ZC_50ML.jpg', 36488, 35445, 34750, 16000, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 77.5, 1, NULL, 0),
(22, 9, 'QOLS00022', 'Alika 247 ZC 40 X 250 ml', 'Alika 247ZC merupakan insektisida racun kontak berbentuk pekatan suspensi, berwarna putih kecoklat - coklatan, berdaya kerja luas, untuk mengendalikan hama kutu - kutuan dan ulat - ulatan pada tanaman bawang merah, cabai, jagung jarak pagar, jeruk, kacang hijau, kacang panjang, kakao, kedelai, kelapa sawit, kentang, kopi, kubis, mangga, semangka, tembakau, terung, dan tomat\n\r\nBahan aktif: Lamda sihalotrin 106 g/l, tiametoksam 141 g/l\r\nisi kemasan: 250 ml', 'ALIKA_247ZC_250ML.jpg', 151200, 146880, 144000, 10280, 0, 'Pcs', 'Pcs', 'Box', '40', '1', 338.8, 1, NULL, 0),
(23, 9, 'QOLS00023', 'Alika 247 ZC 50 X 100 ml', 'Alika 247ZC merupakan insektisida racun kontak berbentuk pekatan suspensi, berwarna putih kecoklat - coklatan, berdaya kerja luas, untuk mengendalikan hama kutu - kutuan dan ulat - ulatan pada tanaman bawang merah, cabai, jagung jarak pagar, jeruk, kacang hijau, kacang panjang, kakao, kedelai, kelapa sawit, kentang, kopi, kubis, mangga, semangka, tembakau, terung, dan tomat\n\r\nBahan aktif: Lamda sihalotrin 106 g/l, tiametoksam 141 g/l\r\nisi kemasan: 100 ml', 'ALIKA_247ZC_100ML.jpg', 64575, 62730, 61500, 17857, 0, 'Pcs', 'Pcs', 'Box', '50', '1', 144, 1, NULL, 0),
(24, 18, 'QOLS00024', 'Amira 10 X 500 ml', 'Dalam dunia pertanian, stres tanaman adalah salah satu penyebab utama penurunan hasil panen. Stres bisa disebabkan oleh cuaca ekstrem, kekeringan, serangan hama, atau ketidakseimbangan nutrisi. Untuk mengatasi tantangan ini, hadir Amira Anti-Stres—formulasi nutrisi tanaman yang dirancang khusus untuk memperkuat daya tahan tanaman dan meningkatkan penyerapan unsur hara.\r\nKandungan : Magnesium (MgO) 3,62 % w/w, Boron (B) 0.63% w/w & Mengandung 13% ekstrak rumput laut (Ascophylium nodosum)\r\nManfaat Amira :\r\n- Perlindungan maksimal tanaman dari stress\r\n- Tanaman kuat, tumbuh maksimal\r\nIsi Bersih: 500 ml\r\n', 'AMIRA_500ML.jpg', 126000, 122400, 120000, 140, 0, 'Pcs', 'Pcs', 'Box', '1', '', 750, 1, NULL, 0),
(25, 1, 'QOLS00025', 'Amistartop 325 SC 100 X 50 ml', 'Amistar Top 325 SC merupakan Fungisida Sistemik yang bersifat protektif, kuratif, dan preventif berbentuk pekatan suspensi, berwarna kuning muda, untuk mengendalikan penyakit pada tanaman bawang merah, buah naga, cabai, jagung, jarak (pembibitan), jeruk, kacang tanah, kakao, karet, kedelai, kelapa sawit (pembibitan), kentang, kopi, krisan, kubis, mangga, melon, padang rumput golf, padi, tembakau, dan tomat.\n\r\nBahan aktif : Azoksistrobin 200 g/l & Difenokonazol 125 g/l\r\nIsi : 50ml', 'AMISTARTOP_325EC_50ML.jpg', 63525, 61710, 60500, 13983, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 75.6, 1, NULL, 0),
(26, 1, 'QOLS00026', 'Amistartop 325 SC 20 X 250 ml', 'Amistar Top 325 SC merupakan Fungisida Sistemik yang bersifat protektif, kuratif, dan preventif berbentuk pekatan suspensi, berwarna kuning muda, untuk mengendalikan penyakit pada tanaman bawang merah, buah naga, cabai, jagung, jarak (pembibitan), jeruk, kacang tanah, kakao, karet, kedelai, kelapa sawit (pembibitan), kentang, kopi, krisan, kubis, mangga, melon, padang rumput golf, padi, tembakau, dan tomat.\n\r\nBahan aktif : Azoksistrobin 200 g/l & Difenokonazol 125 g/l\r\nIsi : 250ml', 'AMISTARTOP_325EC_250ML.jpg', 279300, 271320, 266000, 18721, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 332.5, 1, NULL, 0),
(27, 1, 'QOLS00027', 'Amistartop 325 SC 50 X 100 ml', 'Amistar Top 325 SC merupakan Fungisida Sistemik yang bersifat protektif, kuratif, dan preventif berbentuk pekatan suspensi, berwarna kuning muda, untuk mengendalikan penyakit pada tanaman bawang merah, buah naga, cabai, jagung, jarak (pembibitan), jeruk, kacang tanah, kakao, karet, kedelai, kelapa sawit (pembibitan), kentang, kopi, krisan, kubis, mangga, melon, padang rumput golf, padi, tembakau, dan tomat.\n\r\nBahan aktif : Azoksistrobin 200 g/l & Difenokonazol 125 g/l\r\nIsi : 100ml', 'AMISTARTOP_325EC_100ML.jpg', 117075, 113730, 111500, 19140, 0, 'Pcs', 'Pcs', 'Box', '50', '1', 144.2, 1, NULL, 0),
(28, 1, 'QOLS00028', 'Amolin 300 EC 100 X 100 ml', 'Fungisida sistemik berbentuk pekatan yang dapat diemulsikan untuk mengendalikan penyakit busuk pelepah pada tanaman padi.\nBahan Aktif : Difekonazole 150 g/l + Propikonazole 150g/l\r\nIsi Bersih: 100 ml\r\n', 'AMOLIN_300EC_100ML.jpg', 54600, 53040, 52000, 4790, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 139.1, 1, NULL, 0),
(29, 1, 'QOLS00029', 'Amolin 300 EC 40 X 250 ml', 'Fungisida sistemik berbentuk pekatan yang dapat diemulsikan untuk mengendalikan penyakit busuk pelepah pada tanaman padi.\nBahan Aktif : Difekonazole 150 g/l + Propikonazole 150g/l\r\nIsi Bersih: 250 ml\r\n', 'AMOLIN_300EC_250ML.jpg', 128100, 124440, 122000, 211, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 336.5, 1, NULL, 0),
(30, 9, 'QOLS00030', 'Amuron 70 EC 100 X 100 ml', 'AMURON 70 EC merupakan Insektisida racun kontak dan lambung berbentuk pekatan yang dapat diemulsikan berwarna kuning bening digunakan untuk mengendalikan hama ulat penggerek buah pada tanaman cabai.\r\nBahan Aktif : Heksaflumuron 50g/l + Emamektin benzoat 20g/l\r\nIsi Bersih: 100 ml', 'AMURON_70EC_100ML.jpg', 57750, 56100, 55000, 13, 0, 'Pcs', 'Pcs', 'Box', '100', '', 131, 1, NULL, 0),
(31, 9, 'QOLS00031', 'Amuron 70 EC 40 X 250 ml', 'AMURON 70 EC merupakan Insektisida racun kontak dan lambung berbentuk pekatan yang dapat diemulsikan berwarna kuning bening digunakan untuk mengendalikan hama ulat penggerek buah pada tanaman cabai.\r\nBahan Aktif : Heksaflumuron 50g/l + Emamektin benzoat 20g/l\r\nIsi Bersih: 250 ml', 'AMURON_70EC_250ML.jpg', 123900, 120360, 118000, 1069, 0, 'Pcs', 'Pcs', 'Box', '40', '', 1, 1, NULL, 0),
(32, 9, 'QOLS00032', 'Android 72 EC 20 X 200 ml', 'ANDROID 72 EC merupakan Insektisida racun kontak dan lambung, berbentuk pekatan yang dapat diemulsikan, berwarna coklat, untuk mengendalikan hama pada tanaman Kedelai.\nBahan Aktif : Abamektin 72 g/l\r\nIsi Bersih: 200 ml\r\n', 'ANDROID_72EC_200ML.jpg', 118125, 114750, 112500, 420, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 1, 1, NULL, 0),
(33, 9, 'QOLS00033', 'Android 72 EC 20 X 400 ml', 'ANDROID 72 EC merupakan Insektisida racun kontak dan lambung, berbentuk pekatan yang dapat diemulsikan, berwarna coklat, untuk mengendalikan hama pada tanaman Kedelai.\nBahan Aktif : Abamektin 72 g/l\r\nIsi Bersih: 400 ml\r\n', 'ANDROID_72EC_400ML.jpg', 231000, 224400, 220000, 400, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 533, 1, NULL, 0),
(34, 9, 'QOLS00034', 'Android 72 EC 50 X 80 ml', 'ANDROID 72 EC merupakan Insektisida racun kontak dan lambung, berbentuk pekatan yang dapat diemulsikan, berwarna coklat, untuk mengendalikan hama pada tanaman Kedelai.\nBahan Aktif : Abamektin 72 g/l\r\nIsi Bersih: 80 ml\r\n', 'ANDROID_72EC_80ML.jpg', 53550, 52020, 51000, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 122, 1, NULL, 0),
(35, 1, 'QOLS00035', 'Anmi 100 SC 40 X 250 ml', 'ANMI 100 SC adalah fungisida sistemik berbahan aktif heksakonazol yang diformulasikan khusus untuk mengendalikan penyakit bercak ungu (Alternaria porri) pada tanaman bawang merah. Dengan formulasi SC (Suspension Concentrate), produk ini mudah diaplikasikan dan memberikan perlindungan menyeluruh terhadap tanaman.\nBahan Aktif : Heksakonazol 100 g/l\r\nIsi Bersih: 250 ml\r\n', 'ANMI_100SC_250ML.jpg', 59850, 58140, 57000, 200, 0, 'Pcs', 'Pcs', 'Box', '40', '1', 348.5, 1, NULL, 0),
(36, 1, 'QOLS00036', 'Antracol 70 WP 12 X 1 kg', 'ANTRACOL 70 WP merupakan Fungisida kontak yang bersifat protektif berbentuk tepung yang dapat disuspensikan berwarna krem untuk mengendalikan penyakit-penyakit pada tanaman apel, anggrek, anggur, bawang merah, bawang daun, bawang putih, cabai merah, cengkeh, jagung, jarak, jeruk, kacang tanah, kacang panjang, kentang, kedelai, ketimun, kina, kopi, kubis, krisan, lada, mangga, padi, pembibitan kelapa sawit, petsai, rosela, semangka, strawberi, teh, dan tomat\r\nBahan aktif : Propineb 70%\r\nIsi Bersih: 1 Kilogram\r\n', 'ANTRACOL_70WP_1KG.jpg', 161700, 157080, 154000, 1000, 0, 'Pcs', 'Pcs', 'Box', '12', '', 1, 1, NULL, 0),
(37, 1, 'QOLS00037', 'Antracol 70 WP 20 X 500 gr', 'ANTRACOL 70 WP merupakan Fungisida kontak yang bersifat protektif berbentuk tepung yang dapat disuspensikan berwarna krem untuk mengendalikan penyakit-penyakit pada tanaman apel, anggrek, anggur, bawang merah, bawang daun, bawang putih, cabai merah, cengkeh, jagung, jarak, jeruk, kacang tanah, kacang panjang, kentang, kedelai, ketimun, kina, kopi, kubis, krisan, lada, mangga, padi, pembibitan kelapa sawit, petsai, rosela, semangka, strawberi, teh, dan tomat\r\nBahan aktif : Propineb 70%\r\nIsi Bersih: 500 gr\r\n', 'ANTRACOL_70WP_250GRAM.jpg', 82950, 80580, 79000, 1000, 0, 'Pcs', 'Pcs', 'Box', '20', '', 575, 1, NULL, 0),
(38, 1, 'QOLS00038', 'Antracol 70 WP 40 X 250 gr', 'ANTRACOL 70 WP merupakan Fungisida kontak yang bersifat protektif berbentuk tepung yang dapat disuspensikan berwarna krem untuk mengendalikan penyakit-penyakit pada tanaman apel, anggrek, anggur, bawang merah, bawang daun, bawang putih, cabai merah, cengkeh, jagung, jarak, jeruk, kacang tanah, kacang panjang, kentang, kedelai, ketimun, kina, kopi, kubis, krisan, lada, mangga, padi, pembibitan kelapa sawit, petsai, rosela, semangka, strawberi, teh, dan tomat\r\nBahan aktif : Propineb 70%\r\nIsi Bersih: 250 gram\r\n', 'ANTRACOL_70WP_500GRAM.jpg', 42263, 41055, 40250, 1000, 0, 'Pcs', 'Pcs', 'Box', '40', '', 291.3, 1, NULL, 0),
(39, 1, 'QOLS00039', 'Anvil 50 SC 10 X 1 ltr', 'ANVIL 50SC merupakan Fungisida sistemik berbentuk suspensi, berwarna putih kecoklat-coklatan untuk mengendalikan penyakit pada tanaman apel, bawang merah, bawang putih, cabai, jambu mete, kacang tanah, karet, kedelai, kelapa sawit, kopi, padi, pisang, semangka, dan tomat\n\r\nBahan aktif : Heksakonazol 50 g/l\r\nIsi kemasan : 1 Liter', 'ANVIL_50SC_1LITER.jpg', 231000, 224400, 220000, 1000, 0, 'Pcs', 'Pcs', 'Box', '10', '1', 1, 1, NULL, 0),
(40, 1, 'QOLS00040', 'Anvil 50 SC 40 X 250 ml', 'ANVIL 50SC merupakan Fungisida sistemik berbentuk suspensi, berwarna putih kecoklat-coklatan untuk mengendalikan penyakit pada tanaman apel, bawang merah, bawang putih, cabai, jambu mete, kacang tanah, karet, kedelai, kelapa sawit, kopi, padi, pisang, semangka, dan tomat\n\r\nBahan aktif : Heksakonazol 50 g/l\r\nIsi kemasan : 250ml', 'ANVIL_50SC_250ML.jpg', 64575, 62730, 61500, 80, 0, 'Pcs', 'Pcs', 'Box', '40', '1', 324.25, 1, NULL, 0),
(41, 18, 'QOLS00041', 'A-PlusCal 20 X 250 gr', 'A-PlusCal merupakan pupuk daun berkualitas tinggi yang diformulasikan khusus untuk memenuhi kebutuhan tanaman akan kalsium tanpa menambahkan nitrogen. Dengan kandungan CaO 34%, Zinc (Zn) 1,6%, dan Boron (B) 0,6%, A-PlusCal menjadi solusi ideal bagi petani dalam menjaga kesehatan tanaman, terutama di musim hujan.\nKandungan : CaO : 34%, Zn : 1,6%, B : 0,6%\r\nIsi Bersih: 250 ml', 'A-PLUSCAL_250ML.jpg', 78750, 76500, 75000, 940, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 350, 1, NULL, 0),
(42, 2, 'QOLS00042', 'Arendi 20/10 WP 20 X 20 X 25 gr', 'ARENDI 20/10 WP merupakan Herbisida sistemik pra dan purna tumbuh berbentuk tepung yang dapat disuspensikan berwarna putih untuk mengendalikan gulma pada pertanaman padi\nBahan Aktif : Natrium bispiribak 20% + Etil pirazosulfuron 10%\r\nIsi Bersih: 25 gr\r\n', 'ARENDI_25GRAM.jpg', 27300, 26520, 26000, 2, 0, 'Pcs', 'Pcs', 'Box', '400', '1', 34, 1, NULL, 0),
(43, 1, 'QOLS00043', 'Aslinya 75 WP 100 X 100 gr', 'ASLINYA 75 WP merupakan fungisida sistemik berbentuk tepung yang dapat di suspensikan berwarna jingga untuk mengendalikan penyakit blas, patah leher, blas daun, blas leher, kresek pada tanaman padi\nBahan Aktif : Trisiklazol 75%\r\nIsi Bersih: 100 gr\r\n', 'ASLINYA_75WP_100GRAM.jpg', 60900, 59160, 58000, 568, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 141.5, 1, NULL, 0),
(44, 1, 'QOLS00044', 'Aslinya 75 WP 20 X 20 X 25 gr', 'ASLINYA 75 WP merupakan fungisida sistemik berbentuk tepung yang dapat di suspensikan berwarna jingga untuk mengendalikan penyakit blas, patah leher, blas daun, blas leher, kresek pada tanaman padi\nBahan Aktif : Trisiklazol 75%\r\nIsi Bersih: 25 gr\r\n', 'ASLINYA_75WP_25GRAM.jpg', 15750, 15300, 15000, 1000, 0, 'Pcs', 'Pcs', 'Box', '400', '1', 35.3, 1, NULL, 0),
(45, 9, 'QOLS00045', 'Ayuna 50 EC 40 X 250 ml', 'AYUNA 50 EC adalah insektisida yang mengandung bahan aktif Klorfluazuron 50 g/l. Produk ini dirancang untuk mengendalikan hama Ulat Grayak (Spodoptera litura) pada tanaman. Bahan aktif yang bekerja dengan cara menghambat proses pembentukan kutikula pada hama, sehingga hama tidak dapat berkembang normal dan akhirnya mati. AYUNA 50 EC efektif digunakan untuk mengendalikan hama Ulat Grayak (Spodoptera litura), yang dapat menyebabkan kerusakan pada tanaman dengan memakan daun dan bagian tanaman lainnya.\nBahan Aktif : Klorfluazuron  50 g/I\r\nIsi Bersih: 250 ml\r\n', 'AYUNA_50EC_250ML.jpg', 92400, 89760, 88000, 1000, 0, 'Pcs', 'Pcs', 'Box', '40', '1', 313.8, 1, NULL, 0),
(46, 2, 'QOLS00046', 'Aziziah 300/10 SC 20 X 500 ml', 'Aziziah 300/10 SC adalah herbisida sistemik selektif yang digunakan untuk mengendalikan gulma pada tanaman jagung. Herbisida ini berbentuk pekatan suspensi (SC) berwarna putih dan bekerja secara efektif baik sebelum (pra tumbuh) maupun sesudah (purna tumbuh) gulma muncul.\nBahan Aktif : Atrazin 300 g/l dan Mesotrion 10 g/l.\r\nIsi Bersih: 500 ml\r\n', 'AZIZIAH_500ML.jpg', 159600, 155040, 152000, 157, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 1, 1, NULL, 0),
(47, 9, 'QOLS00047', 'Baycarb 500 EC 20 X 500 ml', 'Baycarb® 500 EC Insektisida racun kontak dan lambung berbentuk pekatan yang dapat diemulsikan berwarna coklat jernih untuk mengendalikan hama pada tanaman jagung, kakao, padi dan teh.\nBahan aktif : Fenobucarb (BPMC) 500 g/l\r\nIsi Bersih: 500 ml\r\n', 'BAYCARB_500EC_500ML.jpg', 74813, 72675, 71250, 1000, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 596, 1, NULL, 0),
(48, 9, 'QOLS00048', 'Belt Expert 480 SC 20 X 250 ml', 'Belt Expert 480 SC Insektisida sistemik racun kontak dan lambung berbentuk pekatan suspensi, berwarna putih kekuningan, mengendalikan hama pada tanaman padi sawah dan jagung\nBahan Aktif : Flubendiamida 240 g/l + Fiakloprid 240 g/l\r\nIsi Bersih: 250 ml\r\n', 'BELT_EXPERT_480SC_250ML.jpg', 405825, 394230, 386500, 1000, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 365, 1, NULL, 0),
(49, 1, 'QOLS00049', 'Bion M 1/48 WP 20 X 500 gr', 'Bion M merupakan Fungisida protektif yang berbentuk tepung yang dapat disuspensikan berwarna coklat kekuning-kuningan, untuk mengendalikan penyakit yang disebabkan oleh cendawan dan bakteri pada tanaman cabai, kentang, kubis dan tomat.\n\r\nBahan aktif : Asibenzolar-s-metil 1% + mankozeb 48%\r\nIsi kemasan : 500gr', 'BION_M_500GR.jpg', 188475, 183090, 179500, 1440, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 611, 1, NULL, 0),
(50, 9, 'QOLS00050', 'Brasso 250 EC 20 X 250 ml', 'BRASSO 250 EC merupakan Insektisida racun kontak dan lambung berbentuk pekatan yang dapat diemulsikan, berwarna merah kecoklatan, untuk mengendalikan hama pada tanaman Kakao, Cabai, dan Kedelai.\nBahan Aktif : Sipermetrin 250 g/l\r\nIsi Bersih: 250 ml\r\n', 'BRASSO_250EC_250ML.jpg', 50400, 48960, 48000, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 315, 1, NULL, 0),
(51, 9, 'QOLS00051', 'Brasso 250 EC 20 X 400 ml', 'BRASSO 250 EC merupakan Insektisida racun kontak dan lambung berbentuk pekatan yang dapat diemulsikan, berwarna merah kecoklatan, untuk mengendalikan hama pada tanaman Kakao, Cabai, dan Kedelai.\nBahan Aktif : Sipermetrin 250 g/l\r\nIsi Bersih: 400 ml\r\n', 'BRASSO_250EC_400ML.jpg', 74550, 72420, 71000, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 511, 1, NULL, 0),
(52, 1, 'QOLS00052', 'Cabrio 250 EC 24 X 250 ml', 'CABRIO 250 EC merupakan Fungisida yang bersifat protektif dan kuratif berbentuk pekatan yang dapat diemulsikan untuk mengendalikan penyakit pada tanaman tomat, kentang dan bawang merah.\nBahan Aktif: Piraklostrobin 250 g/l\r\nIsi Bersih: 250 ml\r\n', 'CABRIO_250EC_250ML.jpg', 202650, 196860, 193000, 26558, 0, 'Pcs', 'Pcs', 'Box', '24', '1', 345.8, 1, NULL, 0),
(53, 1, 'QOLS00053', 'Cabrio 250 EC 48 X 100 ml', 'CABRIO 250 EC merupakan Fungisida yang bersifat protektif dan kuratif berbentuk pekatan yang dapat diemulsikan untuk mengendalikan penyakit pada tanaman tomat, kentang dan bawang merah.\nBahan Aktif: Piraklostrobin 250 g/l\r\nIsi Bersih: 100 ml\r\n', 'CABRIO_250EC_100ML.jpg', 87675, 85170, 83500, 13748, 0, 'Pcs', 'Pcs', 'Box', '48', '1', 162.5, 1, NULL, 0),
(54, 2, 'QOLS00054', 'Calaris 550 SC 10 X 1 ltr', 'Calaris merupakan Herbisida sistemik dan selektif awal purna tumbuh berbentuk pekatan suspensi berwarna coklat muda untuk mengendalikan gulma berdaun lebar, gulma berdaun sempit dan teki-tekian pada pertanaman jagung.\n\r\nBahan aktif : Mesotrion 50 g/l + Atrazin 500 g/l\r\nIsi kemasan : 1 Liter', 'CALARIS_550SC_1LITER.jpg', 278250, 270300, 265000, 80, 0, 'Pcs', 'Pcs', 'Box', '10', '1', 1, 1, NULL, 0),
(55, 2, 'QOLS00055', 'Calaris 550 SC 20 X 250 ml', 'Calaris merupakan Herbisida sistemik dan selektif awal purna tumbuh berbentuk pekatan suspensi berwarna coklat muda untuk mengendalikan gulma berdaun lebar, gulma berdaun sempit dan teki-tekian pada pertanaman jagung.\n\r\nBahan aktif : Mesotrion 50 g/l + Atrazin 500 g/l\r\nIsi kemasan : 250ml', 'CALARIS_550SC_250ML.jpg', 76650, 74460, 73000, 60, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 540, 1, NULL, 0),
(56, 2, 'QOLS00056', 'Calaris 550 SC 20 X 500 ml', 'Calaris merupakan Herbisida sistemik dan selektif awal purna tumbuh berbentuk pekatan suspensi berwarna coklat muda untuk mengendalikan gulma berdaun lebar, gulma berdaun sempit dan teki-tekian pada pertanaman jagung.\n\r\nBahan aktif : Mesotrion 50 g/l + Atrazin 500 g/l\r\nIsi kemasan : 500ml', 'CALARIS_550SC_500ML.jpg', 144900, 140760, 138000, 20, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 1, 1, NULL, 0),
(57, 9, 'QOLS00057', 'Confidor 200 SL 100 X 60 ml', 'Confidor 200 SL Insektisida sistemik racun kontak dan lambung berbentuk larutan dalam air, berwarna coklat jernih, untuk mengendalikan hama pada tanaman apel, cabai, jagung, jeruk, kacang panjang, kapas, kelapa sawit, kentang, ketimun, mangga, padi, semangka, teh, tembakau dan tomat\nBahan aktif : Imidakloprid 200 g/l\r\nIsi Bersih: 60 ml\r\n', 'CONFIDOR_200SL_60ML.jpg', 62738, 60945, 59750, 2264, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 99.2, 1, NULL, 0),
(58, 9, 'QOLS00058', 'Confidor Extra 350 SC 100 X 100 ml', 'CONFIDOR EXTRA® 350 SC Insektisida sistemik yang bekerja secara racun kontak dan lambung berbentuk pekatan suspensi yang larut dalam air berwarna putih untuk mengendalikan hama pada tanaman apel, cabai, jagung, jeruk, kacang panjang, kentang, mangga, mentimun, padi sawah, semangka, teh, tembakau dan tomat.\nBahan aktif : imidakloprid 350 g/l\r\nIsi Bersih: 100 ml\r\n', 'CONFIDOR_EXTRA_100ML.jpg', 98175, 95370, 93500, 1000, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 149.2, 1, NULL, 0),
(59, 2, 'QOLS00059', 'Council Complete SC 300 50 X 100 ml', 'Council Complete® 300 SC Herbisida selektif, berbentuk pekatan suspensi berwarna putih kekuningan, bekerja secara sistemik dan digunakan untuk mengendalikan gulma pada pertanaman padi tanam pindah (TAPIN) dan tanam benih langsung (TABELA).\nBahan aktif : Triafamone 100 g/l + Tefuryltrione 200 g/l\r\nIsi Bersih: 100 ml\r\n', 'COUNCIL_COMPLETE_100ML.jpg', 181125, 175950, 172500, 10449, 0, 'Pcs', 'Pcs', 'Box', '50', '1', 140, 1, NULL, 0),
(60, 2, 'QOLS00060', 'Council Complete SC 300 50 X 50 ml', 'Council Complete® 300 SC Herbisida selektif, berbentuk pekatan suspensi berwarna putih kekuningan, bekerja secara sistemik dan digunakan untuk mengendalikan gulma pada pertanaman padi tanam pindah (TAPIN) dan tanam benih langsung (TABELA).\nBahan aktif : Triafamone 100 g/l + Tefuryltrione 200 g/l\r\nIsi Bersih: 50 ml\r\n', 'COUNCIL_COMPLETE_50ML.jpg', 90300, 87720, 86000, 1000, 0, 'Pcs', 'Pcs', 'Box', '50', '1', 80, 1, NULL, 0),
(61, 9, 'QOLS00061', 'Curacron 500 EC 20 X 500 ml', 'Curacron merupakan Insektisida racun kontak dan lambung, berbentuk pekatan yang dapat diemulsikan, berwarna kuning kecoklat-coklatan, untuk mengendalikan hama pada tanaman bawang merah, cabai, jeruk, kacang hijau, kapas, kentang, kubis, semangka, tebu, tembakau dan tomat.\n\r\nBahan aktif : Profenofos 500 g/l\r\nIsi kemasan : 500ml', 'CURACRON_500EC_500ML.jpg', 143588, 139485, 136750, 6080, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 686, 1, NULL, 0),
(62, 9, 'QOLS00062', 'Curacron 500 EC 40 X 250 ml', 'Curacron merupakan Insektisida racun kontak dan lambung, berbentuk pekatan yang dapat diemulsikan, berwarna kuning kecoklat-coklatan, untuk mengendalikan hama pada tanaman bawang merah, cabai, jeruk, kacang hijau, kapas, kentang, kubis, semangka, tebu, tembakau dan tomat.\n\r\nBahan aktif : Profenofos 500 g/l\r\nIsi kemasan : 250ml', 'CURACRON_500EC_250ML.jpg', 73500, 71400, 70000, 5480, 0, 'Pcs', 'Pcs', 'Box', '40', '1', 356.5, 1, NULL, 0),
(63, 9, 'QOLS00063', 'Curacron 500 EC 50 X 100 ml', 'Curacron merupakan Insektisida racun kontak dan lambung, berbentuk pekatan yang dapat diemulsikan, berwarna kuning kecoklat-coklatan, untuk mengendalikan hama pada tanaman bawang merah, cabai, jeruk, kacang hijau, kapas, kentang, kubis, semangka, tebu, tembakau dan tomat.\n\r\nBahan aktif : Profenofos 500 g/l\r\nIsi kemasan : 100ml', 'CURACRON_500EC_100ML.jpg', 31500, 30600, 30000, 12800, 0, 'Pcs', 'Pcs', 'Box', '50', '1', 150.2, 1, NULL, 0),
