(66, 9, 'QOLS00066', 'Decis 25 EC 100 X 100 ml', 'Decis® 25 EC Insektisida racun kontak dan lambung berbentuk pekatan yang dapat diemulsikan berwarna kuning jernih untuk mengendalikan hama pada tanaman anggrek, apel, bawang merah, belimbing, benih jagung, cabai, jagung, jarak pagar, jeruk, kacang hijau, kacang panjang, kakao, kedelai, kelapa sawit, kentang, ketimun, kopi, kubis, lada, mangga, melon, semangka, teh, tembakau dan tomat.\nBahan aktif : Deltametrin 25 g/ℓ\r\nIsi Bersih: 100 ml\r\n', 'DECIS_25EC_100ML.jpg', 28875, 28050, 27500, 13465, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 126.5, 1, NULL, 0),
(67, 9, 'QOLS00067', 'Decis 25 EC 100 X 50 ml', 'Decis® 25 EC Insektisida racun kontak dan lambung berbentuk pekatan yang dapat diemulsikan berwarna kuning jernih untuk mengendalikan hama pada tanaman anggrek, apel, bawang merah, belimbing, benih jagung, cabai, jagung, jarak pagar, jeruk, kacang hijau, kacang panjang, kakao, kedelai, kelapa sawit, kentang, ketimun, kopi, kubis, lada, mangga, melon, semangka, teh, tembakau dan tomat.\nBahan aktif : Deltametrin 25 g/ℓ\r\nIsi Bersih: 50 ml\r\n', 'DECIS_25EC_50ML.jpg', 15908, 15453, 15150, 11600, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 77.5, 1, NULL, 0),
(68, 9, 'QOLS00068', 'Decis 25 EC 20 X 500 ml', 'Decis® 25 EC Insektisida racun kontak dan lambung berbentuk pekatan yang dapat diemulsikan berwarna kuning jernih untuk mengendalikan hama pada tanaman anggrek, apel, bawang merah, belimbing, benih jagung, cabai, jagung, jarak pagar, jeruk, kacang hijau, kacang panjang, kakao, kedelai, kelapa sawit, kentang, ketimun, kopi, kubis, lada, mangga, melon, semangka, teh, tembakau dan tomat.\nBahan aktif : Deltametrin 25 g/ℓ\r\nIsi Bersih: 500 ml\r\n', 'DECIS_25EC_500ML.jpg', 130988, 127245, 124750, 1319, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 549.5, 1, NULL, 0),
(69, 9, 'QOLS00069', 'Decis 25 EC 40 X 250 ml', 'Decis® 25 EC Insektisida racun kontak dan lambung berbentuk pekatan yang dapat diemulsikan berwarna kuning jernih untuk mengendalikan hama pada tanaman anggrek, apel, bawang merah, belimbing, benih jagung, cabai, jagung, jarak pagar, jeruk, kacang hijau, kacang panjang, kakao, kedelai, kelapa sawit, kentang, ketimun, kopi, kubis, lada, mangga, melon, semangka, teh, tembakau dan tomat.\nBahan aktif : Deltametrin 25 g/ℓ\r\nIsi Bersih: 250 ml\r\n', 'DECIS_25EC_250ML.jpg', 70613, 68595, 67250, 2478, 0, 'Pcs', 'Pcs', 'Box', '40', '1', 301.75, 1, NULL, 0),
(70, 9, 'QOLS00070', 'Elestal Neo 54 WG 100 X 30 gr', 'Elestal Neo merupakan Insektisida racun kontak dan lambung berbentuk butiran yang dapat didispersikan dalam air yang bekerja dengan menghambat biosintesa lemak dan menyebabkan serangga menjadi lumpuh, berwarna coklat muda untuk mengendalikan hama di tanaman cabai dan tomat.  \n\r\nBahan aktif : Spiropidion 30% + acetamiprid 24%\r\nIsi kemasan : 30 Gram', 'ESTAL_NEO_30GRAM.jpg', 99750, 96900, 95000, 1000, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 176, 1, NULL, 0),
(71, 9, 'QOLS00071', 'Elestal Neo 54 WG 20 X 150 gr', 'Elestal Neo merupakan Insektisida racun kontak dan lambung berbentuk butiran yang dapat didispersikan dalam air yang bekerja dengan menghambat biosintesa lemak dan menyebabkan serangga menjadi lumpuh, berwarna coklat muda untuk mengendalikan hama di tanaman cabai dan tomat.  \n\r\nBahan aktif : Spiropidion 30% + acetamiprid 24%\r\nIsi kemasan : 150 Gram', 'ESTAL_NEO_150GRAM.jpg', 425250, 413100, 405000, 1000, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 640, 1, NULL, 0),
(72, 20, 'QOLS00072', 'Ethrel 480 SL 100 X 100 ml', 'ETHREL 480 SL merupakan zat pengatur tumbuh tanaman berbentuk larutan dalam air yang berwarna coklat jernih digunakan sebagai zat pengatur tumbuh tanaman pada tanaman Apel, Kedelai, Kopi, Nenas, Pisang, dan Tembakau\nBahan aktif : Etefon 480 g/l\r\nIsi Bersih: 100 ml\r\n', 'ETHREL_480SL_100ML.jpg', 44625, 43350, 42500, 3100, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 156.5, 1, NULL, 0),
(73, 9, 'QOLS00073', 'Fenval 200 EC 15 X 1 ltr', 'FENVAL 200 g/l merupakan Insektisida racun kontak dan lambung, berbentuk pekatan yang dapat diemulsikan, berwarna coklat kemerahan, untuk mengendalikan hama pada tanaman Bawang Merah, Cabai, Jeruk, Kakao, Kapas, Kedelai, Kelapa Sawit, Kubis, Teh, Tembakau dan Tomat.\nBahan Aktif: Fenvalerat 200 g/l\r\nIsi Bersih: 1 Liter\r\n', 'FENVAL_200EC_1LITER.jpg', 142800, 138720, 136000, 2185, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 1, 1, NULL, 0),
(74, 9, 'QOLS00074', 'Fenval 200 EC 20 X 250 ml', 'FENVAL 200 g/l merupakan Insektisida racun kontak dan lambung, berbentuk pekatan yang dapat diemulsikan, berwarna coklat kemerahan, untuk mengendalikan hama pada tanaman Bawang Merah, Cabai, Jeruk, Kakao, Kapas, Kedelai, Kelapa Sawit, Kubis, Teh, Tembakau dan Tomat.\nBahan Aktif: Fenvalerat 200 g/l\r\nIsi Bersih: 250 ml\r\n', 'FENVAL_200EC_250ML.jpg', 35700, 34680, 34000, 3175, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 315, 1, NULL, 0),
(75, 9, 'QOLS00075', 'Fenval 200 EC 20 X 500 ml', 'FENVAL 200 g/l merupakan Insektisida racun kontak dan lambung, berbentuk pekatan yang dapat diemulsikan, berwarna coklat kemerahan, untuk mengendalikan hama pada tanaman Bawang Merah, Cabai, Jeruk, Kakao, Kapas, Kedelai, Kelapa Sawit, Kubis, Teh, Tembakau dan Tomat.\nBahan Aktif: Fenvalerat 200 g/l\r\nIsi Bersih: 500 ml\r\n', 'FENVAL_200EC_500ML.jpg', 73500, 71400, 70000, 19944, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 589, 1, NULL, 0),
(76, 9, 'QOLS00076', 'Fenval 200 EC 50 X 100 ml', 'FENVAL 200 g/l merupakan Insektisida racun kontak dan lambung, berbentuk pekatan yang dapat diemulsikan, berwarna coklat kemerahan, untuk mengendalikan hama pada tanaman Bawang Merah, Cabai, Jeruk, Kakao, Kapas, Kedelai, Kelapa Sawit, Kubis, Teh, Tembakau dan Tomat.\nBahan Aktif: Fenvalerat 200 g/l\r\nIsi Bersih: 100 ml\r\n', 'FENVAL_200EC_100ML.jpg', 15750, 15300, 15000, 4689, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 134.6, 1, NULL, 0),
(77, 1, 'QOLS00077', 'Filia 525 SE 100 X 50 ml', 'Filia merupakan fungisida protektif untuk mengendalikan penyakit blas Pyricularia oryzae pada tanaman padi. Dengan kombinasi dua bahan aktif pilihan yang do formulasi secara tepat, maka Filia 525 SE tidak saja mengendalikan penyakit blas yang sering terjadi pada tanaman padi seperti Ustilago, hawar pelepah, \"dirty panicle\" pada bulir tetapi juga membuat batang lebih kuat, enampilan daun dan tamana padi lebih hijau dan memberikan peningkatan hasil yang signfikan. Filia 525 SE juga dapat digunakan pada tanaman bawang merah untuk mengendalikan penyakit dan meningkatkan kualitas umbi serta hasil panen.\n\r\nBahan aktif : Trisiklazol 400 g/l + Propikonazol 125 g/l\r\nIsi kemasan : 50ml', 'FILIA_525SE_50ML.jpg', 30713, 29835, 29250, 11767, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 81.3, 1, NULL, 0),
(78, 1, 'QOLS00078', 'Filia 525 SE 20 X 250 ml', 'Filia merupakan fungisida protektif untuk mengendalikan penyakit blas Pyricularia oryzae pada tanaman padi. Dengan kombinasi dua bahan aktif pilihan yang do formulasi secara tepat, maka Filia 525 SE tidak saja mengendalikan penyakit blas yang sering terjadi pada tanaman padi seperti Ustilago, hawar pelepah, \"dirty panicle\" pada bulir tetapi juga membuat batang lebih kuat, enampilan daun dan tamana padi lebih hijau dan memberikan peningkatan hasil yang signfikan. Filia 525 SE juga dapat digunakan pada tanaman bawang merah untuk mengendalikan penyakit dan meningkatkan kualitas umbi serta hasil panen.\n\r\nBahan aktif : Trisiklazol 400 g/l + Propikonazol 125 g/l\r\nIsi kemasan : 250ml', 'FILIA_525SE_250ML.jpg', 133875, 130050, 127500, 22880, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 354.5, 1, NULL, 0),
(79, 1, 'QOLS00079', 'Folirfos 400 SL 15 X 1 ltr', 'Folirfos 400 SL merupakan Fungisida sistemik untuk mengendalikan penyakit yang disebabkan oleh jamur pada tanaman anggur, bawang merah, jeruk, kakao, kelapa, kentang, lada, nanas, padi, dan tomat\nBahan Aktif: Asam fosfit 400 g/l\r\nIsi Bersih: 1 Liter\r\n', 'FOLIRFOS_400SL_1LITER.jpg', 99750, 96900, 95000, 1075, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 1, 1, NULL, 0),
(80, 1, 'QOLS00080', 'Folirfos 400 SL 20 X 500 ml', 'Folirfos 400 SL merupakan Fungisida sistemik untuk mengendalikan penyakit yang disebabkan oleh jamur pada tanaman anggur, bawang merah, jeruk, kakao, kelapa, kentang, lada, nanas, padi, dan tomat\nBahan Aktif: Asam fosfit 400 g/l\r\nIsi Bersih: 500 ml\r\n', 'FOLIRFOS_400SL_500ML.jpg', 55125, 53550, 52500, 305, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 783, 1, NULL, 0),
(81, 1, 'QOLS00081', 'Folirfos 400 SL 4 X 5 ltr', 'Folirfos 400 SL merupakan Fungisida sistemik untuk mengendalikan penyakit yang disebabkan oleh jamur pada tanaman anggur, bawang merah, jeruk, kakao, kelapa, kentang, lada, nanas, padi, dan tomat\nBahan Aktif: Asam fosfit 400 g/l\r\nIsi Bersih: 5 Liter\r\n', 'FOLIRFOS_400SL_5LITER.jpg', 472500, 459000, 450000, 1000, 0, 'Pcs', 'Pcs', 'Box', '4', '1', 6, 1, NULL, 0),
(82, 19, 'QOLS00082', 'Forsil 20 X 250 ml', 'FORSIL merupakan pupuk mikro majemuk an-organik yang dapat terlarut sempurnadalam air. Forsil yang diperkaya silika yang dapat meningkatkan kualitas dan hasilpanen, selain itu juga berfungsi sebagai Biostimulant yang dapat melindungi tanaman dari serangan hama dan penyakit, kekeringan, serta perubahan cuaca\nKandungan Hara: Silika (SiO2) 20%, Seng (Zn) 0,25%, Molibdenum (Mo) 0,001%\r\nIsi Bersih: 250 ml\r\n', 'FORSIL_250ML.jpg', 58800, 57120, 56000, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 400, 1, NULL, 0),
(83, 19, 'QOLS00083', 'Forsil 20 X 500 ml', 'FORSIL merupakan pupuk mikro majemuk an-organik yang dapat terlarut sempurnadalam air. Forsil yang diperkaya silika yang dapat meningkatkan kualitas dan hasilpanen, selain itu juga berfungsi sebagai Biostimulant yang dapat melindungi tanaman dari serangan hama dan penyakit, kekeringan, serta perubahan cuaca\nKandungan Hara: Silika (SiO2) 20%, Seng (Zn) 0,25%, Molibdenum (Mo) 0,001%\r\nIsi Bersih: 500 ml\r\n', 'FORSIL_500ML.jpg', 108675, 105570, 103500, 115, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 765, 1, NULL, 0),
(84, 1, 'QOLS00084', 'Insure Max 510 FS 100 X 25 ml', 'INSURE MAX 510 FS merupakan Fungisida sistemik yang bersifat protektif dan kuratif berbentuk pekatan suspensi berwarna merah muda digunakan untuk mengendalikan penyakit Bulai pada tanaman Jagung.\nBahan Aktif: Dimetomorf 500 g/l & Piraklostrobin 10 g/l\r\nIsi Bersih: 25 ml\r\n', 'INSURE_MAX_25ML.jpg', 35700, 34680, 34000, 1000, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 49.1, 1, NULL, 0),
(85, 14, 'QOLS00085', 'Jagung ADV 132 20 X 1 kg', 'Jagung ADV 132 adalah benih jagung hibrida yang diproduksi oleh perusahaan Advanta Seeds Indonesia dengan nama produk ADV Montok. Benih ini dikenal karena toleransinya terhadap penyakit bulai dan rendemennya yang sangat tinggi. Tipe persilangan: Hibrida silang tunggal.Batang: Kokoh dan tahan dari kerobohan.Pengakaran: Dalam, memberikan stabilitas pada tanaman.Toleransi penyakit: Sangat toleran terhadap penyakit bulai dan busuk batang.Tongkol: Montok, terisi penuh hingga ujung, dan kelobot menutup dengan sempurna, sehingga tidak mudah busuk.Hasil panen: Rendemennya sangat tinggi, mencapai kurang lebih 85%.\nIsi Bersih: 1 Kilogram\r\n', 'JAGUNG_ADV_132_1KG.jpg', 93450, 90780, 89000, 101, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 1, 1, NULL, 0),
(86, 14, 'QOLS00086', 'Jagung DK 771 20 X 1 kg (Bayer)', 'Benih Jagung Hibrida Dekalb 771 Produksinya tinggi, juga tahan terhadap serangan penyakit bulai dan mampu menghasilkan jagung dengan tongkol lebih panjang dan besar. Benih jagung ini juga mudah ditanam di lahan datar, lereng gunung, ataupun di lahan-lahan marginal lainnya.\nIsi Bersih: 1 Kilogram\r\n', 'JAGUNG_DK771_1KG.jpg', 85050, 82620, 81000, 1000, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 1, 1, NULL, 0),
(87, 14, 'QOLS00087', 'Jagung DK 9209C 20 X 1 kg (Bayer)', 'Jagung DK 9209C adalah benih jagung hibrida dari Bayer dengan keunggulan ketahanan terhadap penyakit bulai dan busuk batang, adaptasi luas di berbagai kondisi tanah, serta potensi hasil yang tinggi hingga 15,2 ton per hektare pipil kering, sehingga cocok untuk meningkatkan produktivitas petani. Benih ini menghasilkan tongkol yang besar dengan biji yang rapat dan dapat dipanen pada berbagai usia.\nIsi Bersih: 1 Kilogram\r\n', 'JAGUNG_DK9209C_1KG.jpg', 107100, 104040, 102000, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 1, 1, NULL, 0),
(88, 14, 'QOLS00088', 'Jagung DK 95R 20 X 1 kg', 'DEKALB DK95R adalah Jagung Bioteknologi Tahan Roundup (glifosat), memungkinkan penggunaan herbisida berbasis glifosat tanpa merusak tanaman jagung.\nKeunggulan:\r\n- Tahan Herbisida Glyphosate: Mengurangi gulma secara efisien tanpa merusak tanaman.\r\n- Hasil Panen Tinggi: Teruji di lahan petani dengan produktivitas tinggi.\r\n- Kualitas Benih Terjamin: Diproduksi oleh Bayer, perusahaan global terpercaya di bidang pertanian.\r\n- Efisiensi Biaya: Mengurangi kebutuhan tenaga kerja dan biaya penyiangan manual.\r\n- Cocok untuk Wilayah Tropis: Telah diuji dan terbukti adaptif untuk kondisi Indonesia.\r\nIsi Bersih: 1 Kilogram\r\n', 'JAGUNG_DK95R_1KG.jpg', 120000, 115000, 110000, 751, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 1, 1, NULL, 0),
(89, 14, 'QOLS00089', 'Jagung NK 212 20 X 1 kg', 'NK212 memiliki kemampuan beradaptasi di lahan tadah hujan (tegalan) dan lahan sawah dengan kondisi tanah yang marjinal serta kekurangan air. NK 212 adalah jagung yang mempunyai pertumbuhan awal sangat bagus, warna oranye, dan pengisian penuh. Serta benih jagung ini juga mudah beradptasi di berbagai kondisi lahan.\nPotensi Hasil: 10,8 Ton/Ha pipilan kering.\r\nRata-Rata Hasil: 9,5 Ton/Ha pipilan kering.\r\nUmur Panen: ± 101 HST\r\nKemasan: 1 kilogram', 'JAGUNG_NK212_1KG.jpg', 86625, 84150, 82500, 111400, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 1, 1, NULL, 0),
(90, 14, 'QOLS00090', 'Jagung NK 212 BTGT 20 X 1 kg', 'NK212s | NK Pendekar Sakti adalah benih Jagung Hibrida Bioteknologi NK212s-Bt11GA21 yang sudah ditambahkan dengan beberapa kesaktian. NK Pendekar Sakti memiliki kesaktian (toleran) terhadap penyemprotan herbisida glyphosate murni dan juga sakti (tahan) terhadap serangan hama penggerek batang-Asian Corn Borer. Kesaktian yang dimiliki NK Pendekar Sakti menawarkan budidaya tanaman jagung yang lebih mudah dan murah, serta pastinya meningkatkan hasil bagi petani.\nPotensi Hasil: 11,8 Ton/Ha (KA 15%).\r\nRata-Rata Hasil: 9,0 Ton/Ha (KA 15%).\r\n Umur Panen: ± 103 HST\r\nKemasan: 1 Kilogram\r\n', 'JAGUNG_NK212_SAKTI_1KG.jpg', 111300, 108120, 106000, 177420, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 1, 1, NULL, 0),
(91, 14, 'QOLS00091', 'Jagung NK 7202 20 X 1 kg', 'NK7202 | NK JUARA memiliki kemampuan beradaptasi di lahan sawah. Benih NK Juara dapat ditanam oleh petani yang mempunyai masalah endemik penyakit bulai dan busuk batang, karena benih ini memiliki ketahanan terhadap penyakit tersebut. Selain itu benih ini juga memiliki potensi hasil yang tinggi, sehingga membuat petani aman dan menguntungkan dengan hasil tanam jagungnya.\nPotensi Hasil: 12,9 Ton/Ha.\r\nRata-Rata Hasil: 10,7 Ton/Ha.\r\nUmur Panen: ± 107 HST \r\nKemasan: 1 Kilogram\r\n', 'JAGUNG_NK7202_JUARA_1KG.jpg', 101325, 98430, 96500, 1000, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 1, 1, NULL, 0),
(92, 14, 'QOLS00092', 'Jagung NK 7328 20 X 1 kg', 'NK7328 | NK SUMO memiliki kemampuan beradaptasi di lahan tadah hujan (tegalan) dan untuk petani progressive. Benih ini memiliki tanaman yang Sumo dengan hasil yang Sumo. Petani tidak perlu khawatir tanaman rebah karena batang yang kokoh, serta pertumbuhan tanaman yang menarik yang disukai oleh petani jagung Indonesia.\nPotensi Hasil: 12,4 Ton/Ha (KA 15%). \r\nRata-Rata Hasil: 9,9 Ton/Ha (KA 15%). \r\nUmur Panen: ± 115 HST\r\nKemasan: 1 Kilogram\r\n', 'JAGUNG_NK7328_1KG.jpg', 119175, 115770, 113500, 277320, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 1, 1, NULL, 0),
(93, 14, 'QOLS00093', 'Jagung NK 7328 BTGT 20 X 1 kg', 'NK7328s | NK Sumo Sakti adalah benih Jagung Hibrida Bioteknologi NK7328s-Bt11GA21 dengan performa tanaman yang disukai petani, berbatang Kokoh, dan juga memiliki kesaktian tambahan dari varietas NK Sumo sebelumnya. Kesaktian yang dimiliki oleh NK Sumo Sakti adalah ketahanan terhadap penyemprotan herbisida jenis Glyphosate murni dan juga ketahanan terhadap serangan hama penggerek batang (Asian Corn Borer). Petani akan lebih mudah dalam membudidayakan jagung hibrida, lebih sedikit menggunakan pestisida untuk perawatan tanaman sehingga lebih menguntungkan, dan tentunya meningkatkan hasil bagi petani.\nPotensi Hasil: 11.5 Ton/Ha (KA 15%). \r\nRata-Rata Hasil: 9.0 Ton/Ha (KA 15%) \r\nUmur Panen: ± 105 HST\r\nKemasan: 1 Kilogram\r\n', 'NK_SUMO_7328_SAKTI_1KG.jpg', 140175, 136170, 133500, 19120, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 1, 1, NULL, 0),
(94, 14, 'QOLS00094', 'Kubis Hibrida F1 Kaelo 30 X 15 gr', 'Kubis Hibrida F1 Kaelo adalah varietas kubis produk Seminis yang cocok untuk dataran rendah-menengah, memiliki umur panen genjah (sekitar 50-65 HST), menghasilkan krop bulat pipih, keras, dan padat dengan berat 1,5-2,5 kg, serta tahan penyakit akar gada, bercak daun, dan jamur. Kubis ini memiliki kemampuan adaptasi luas, tahan cuaca panas, dan cocok untuk pengangkutan jarak jauh karena tidak mudah pecah.\nIsi Bersih: 15 Gram\r\n', 'KUBIS_KAELO_15GRAM.jpg', 90300, 87720, 86000, 3000, 0, 'Pcs', 'Pcs', 'Box', '30', '1', 17, 1, NULL, 0),
(95, 1, 'QOLS00095', 'Luna Smart 250/250 SC 100 X 100 ml', 'Fungisida yang bersifat preventif, kuratif dan sistemik berbentuk pekatan suspensi yang larut dalam air berwarna putih keabu-abuan untuk mengendalikan penyakit-penyakit pada tanaman apel, bawang merah, cabai, jeruk, kakao, kentang, mangga, semangka dan tomat\nBahan aktif : Fluopiram 250 g/l + Trifloksistrobin 250 g/l\r\nIsi Bersih: 100 ml\r\n', 'LUNA_SMART_100ML.jpg', 142275, 138210, 135500, 1000, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 151.5, 1, NULL, 0),
(96, 1, 'QOLS00096', 'Luna Smart 250/250 SC 50 X 100 ml', 'Fungisida yang bersifat preventif, kuratif dan sistemik berbentuk pekatan suspensi yang larut dalam air berwarna putih keabu-abuan untuk mengendalikan penyakit-penyakit pada tanaman apel, bawang merah, cabai, jeruk, kakao, kentang, mangga, semangka dan tomat\nBahan aktif : Fluopiram 250 g/l + Trifloksistrobin 250 g/l\r\nIsi Bersih: 100 ml\r\n', 'LUNA_SMART_100ML.jpg', 142275, 138210, 135500, 1000, 0, 'Pcs', 'Pcs', 'Box', '50', '1', 77, 1, NULL, 0);
INSERT INTO `products` (`id`, `category_id`, `sku`, `name`, `description`, `picture_name`, `price`, `price_3`, `price_2`, `stock`, `current_discount`, `product_unit`, `product_unit_1`, `product_unit_2`, `product_unit_value`, `product_type`, `product_unit_weight`, `is_available`, `add_date`, `user_level`) VALUES
(97, 9, 'QOLS00097', 'Matador 25 EC 100 X 50 ml', 'Matador merupakan Insektisida racun kontak dan lambung, berbentuk pekatan yang dapat diemulsikan, berwarna kuning jerami jernih untuk mengendalikan hama-hama pada tanaman bawang merah, bawang putih, cabai, jagung, jeruk, kacang panjang, kakao, kapas, kedelai, kelapa sawit, kubis, lada, lamtoro, mangga, teh, tembakau dan tomat. \nBahan Aktif:\r\n25 g/l lamda sihalotrin\r\nIsi Bersih: 50 ml\r\n', 'MATADOR_25EC_50ML.jpg', 16485, 16014, 15700, 7000, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 67.1, 1, NULL, 0),
(98, 9, 'QOLS00098', 'Matador 25 EC 100 X 80 ml', 'Matador merupakan Insektisida racun kontak dan lambung, berbentuk pekatan yang dapat diemulsikan, berwarna kuning jerami jernih untuk mengendalikan hama-hama pada tanaman bawang merah, bawang putih, cabai, jagung, jeruk, kacang panjang, kakao, kapas, kedelai, kelapa sawit, kubis, lada, lamtoro, mangga, teh, tembakau dan tomat. \nBahan Aktif:\r\n25 g/l lamda sihalotrin\r\nIsi Bersih: 80 ml\r\n', 'MATADOR_25EC_80ML.jpg', 23363, 22695, 22250, 1170, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 102.8, 1, NULL, 0),
(99, 9, 'QOLS00099', 'Matador 25 EC 40 X 250 ml', 'Matador merupakan Insektisida racun kontak dan lambung, berbentuk pekatan yang dapat diemulsikan, berwarna kuning jerami jernih untuk mengendalikan hama-hama pada tanaman bawang merah, bawang putih, cabai, jagung, jeruk, kacang panjang, kakao, kapas, kedelai, kelapa sawit, kubis, lada, lamtoro, mangga, teh, tembakau dan tomat. \nBahan Aktif:\r\n25 g/l lamda sihalotrin\r\nIsi Bersih: 250 ml\r\n', 'MATADOR_25EC_250ML.jpg', 65888, 64005, 62750, 2200, 0, 'Pcs', 'Pcs', 'Box', '40', '1', 285.8, 1, NULL, 0),
(100, 1, 'QOLS00100', 'Melyra 200/200 SC 24 X 250 ml', 'Fungisida Melyra® 200/200SC merupakan fungisida dengan 2 bahan aktif Mefentrifluconazole 200g/l dan Piraklostrobin 200g/l untuk perlindungan tanaman jagung terhadap penyakit yang diakibatkan jamur secara lebih efektif dan meningkatkan hasil panen lebih maksimal.\nBahan Aktif: Mefentriflukonazol 200 g/L + Piraklostrobin 200 g/L\r\nIsi Bersih: 250 ml\r\n', 'MELYRA_250ML.jpg', 250000, 240000, 232500, 91, 0, 'Pcs', 'Pcs', 'Box', '24', '1', 345.8, 1, NULL, 0),
(101, 9, 'QOLS00101', 'Metindo 25 WP 10 X 10 X 100 gr', 'METINDO 25 WP merupakan Insektisida racun kontak dan lambung, berbentuk tepung yang dapat disuspensikan, berwarna putih sampai krem, untuk mengendalikan hama pada tanaman Bawang Merah, Cabai, Kedelai, dan Tembakau.\nBahan Aktif: Metomil 25%\r\nIsi Bersih: 100 ml\r\n', 'METINDO_25WP_100GRAM.jpg', 15750, 15300, 15000, 14300, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 116.5, 1, NULL, 0),
(102, 9, 'QOLS00102', 'Metindo 25 WP 40 X 250 gr', 'METINDO 25 WP merupakan Insektisida racun kontak dan lambung, berbentuk tepung yang dapat disuspensikan, berwarna putih sampai krem, untuk mengendalikan hama pada tanaman Bawang Merah, Cabai, Kedelai, dan Tembakau.\nBahan Aktif: Metomil 25%\r\nIsi Bersih: 250 ml\r\n', 'METINDO_25WP_250GRAM.jpg', 38063, 36975, 36250, 20202, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 300, 1, NULL, 0),
(103, 9, 'QOLS00103', 'Metindo 25 WP 40 X 500 gr', 'METINDO 25 WP merupakan Insektisida racun kontak dan lambung, berbentuk tepung yang dapat disuspensikan, berwarna putih sampai krem, untuk mengendalikan hama pada tanaman Bawang Merah, Cabai, Kedelai, dan Tembakau.\nBahan Aktif: Metomil 25%\r\nIsi Bersih: 500 ml\r\n', 'METINDO_25WP_500GRAM.jpg', 71925, 69870, 68500, 7786, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 603, 1, NULL, 0),
(104, 9, 'QOLS00104', 'Metindo 40 SP 10 X 10 X 100 gr', 'METINDO 40 SP adalah pestisida berjenis insektisida sistemik racun kontak dan lambung berbentuk tepung yang dapat larut dalam air. Termasuk keluarga karbamat yang memiliki spektrum pengendalian hama yang luas, yang utamanya sangat efektif untuk mengendalikan segala jenis ulat.\nBahan aktif: Metomil 40%\r\nIsi Bersih: 100 gr', 'METINDO_40SP_100GRAM.jpg', 23888, 23205, 22750, 21129, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 116.5, 1, NULL, 0),
(105, 9, 'QOLS00105', 'Metindo 40 SP 20 X 800 gr', 'METINDO 40 SP adalah pestisida berjenis insektisida sistemik racun kontak dan lambung berbentuk tepung yang dapat larut dalam air. Termasuk keluarga karbamat yang memiliki spektrum pengendalian hama yang luas, yang utamanya sangat efektif untuk mengendalikan segala jenis ulat.\nBahan aktif: Metomil 40%\r\nIsi Bersih: 800 gr', 'METINDO_40SP_800GRAM.jpg', 168000, 163200, 160000, 1000, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 1, 1, NULL, 0),
(106, 9, 'QOLS00106', 'Metindo 40 SP 40 X 200 gr', 'METINDO 40 SP adalah pestisida berjenis insektisida sistemik racun kontak dan lambung berbentuk tepung yang dapat larut dalam air. Termasuk keluarga karbamat yang memiliki spektrum pengendalian hama yang luas, yang utamanya sangat efektif untuk mengendalikan segala jenis ulat.\nBahan aktif: Metomil 40%\r\nIsi Bersih: 200 gr\r\n', 'METINDO_40SP_200GRAM.jpg', 45413, 44115, 43250, 24421, 0, 'Pcs', 'Pcs', 'Box', '40', '1', 257.5, 1, NULL, 0),
(107, 9, 'QOLS00107', 'Metindo 40 SP 40 X 400 gr', 'METINDO 40 SP adalah pestisida berjenis insektisida sistemik racun kontak dan lambung berbentuk tepung yang dapat larut dalam air. Termasuk keluarga karbamat yang memiliki spektrum pengendalian hama yang luas, yang utamanya sangat efektif untuk mengendalikan segala jenis ulat.\nBahan aktif: Metomil 40%\r\nIsi Bersih: 400 gr', 'METINDO_40SP_400GRAM.jpg', 89250, 86700, 85000, 12729, 0, 'Pcs', 'Pcs', 'Box', '40', '1', 467.75, 1, NULL, 0),
(108, 2, 'QOLS00108', 'Metsulindo Plus 80 WP 8 X 25 X 40 gr', 'Herbisida sistemik selektif pra tumbuh dan purna tumbuh, berbentuk tepung yang dapat disuspensikan, berwarna putih sampai krem untuk mengendalikan gulma berdaun lebar dan teki pada pertanaman padi sawah.\r\nBahan Aktif: 2,4-D natrium 76% (setara dengan 2,4-D 69%), metil metsulfuron 2%, etil klorimuron 2%\r\nIsi Bersih: 40 gram\r\n', 'METSULINDO_PLUS_40GRAM.jpg', 9030, 8772, 8600, 713978, 0, 'Pcs', 'Pcs', 'Box', '200', '1', 55, 1, NULL, 0),
(109, 9, 'QOLS00109', 'Minecto Xtra 200/200 SC 100 X 50 ml', 'Minecto Xtra merupakan Insektisida racun kontak, lambung dan penghambat pertumbuhan serangga berbentuk pekatan suspensi, berwarna putih, untuk mengendalikan hama pada cabai, jagung, dan tomat. \nBahan Aktif: 200 g/l lufenuron +200 g/l\" siantraniliprol\"\r\nKemasan : 50 ml\r\n', 'MINECTO_XTRA_50ML.jpg', 120750, 117300, 115000, 503, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 1, 1, NULL, 0),
(110, 9, 'QOLS00110', 'Minecto Xtra 200/200 SC 50 X 100 ml', 'Minecto Xtra merupakan Insektisida racun kontak, lambung dan penghambat pertumbuhan serangga berbentuk pekatan suspensi, berwarna putih, untuk mengendalikan hama pada cabai, jagung, dan tomat. \nBahan Aktif: 200 g/l lufenuron +200 g/l\" siantraniliprol\"\r\nKemasan : 100 ml\r\n', 'MINECTO_XTRA_100ML.jpg', 243600, 236640, 232000, 3150, 0, 'Pcs', 'Pcs', 'Box', '50', '1', 150, 1, NULL, 0),
(111, 9, 'QOLS00111', 'Mition 500 EC 15 X 1 ltr', 'Mition 500 EC Insektisida racun kontak dan lambung, berbentuk pekatan yang dapat diemulsikan, berwarna kuning, untuk mengendalikan hama pada tanaman cabai.\nBahan Aktif: etion 500 g/l\r\nIsi Bersih: 1 Liter\r\n', 'MITION_500EC_1LITER.jpg', 246750, 239700, 235000, 1285, 0, 'Pcs', 'Pcs', 'Box', '15', '1', 1, 1, NULL, 0),
(112, 9, 'QOLS00112', 'Mition 500 EC 20 X 500 ml', 'Mition 500 EC Insektisida racun kontak dan lambung, berbentuk pekatan yang dapat diemulsikan, berwarna kuning, untuk mengendalikan hama pada tanaman cabai.\nBahan Aktif: etion 500 g/l\r\nIsi Bersih: 500 ml\r\n', 'MITION_500EC_500ML.jpg', 126000, 122400, 120000, 2779, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 640, 1, NULL, 0),
(113, 9, 'QOLS00113', 'Movento Energy 240 SC 50 X 100 ml', 'Movento Energy 240 SC Insektisida sistemik racun kontak dan lambung berbentuk pekatan suspensi putih keabu-abuan untuk mengendalikan hama pada tanaman apel, bawang merah, cabai, jambu biji, jeruk, kentang, kopi, kubis, mangga, melon, rambutan, semangka, tembakau dan tomat\nBahan aktif : Imidakloprid 120 g/ℓ + Spirotetramat 120 g/ℓ\r\nIsi Bersih: 100 ml\r\n', 'MOVENTO_ENERGY_100ML.jpg', 110775, 107610, 105500, 1000, 0, 'Pcs', 'Pcs', 'Box', '50', '1', 152, 1, NULL, 0),
(114, 1, 'QOLS00114', 'Nativo 75 WG 16 X 20 X 12.5 gr', 'Nativo® adalah fungisida sistemik yang bersifat protektif, preventif, kuratif dan eradikatif berbentuk butiran yang dapat didispersikan dalam air berwarna putih untuk mengendalikan penyakit pada tanaman anggrek, apel, bawang merah, cabai, jagung, jeruk, kacang hijau, kacang tanah, kacang panjang, kakao, karet, krisan, kedelai, kopi, mangga, melon, mentimun, padi, pembibitan kelapa sawit, pisang, semangka, teh, tembakau, dan tomat.\nBahan aktif : Trifloksistrobin 25%  + Tebukonazol 50%\r\nIsi Bersih: 12.5 gr\r\n', 'NATIVO_75WP_12,5GRAM.jpg', 17850, 17340, 17000, 24210, 0, 'Pcs', 'Pcs', 'Box', '320', '1', 18.8, 1, NULL, 0),
(115, 9, 'QOLS00115', 'Nemaguard 10 GR 10 X 1 kg', 'NEMAGUARD 10 GR Insektisida racun kontak dan lambung, berbentuk butiran, berwarna hijau, untuk mengendalikan hama ulat tanah Agrotis ipsilon pada tanaman kentang.\nBahan Aktif: oksamil 10 %\r\nIsi Bersih: 1 Kilogram\r\n', 'NEMAGUARD_10GR_1KG.jpg', 92400, 89760, 88000, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 1, 1, NULL, 0),
(116, 9, 'QOLS00116', 'Nemaguard 10 GR 20 X 500 gr', 'NEMAGUARD 10 GR Insektisida racun kontak dan lambung, berbentuk butiran, berwarna hijau, untuk mengendalikan hama ulat tanah Agrotis ipsilon pada tanaman kentang.\nBahan Aktif: oksamil 10 %\r\nIsi Bersih: 500 Gram\r\n', 'NEMAGUARD_10GR_500GRAM.jpg', 49875, 48450, 47500, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 1, 1, NULL, 0),
(117, 2, 'QOLS00117', 'Neocron 80 OL 15 X 1 ltr', 'Herbisida selektif purna tumbuh berbentuk larutan dalam minyak berwarna putih untuk mengendalikan gulma berdaun lebar dan gulma berdaun sempit pada pertanaman jagung.\nBahan Aktif: nikosulfuron 80 g/l\r\nIsi Bersih: 1 Liter', 'NEOCRON_80OL_1LITER.jpg', 341250, 331500, 325000, 20585, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 1, 1, NULL, 0),
(118, 2, 'QOLS00118', 'Neocron 80 OL 20 X 250 ml', 'Herbisida selektif purna tumbuh berbentuk larutan dalam minyak berwarna putih untuk mengendalikan gulma berdaun lebar dan gulma berdaun sempit pada pertanaman jagung.\nBahan Aktif: nikosulfuron 80 g/l\r\nIsi Bersih: 250 ml', 'NEOCRON_80OL_250ML.jpg', 90825, 88230, 86500, 8605, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 327.5, 1, NULL, 0),
(119, 2, 'QOLS00119', 'Neocron 80 OL 20 X 500 ml', 'Herbisida selektif purna tumbuh berbentuk larutan dalam minyak berwarna putih untuk mengendalikan gulma berdaun lebar dan gulma berdaun sempit pada pertanaman jagung.\nBahan Aktif: nikosulfuron 80 g/l\r\nIsi Bersih: 500 ml\r\n', 'NEOCRON_80OL_500ML.jpg', 173250, 168300, 165000, 19815, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 612.5, 1, NULL, 0),
(120, 1, 'QOLS00120', 'Orondis Opti 6/400 SC 20 X 500 ml', 'Orondis Opti merupakan Fungisida sistemik yang berbentuk pekatan suspensi, berwarna putih untuk mengendalikan penyakit pada tanaman melon, semangka, timun dan tomat.\nBahan Aktif: 400 g/lklorotalonil + 6 g/l\"oksatiapiprolin\"\r\nKemasan : 500 ml\r\n', 'ORONDIS_OPTI_500ML.jpg', 168000, 163200, 160000, 4080, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 1, 1, NULL, 0),
(121, 2, 'QOLS00121', 'Paket Convey 336 SC 10 X 40 ml', 'Convey® adalah herbisida sistemik purna tumbuh berbentuk pekatan suspensi berwarna cokelat muda yang aman untuk tanaman dan fleksibel dalam waktu aplikasinya dibanding dengan herbisida sejenis, sehingga melindungi lebih lama.\nBahan Aktif: Topramezon 336g/l\r\nIsi Bersih: 40 ml\r\n', '-', 343350, 333540, 327000, 7287, 0, 'Pcs', 'Pcs', 'Box', '10', '1', 1, 1, NULL, 0),
(122, 2, 'QOLS00122', 'Paket Convey 336 SC 20 X 20 ml', 'Convey® adalah herbisida sistemik purna tumbuh berbentuk pekatan suspensi berwarna cokelat muda yang aman untuk tanaman dan fleksibel dalam waktu aplikasinya dibanding dengan herbisida sejenis, sehingga melindungi lebih lama.\nBahan Aktif: Topramezon 336g/l\r\nIsi Bersih: 20 ml\r\n', '-', 203175, 197370, 193500, 4480, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 955, 1, NULL, 0),
(123, 9, 'QOLS00123', 'Pegasus 500 SC 50 X 80 ml', 'Pegasus merupakan Insektisida dan akarisida racun kontak dan lambung, berbentuk pekatan suspensi berwarna putih keabu-abuan yang dapat larut dalam air, untuk mengendalikan hama serangga pada tanaman apel, bawang merah, cabai, kentang, kubis, semangka dan tomat.\nBahan Aktif: 500 g/l Diafenthiuron\r\nKemasan : 80 ml\r\n', 'PEGASUS_500SC_80ML.jpg', 85575, 83130, 81500, 1000, 0, 'Pcs', 'Pcs', 'Box', '50', '1', 119, 1, NULL, 0),
(124, 9, 'QOLS00124', 'Plenum 50 WG 12 X 10 X 25 gr', 'Plenum merupakan Insektisida sistemik yang bersifat menghambat aktivitas makan serangga, berbentuk butiran berwarna kecoklatan yang dapat disuspensikan dalam air untuk mengendalikan hama wereng coklat, wereng punggung putih, wereng hijau, kepinding tanah dan walang sangit pada tanaman padi.\nBahan Aktif: 50% pimetrozin\r\nKemasan : 25 gram\r\n', 'PLENUM_50WG_100GRAM.jpg', 36750, 35700, 35000, 34134, 0, 'Pcs', 'Pcs', 'Box', '120', '1', 40.4, 1, NULL, 0),
(125, 9, 'QOLS00125', 'Plenum 50 WG 50 X 100 gr', 'Plenum merupakan Insektisida sistemik yang bersifat menghambat aktivitas makan serangga, berbentuk butiran berwarna kecoklatan yang dapat disuspensikan dalam air untuk mengendalikan hama wereng coklat, wereng punggung putih, wereng hijau, kepinding tanah dan walang sangit pada tanaman padi.\nBahan Aktif: 50% pimetrozin\r\nKemasan : 100 gram\r\n', 'PLENUM_50WG_25GRAM.jpg', 135975, 132090, 129500, 12450, 0, 'Pcs', 'Pcs', 'Box', '50', '1', 141, 1, NULL, 0),
(126, 1, 'QOLS00126', 'Previcur N 722SL 100 X 100 ml', 'Previcur® N 722 SL Fungisida sistemik berbentuk larutan dalam air berwarna kekuning-kuningan yang ditranslokasikan ke seluruh bagian tanaman untuk mengendalikan penyakit pada tanaman bawang merah, cabai, kentang, kubis, melon, pinus, tembakau dan tomat.\nBahan aktif : Propamokarb hidroklorida 722 g/l\r\nIsi Bersih: 100 ml\r\n', 'PREVICUR_N_722SL_100ML.jpg', 37800, 36720, 36000, 5290, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 144.2, 1, NULL, 0),
(127, 1, 'QOLS00127', 'Previcur N 722SL 20 X 500 ml', 'Previcur® N 722 SL Fungisida sistemik berbentuk larutan dalam air berwarna kekuning-kuningan yang ditranslokasikan ke seluruh bagian tanaman untuk mengendalikan penyakit pada tanaman bawang merah, cabai, kentang, kubis, melon, pinus, tembakau dan tomat.\nBahan aktif : Propamokarb hidroklorida 722 g/l\r\nIsi Bersih: 500 ml\r\n', 'PREVICUR_N_722SL_500ML.jpg', 170888, 166005, 162750, 5398, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 649, 1, NULL, 0),
(128, 9, 'QOLS00128', 'Regent 50 SC Red 24 X 250 ml', 'Regent® 50 SC RED adalah insektisida sistemik racun kontak dan lambung  berbentuk pekatan suspensi berwarna merah yang digunakan untuk mengendalikan hama pada tanaman kedelai, jagung dan padi serta sebagai ZPT pada Jagung.\nBahan Aktif: Fipronil 50 g/l\r\nIsi Bersih: 250 ml\r\n', 'REGENT_RED_50SC_250ML.jpg', 101850, 98940, 97000, 51724, 0, 'Pcs', 'Pcs', 'Box', '24', '1', 318.8, 1, NULL, 0),
(129, 9, 'QOLS00129', 'Regent 50 SC Red 48 X 100 ml', 'Regent® 50 SC RED adalah insektisida sistemik racun kontak dan lambung  berbentuk pekatan suspensi berwarna merah yang digunakan untuk mengendalikan hama pada tanaman kedelai, jagung dan padi serta sebagai ZPT pada Jagung.\nBahan Aktif: Fipronil 50 g/l\r\nIsi Bersih: 100 ml\r\n', 'REGENT_RED_50SC_50ML.jpg', 44625, 43350, 42500, 142954, 0, 'Pcs', 'Pcs', 'Box', '48', '1', 133.3, 1, NULL, 0),
(130, 9, 'QOLS00130', 'Regent 50 SC Red 80 X 50 ml', 'Regent® 50 SC RED adalah insektisida sistemik racun kontak dan lambung  berbentuk pekatan suspensi berwarna merah yang digunakan untuk mengendalikan hama pada tanaman kedelai, jagung dan padi serta sebagai ZPT pada Jagung.\nBahan Aktif: Fipronil 50 g/l\r\nIsi Bersih: 50 ml\r\n', 'REGENT_RED_50SC_100ML.jpg', 23625, 22950, 22500, 137218, 0, 'Pcs', 'Pcs', 'Box', '80', '1', 1, 1, NULL, 0),
(131, 1, 'QOLS00131', 'Remazole-P 490 EC 20 X 400 ml', 'Remazole P 490 EC adalah fungisida sistemik dalam bentuk pekatan yang dapat diemulsikan (EC) untuk mengendalikan berbagai penyakit jamur pada tanaman seperti padi, bawang merah, kedelai, dan mangga. Fungisida ini mengandung dua bahan aktif, yaitu Prokloraz (400 g/L) dan Propikonazol (90 g/L). Remazole P 490 EC bekerja secara protektif, kuratif, dan eradikatif, efektif untuk melawan penyakit seperti bercak daun, karat daun, hawar pelepah, dan bercak ungu.\nBahan Aktif:\r\nProkloraz (400 g/L) dan Propikonazol (90 g/L).\r\nIsi Bersih: 400 ml\r\n', 'REMAZOLE_P_490EC_400ML.jpg', 350175, 340170, 333500, 1000, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 567.5, 1, NULL, 0),
(132, 1, 'QOLS00132', 'Remazole-P 490 EC 40 X 250 ml', 'Remazole P 490 EC adalah fungisida sistemik dalam bentuk pekatan yang dapat diemulsikan (EC) untuk mengendalikan berbagai penyakit jamur pada tanaman seperti padi, bawang merah, kedelai, dan mangga. Fungisida ini mengandung dua bahan aktif, yaitu Prokloraz (400 g/L) dan Propikonazol (90 g/L). Remazole P 490 EC bekerja secara protektif, kuratif, dan eradikatif, efektif untuk melawan penyakit seperti bercak daun, karat daun, hawar pelepah, dan bercak ungu.\nBahan Aktif:\r\nProkloraz (400 g/L) dan Propikonazol (90 g/L).\r\nIsi Bersih: 250 ml\r\n', 'REMAZOLE_P_490EC_250ML.jpg', 227850, 221340, 217000, 2590, 0, 'Pcs', 'Pcs', 'Box', '40', '1', 375, 1, NULL, 0),
(133, 1, 'QOLS00133', 'Revus Opti 440 SC 20 X 250 ml', 'Revus Opti merupakan Fungisida protektif yang bersifat sistemik dan kontak, berbentuk pekatan suspensi, berwarna putih keabu-abuan, untuk mengendalikan penyakit secara preventif dan kuratif pada tanaman bawang merah, cabai, jeruk, kakao, kentang, mentimun, melon, semangka, tembakau dan tomat. \nBahan Aktif:\r\n40 g/l mandipropamid\r\n400 g/l klorotalonil\r\nKemasan : 250 ml\r\n', 'REVUS_OPTI_440SC_250ML.jpg', 110250, 107100, 105000, 120, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 355, 1, NULL, 0),
(134, 2, 'QOLS00134', 'Ricestar Xtra 89 OD 100 X 100 ml', 'Ricestar® Xtra 89 OD Herbisida sistemik purna tumbuh berbentuk larutan dalam minyak berwarna putih keabu-abuan untuk mengendalikan gulma pada pertanaman padi.\nBahan aktif : Fenoksaprop-p-etil 69 g/ℓ + Etoksisulfuron 20 g/l\r\nIsi Bersih: 100 ml\r\n', 'RICESTAR_XTRA_100ML.jpg', 62475, 60690, 59500, 200, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 137, 1, NULL, 0),
(135, 2, 'QOLS00135', 'Ricestar Xtra 89 OD 40 X 250 ml', 'Ricestar® Xtra 89 OD Herbisida sistemik purna tumbuh berbentuk larutan dalam minyak berwarna putih keabu-abuan untuk mengendalikan gulma pada pertanaman padi.\nBahan aktif : Fenoksaprop-p-etil 69 g/ℓ + Etoksisulfuron 20 g/l\r\nIsi Bersih: 250 ml\r\n', 'RICESTAR_XTRA_250ML.jpg', 147000, 142800, 140000, 240, 0, 'Pcs', 'Pcs', 'Box', '40', '1', 326.25, 1, NULL, 0),
(136, 1, 'QOLS00136', 'Ridomil Gold 350 ES 4 X 20 X 12.5 ml', 'Fungisida sistemik berbentuk larutan emulsi berwarna merah muda untuk perlakuan benih untuk mengendalikan penyakit pada tanaman cabai, jagung, lada, dan tembakau yang digunakan dengan cara dicampurkan dengan benih sebelum tanam agar benih yang ditanam lebih tanam terhadap serangan jamur yang rawan menyerang tanaman pada saat umur muda.\nBahan Aktif: Mefenoksam 350 g/l\r\nKemasan : 12,5 ml\r\n', 'RIDOMIL_GOLD_350ES_12,5ML.jpg', 22838, 22185, 21750, 1000, 0, 'Pcs', 'Pcs', 'Box', '80', '1', 37.5, 1, NULL, 0),
(137, 1, 'QOLS00137', 'Ridomil Gold MZ 4/64 WG 100 X 100 gr', 'Fungisida sistemik berbentuk larutan emulsi berwarna merah muda untuk perlakuan benih untuk mengendalikan penyakit pada tanaman cabai, jagung, lada, dan tembakau yang digunakan dengan cara dicampurkan dengan benih sebelum tanam agar benih yang ditanam lebih tanam terhadap serangan jamur yang rawan menyerang tanaman pada saat umur muda.\nBahan Aktif: Mefenoksam 350 g/l\r\nKemasan : 100 gram\r\n', 'RIDOMIL_GOLD_100GRAM.jpg', 38850, 37740, 37000, 4000, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 121, 1, NULL, 0),
