(141, 9, 'QOLS00141', 'Rotraz 200 EC 50 X 100 ml', 'Rotraz 200 EC Insektisida dan akarisida racun kontak dan pernafasan, berbentuk pekatan yang dapat diemulsikan dalam air, berwarna coklat kemerahan, untuk mengendalikan hama pada tanaman apel dan cabai.\nBahan Aktif: amitraz 200 g/l\r\nIsi Bersih: 100 ml\r\n', 'ROTRAZ_200EC_100ML.jpg', 28350, 27540, 27000, 597, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 141, 1, NULL, 0),
(142, 2, 'QOLS00142', 'Rumpas 110 EW 100 X 100 ml', 'Rumpas® 110 EW Herbisida kontak dan sistemik purna tumbuh berbentuk pekatan emulsi minyak dalam air berwarna putih untuk mengendalikan gulma pada pertanaman bawang merah, cabai, kacang hijau, kacang panjang, kacang tanah, kedelai, ketimun, nanas, padi sawah dan tebu.\nBahan aktif : Fenoksaprop -p-etil 110 g/l\r\nIsi Bersih: 100 ml\r\n', 'RUMPAS_110EW_100ML.jpg', 43313, 42075, 41250, 7200, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 136.3, 1, NULL, 0),
(143, 2, 'QOLS00143', 'Rumpas 110 EW 40 X 250 ml', 'Rumpas® 110 EW Herbisida kontak dan sistemik purna tumbuh berbentuk pekatan emulsi minyak dalam air berwarna putih untuk mengendalikan gulma pada pertanaman bawang merah, cabai, kacang hijau, kacang panjang, kacang tanah, kedelai, ketimun, nanas, padi sawah dan tebu.\nBahan aktif : Fenoksaprop -p-etil 110 g/l\r\nIsi Bersih: 250 ml\r\n', 'RUMPAS_110EW_250ML.jpg', 103425, 100470, 98500, 2950, 0, 'Pcs', 'Pcs', 'Box', '40', '1', 322.5, 1, NULL, 0),
(144, 1, 'QOLS00144', 'Score 250 EC 40 X 250 ml', 'Score merupakan Fungisida sistemik berbentuk pekatan yang dapat diemulsikan, berwarna coklat kekuning-kuningan sampai coklat tua untuk mengendalikan penyakit pada tanaman apel, bawang merah, bawang putih, cabai, jagung, jarak pagar, jeruk, kacang panjang, kedelai, kelapa sawit, kentang, mangga, padi, semangka, tembakau, dan tomat. \nBahan Aktif: 250 g/l difenokonazol\r\nKemasan : 250 ml\r\n', 'SCORE_250EC_250ML.jpg', 173513, 168555, 165250, 13200, 0, 'Pcs', 'Pcs', 'Box', '40', '1', 312, 1, NULL, 0),
(145, 1, 'QOLS00145', 'Score 250 EC 50 X 80 ml', 'Score merupakan Fungisida sistemik berbentuk pekatan yang dapat diemulsikan, berwarna coklat kekuning-kuningan sampai coklat tua untuk mengendalikan penyakit pada tanaman apel, bawang merah, bawang putih, cabai, jagung, jarak pagar, jeruk, kacang panjang, kedelai, kelapa sawit, kentang, mangga, padi, semangka, tembakau, dan tomat. \nBahan Aktif: 250 g/l difenokonazol\r\nKemasan : 80 ml\r\n', 'SCORE_250EC_80ML.jpg', 58013, 56355, 55250, 30879, 0, 'Pcs', 'Pcs', 'Box', '50', '1', 110.6, 1, NULL, 0),
(146, 1, 'QOLS00146', 'Seltima 100 CS 20 X 500 ml', 'Seltima® 100 CS adalah fungisida dengan formulasi inovatif yang bekerja secara sistemik, bekerja protektif dan kuratif berbentuk mikrokapsul dalam pekatan yang dapat disuspensikan berwarna putih untuk mengendalikan penyakit pada tanaman padi. Seltima® juga memiliki efek Agcelence yang berperan dalam pengisian gabah sehingga gabah terisi maksimal dan mengurangi jumlah gabah kosong.\nBahan aktif: Piraklostrobin 100 g/l\r\nIsi Bersih: 500 ml\r\n', 'SELTIMA_100CS_500ML.jpg', 192675, 187170, 183500, 18505, 0, 'Pcs', 'Pcs', 'Box', '20', '1', 600, 1, NULL, 0),
(147, 1, 'QOLS00147', 'Seltima 100 CS 24 X 250 ml', 'Seltima® 100 CS adalah fungisida dengan formulasi inovatif yang bekerja secara sistemik, bekerja protektif dan kuratif berbentuk mikrokapsul dalam pekatan yang dapat disuspensikan berwarna putih untuk mengendalikan penyakit pada tanaman padi. Seltima® juga memiliki efek Agcelence yang berperan dalam pengisian gabah sehingga gabah terisi maksimal dan mengurangi jumlah gabah kosong.\nBahan aktif: Piraklostrobin 100 g/l\r\nIsi Bersih: 250 ml\r\n', 'SELTIMA_100CS_250ML.jpg', 104475, 101490, 99500, 11510, 0, 'Pcs', 'Pcs', 'Box', '24', '1', 333, 1, NULL, 0),
(148, 9, 'QOLS00148', 'Simodis 100 DC 50 X 100 ml', 'Simodis merupakan Insektisida racun kontak dan lambung berbentuk pekatan yang dapat didispersikan, berwarna coklat, untuk mengendalikan hama pada tanaman bawang merah, cabai, kubis dan tomat.\nBahan Aktif:\r\n100 g/l isosikloseram \r\nKemasan : 100 ml\r\n', 'SIMODIS_100DC_100ML.jpg', 134400, 130560, 128000, 20010, 0, 'Pcs', 'Pcs', 'Box', '50', '1', 149, 1, NULL, 0),
(149, 9, 'QOLS00149', 'Sivanto Prime 200 SL 100 X 100 ml', 'Sivanto Prime 200 SL Insektisida sistemik berbentuk larutan dalam air, berwarna kuning kecoklatan / merah, untuk mengendalikan hama pada tanaman cabai, jeruk, tembakau, terong, dan tomat\nBahan aktif : Flupiradifuron 200 g/l\r\nIsi Bersih: 100 ml\r\n', 'SIVANTO_PRIME_100ML.jpg', 64050, 62220, 61000, 1000, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 154.5, 1, NULL, 0),
(150, 15, 'QOLS00150', 'Stardon 60 WP 10 X 8 X 100 gr', 'Stardon 60 WP Moluskisida racun kontak berbentuk tepung yang dapat disuspensikan, berwarna putih, untuk mengendalikan siput murbei (Pomacea canaliculata) pada tanaman padi sawah.\nBahan Aktif: fentin asetat 60%\r\nIsi Bersih: 100 Gram\r\n', 'STARDON_60WP_100GRAM.jpg', 55650, 54060, 53000, 3793, 0, 'Pcs', 'Pcs', 'Box', '80', '1', 129, 1, NULL, 0),
(151, 9, 'QOLS00151', 'Symphony Plus 32 X 250 ml', 'SYMPHONY 100 EC merupakan Insektisida racun kontak dan lambung berbentuk pekatan yang dapat diemulsikan berwarna kuning bening, untuk mengendalikan hama pada tanaman Bawang Merah, Cabai, dan Kubis.\nBahan Aktif : Piridalil 100 g/L\r\nIsi Bersih: 250 ml\r\n', 'SYMPHONY_PLUS_250ML.jpg', 346500, 336600, 330000, 1000, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 656.3, 1, NULL, 0),
(152, 9, 'QOLS00152', 'Symphony Plus 40 X 100 ml', 'SYMPHONY 100 EC merupakan Insektisida racun kontak dan lambung berbentuk pekatan yang dapat diemulsikan berwarna kuning bening, untuk mengendalikan hama pada tanaman Bawang Merah, Cabai, dan Kubis.\nBahan Aktif : Piridalil 100 g/L\r\nIsi Bersih: 100 ml\r\n', 'SYMPHONY_PLUS_100ML.jpg', 141750, 137700, 135000, 547, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 305, 1, NULL, 0),
(153, 1, 'QOLS00153', 'Topsindo 70 WP 20 X 500 gr', 'Topsindo 70 WP Fungisida kontak dan sistemik berbentuk tepung yang dapat disuspensikan, berwarna putih sampai krem, untuk mengendalikan penyakit yang disebabkan oleh jamur pada tanaman padi dan tembakau.\nBahan Aktif: metil tiofanat 70%\r\nIsi Bersih: 500 ml\r\n', 'TOPSINDO_70WP_500GRAM.jpg', 102900, 99960, 98000, 700, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 597.5, 1, NULL, 0),
(154, 9, 'QOLS00154', 'Trigard 75 WP 10 X 10 X 50 gr', 'Trigard® 75 WP merupakan insektisida sistemik penghambat pertumbuhan serangga, berbentuk tepung yang dapat disuspensikan berwarna putih kecoklat-coklatan, digunakan untuk mengendalikan hama pada tanaman bawang merah, kacang panjang, kentang, dan tomat. \nBahan Aktif: 75% siromazin\r\nKemasan : 50 gram\r\n', 'TRIGARD_75WP_50GRAM.jpg', 211575, 205530, 201500, 1000, 0, 'Pcs', 'Pcs', 'Box', '100', '1', 67.7, 1, NULL, 0),
(155, 9, 'QOLS00155', 'Trigard 75 WP 12 X 10 X 25 gr', 'Trigard® 75 WP merupakan insektisida sistemik penghambat pertumbuhan serangga, berbentuk tepung yang dapat disuspensikan berwarna putih kecoklat-coklatan, digunakan untuk mengendalikan hama pada tanaman bawang merah, kacang panjang, kentang, dan tomat. \nBahan Aktif: 75% siromazin\r\nKemasan : 25 gram\r\n', 'TRIGARD_75WP_25GRAM.jpg', 110775, 107610, 105500, 1000, 0, 'Pcs', 'Pcs', 'Box', '120', '1', 40, 1, NULL, 0),
(156, 2, 'QOLS00156', 'Unibro 500/50 SC 20 X 250 ml', 'UNIBRO 500/50 EC Herbisida sistemik selektif pra tumbuh dan purna tumbuh berbentuk pekatan suspensi, berwarna coklat muda, untuk mengendalikan gulma berdaun lebar, gulma golongan rumput dan teki pada budidaya tanaman jagung.\nBahan Aktif: atrazin 500 g/l mesotrion 50 g/l\r\nIsi Bersih: 250 ml\r\n', 'UNIBRO_250ML.jpg', 68250, 66300, 65000, 425, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 327.5, 1, NULL, 0),
(157, 2, 'QOLS00157', 'Unibro 500/50 SC 20 X 500 ml', 'UNIBRO 500/50 EC Herbisida sistemik selektif pra tumbuh dan purna tumbuh berbentuk pekatan suspensi, berwarna coklat muda, untuk mengendalikan gulma berdaun lebar, gulma golongan rumput dan teki pada budidaya tanaman jagung.\nBahan Aktif: atrazin 500 g/l mesotrion 50 g/l\r\nIsi Bersih: 500 ml\r\n', 'UNIBRO_500ML.jpg', 131250, 127500, 125000, 7579, 0, 'Pcs', 'Pcs', 'Box', '1', '1', 612.5, 1, NULL, 0),
