(469, 9, 'B6W2X1GI662500208', 'Buniken 60/10 WP 20 X 100 gr', '\"Buniken 60/10 WP adalah insektisida berbentuk tepung yang dapat disuspensikan (Wettable Powder / WP) yang diformulasikan untuk mengendalikan hama pada tanaman padi, khususnya wereng coklat. Produk ini mengandung kombinasi bahan aktif Buprofezin 60% dan Nitenpiram 10% yang bekerja secara sistemik, kontak, dan lambung sehingga mampu mengendalikan hama dari fase telur, nimfa hingga dewasa.\r\n\r\nSpesifikasi Produk :\r\nNama Produk : Buniken 60/10 WP\r\nBentuk Formulasi : WP (Wettable Powder) – tepung yang dapat disuspensikan dalam air\r\nJenis : Insektisida sistemik, racun kontak dan lambung\r\n\r\nBahan Aktif : Buprofezin 60% dan Nitenpiram 10%\"', 'BUNIKEN_6010WP_100GRAM.jpg', 65625, 62500, 63750, 72, 0, NULL, 'Botol', 'Box', '100', 'Pilih Tipe Produk', 120, 1, '2026-04-21 13:33:28', 0),
(470, 9, 'E5E2X1LI4472500283', 'Emaplus 50 EC 20 X 1 ltr', '\"NEMAGUARD 10 GR adalah insektisida berbentuk butiran (Granule / GR) berwarna hijau yang bekerja sebagai racun kontak dan lambung untuk mengendalikan hama perusak tanaman. Produk ini mengandung bahan aktif Oksamil 10% yang efektif mengendalikan hama ulat tanah pada tanaman, khususnya pada budidaya kentang.\r\n\r\nSpesifikasi Produk :\r\nNama Produk : NEMAGUARD 10 GR\r\nBentuk Formulasi : GR (Granule) – butiran berwarna hijau\r\nJenis : Insektisida racun kontak dan lambung\r\n\r\nBahan Aktif : Oksamil 10%\"', 'EMAPLUS_50EC_1LITER.jpg', 496125, 472500, 481950, 0, 0, NULL, 'Botol', 'Box', '0', 'Pilih Tipe Produk', 1200, 1, '2026-04-21 13:34:43', 0),
