(473, 9, 'E5E5X8MI552500402', 'Emaplus 50 EC 50 X 80 ml', '\"Emaplus 50 EC adalah insektisida berbentuk pekatan yang dapat diemulsikan (Emulsifiable Concentrate / EC) berwarna kuning kecoklatan yang bekerja sebagai racun kontak dan lambung. Produk ini mengandung bahan aktif Emamektin Benzoat 50 g/L yang efektif mengendalikan berbagai hama ulat pada tanaman pertanian dengan daya kerja cepat (knockdown).\r\n\r\nSpesifikasi Produk :\r\nNama Produk : Emaplus 50 EC\r\nBentuk Formulasi : EC (Emulsifiable Concentrate) – pekatan yang dapat diemulsikan dengan air\r\nJenis : Insektisida racun kontak dan lambung\r\n\r\nBahan Aktif : Emamektin Benzoat 50 g/L\"\r\n', 'EMAPLUS_50EC_80ML.jpg', 55125, 52500, 53550, 135, 0, NULL, 'Botol', 'Box', '100', 'Pilih Tipe Produk', 100, 1, '2026-04-21 13:53:22', 0),
(474, 13, 'K5E2X1LLL1110000495', 'Konsep 50 EC 20 X 1 ltr', '\"KONSEP 50 EC adalah insektisida racun kontak dan lambung dari golongan sintetik piretroid yang diformulasikan dalam bentuk Emulsifiable Concentrate (EC) atau pekatan yang dapat diemulsikan dengan air. Produk ini berbentuk cairan kuning kecoklatan dan mengandung bahan aktif Lamda Sihalotrin 50 g/L yang bekerja cepat dalam mengendalikan berbagai hama perusak tanaman, baik pada tanaman perkebunan maupun hama gudang.\r\n\r\nSpesifikasi Produk :\r\nNama Produk : KONSEP 50 EC\r\nBentuk Formulasi : EC (Emulsifiable Concentrate) – pekatan yang dapat diemulsikan dengan air\r\nJenis : Insektisida racun kontak dan lambung\r\nGolongan : Sintetik piretroid\r\n\r\nBahan Aktif : Lamda Sihalotrin 50 g/L\"\r\n\r\n', 'KONSEP_50EC_1LITER.jpg', 115500, 110000, 112200, 50, 0, NULL, 'Botol', 'Box', '100', 'Pilih Tipe Produk', 1200, 1, '2026-04-21 13:54:55', 0),
(475, 13, 'K5E2X5MLL657500562', 'Konsep 50 EC 25 X 500 ml', '\"KONSEP 50 EC adalah insektisida racun kontak dan lambung dari golongan sintetik piretroid yang diformulasikan dalam bentuk Emulsifiable Concentrate (EC) atau pekatan yang dapat diemulsikan dengan air. Produk ini berbentuk cairan kuning kecoklatan dan mengandung bahan aktif Lamda Sihalotrin 50 g/L yang bekerja cepat dalam mengendalikan berbagai hama perusak tanaman, baik pada tanaman perkebunan maupun hama gudang.\r\n\r\nSpesifikasi Produk :\r\nNama Produk : KONSEP 50 EC\r\nBentuk Formulasi : EC (Emulsifiable Concentrate) – pekatan yang dapat diemulsikan dengan air\r\nJenis : Insektisida racun kontak dan lambung\r\nGolongan : Sintetik piretroid\r\n\r\nBahan Aktif : Lamda Sihalotrin 50 g/L\"\r\n\r\n', 'KONSEP_50EC_500ML.jpg', 60375, 57500, 58650, 2125, 0, NULL, 'Botol', 'Box', '0', 'Pilih Tipe Produk', 520, 1, '2026-04-21 13:56:02', 0),
(476, 13, 'K5E4X2MLL335000710', 'Konsep 50 EC 40 X 250 ml', '\"KONSEP 50 EC adalah insektisida racun kontak dan lambung dari golongan sintetik piretroid yang diformulasikan dalam bentuk Emulsifiable Concentrate (EC) atau pekatan yang dapat diemulsikan dengan air. Produk ini berbentuk cairan kuning kecoklatan dan mengandung bahan aktif Lamda Sihalotrin 50 g/L yang bekerja cepat dalam mengendalikan berbagai hama perusak tanaman, baik pada tanaman perkebunan maupun hama gudang.\r\n\r\nSpesifikasi Produk :\r\nNama Produk : KONSEP 50 EC\r\nBentuk Formulasi : EC (Emulsifiable Concentrate) – pekatan yang dapat diemulsikan dengan air\r\nJenis : Insektisida racun kontak dan lambung\r\nGolongan : Sintetik piretroid\r\n\r\nBahan Aktif : Lamda Sihalotrin 50 g/L\"\r\n\r\n', 'KONSEP_50EC_250ML.jpg', 36750, 35000, 35700, 920, 0, NULL, 'Botol', 'Box', '0', 'Pilih Tipe Produk', 270, 1, '2026-04-21 13:58:30', 0),
(477, 20, 'G2E4X2MZ1170000794', 'Ganero 250 EC 40 X 250 ml', '\"GANERO 250 EC adalah zat pengatur tumbuh (ZPT) sistemik berbentuk pekatan emulsi (Emulsifiable Concentrate / EC) yang mengandung bahan aktif Piraklostrobin. Produk ini diformulasikan untuk membantu memacu pertumbuhan tanaman, meningkatkan hasil panen, serta mempercepat proses pembuahan. Selain berfungsi sebagai ZPT, GANERO 250 EC juga memiliki fungistatic effect, yaitu membantu menekan perkembangan cendawan patogen pada tanaman sehingga tanaman dapat tumbuh lebih sehat dan produktif.\r\n\r\nSpesifikasi Produk :\r\nNama Produk : GANERO 250 EC\r\nBentuk Formulasi : EC (Emulsifiable Concentrate) – pekatan yang dapat diemulsikan dengan air\r\nJenis : Zat Pengatur Tumbuh (ZPT) sistemik\r\n\r\nBahan Aktif : Piraklostrobin\"\r\n', 'GANERO_250EC_250ML.jpg', 178500, 170000, 173400, 40, 0, NULL, 'Botol', 'Box', '120', 'Pilih Tipe Produk', 270, 1, '2026-04-21 13:59:54', 0),
(478, 20, 'G2E4X1MZ880000842', 'Ganero 250 EC 40 X 100 ml', '\"GANERO 250 EC adalah zat pengatur tumbuh (ZPT) sistemik berbentuk pekatan emulsi (Emulsifiable Concentrate / EC) yang mengandung bahan aktif Piraklostrobin. Produk ini diformulasikan untuk membantu memacu pertumbuhan tanaman, meningkatkan hasil panen, serta mempercepat proses pembuahan. Selain berfungsi sebagai ZPT, GANERO 250 EC juga memiliki fungistatic effect, yaitu membantu menekan perkembangan cendawan patogen pada tanaman sehingga tanaman dapat tumbuh lebih sehat dan produktif.\r\n\r\nSpesifikasi Produk :\r\nNama Produk : GANERO 250 EC\r\nBentuk Formulasi : EC (Emulsifiable Concentrate) – pekatan yang dapat diemulsikan dengan air\r\nJenis : Zat Pengatur Tumbuh (ZPT) sistemik\r\n\r\nBahan Aktif : Piraklostrobin\"\r\n', 'GANERO_250EC_100ML.jpg', 84000, 80000, 81600, 40, 0, NULL, 'Botol', 'Box', '120', 'Pilih Tipe Produk', 120, 1, '2026-04-21 14:00:42', 0),
(479, 12, 'TDS1LB(SP4450000923', 'Tangki Dragon Star 16 ltr baterai (Biru)', '\"Dragon Star 16 Liter adalah alat semprot elektrik (knapsack sprayer) yang dirancang untuk memudahkan kegiatan penyemprotan di bidang pertanian, perkebunan, hingga penggunaan disinfektan. Alat ini menggunakan tenaga baterai/aki sehingga pengguna tidak perlu memompa secara manual, membuat pekerjaan menjadi lebih praktis, hemat tenaga, dan hemat waktu.\r\n\r\nSpesifikasi Produk :\r\nNama Produk : Dragon Star 16 Liter\r\nJenis : Sprayer elektrik / knapsack sprayer\r\nKapasitas Tangki : 16 Liter\r\nSumber Tenaga : Baterai / aki\"', 'SPRAYER_TANGKI_DRAGON_STAR_16LITER.jpg', 472500, 450000, 459000, 15, 0, NULL, 'Pcs', 'Pilih Satuan Product', '30', 'Pilih Tipe Produk', 16000, 1, '2026-04-21 14:02:03', 0),
(480, 20, 'K1S2X5MZ2195000017', 'Kelpak 11/0.031 SL 20 X 500 ml', '\"Kelpak 11/0.031 SL adalah zat pengatur tumbuh (ZPT) organik berbentuk cair (SL) yang dibuat dari ekstrak rumput laut Ecklonia maxima. Produk ini mengandung bio-auxin dan sitokinin yang berfungsi merangsang pertumbuhan akar, memperkuat pertumbuhan awal tanaman, meningkatkan jumlah anakan produktif, serta membantu meningkatkan kualitas dan hasil panen pada berbagai jenis tanaman.\r\n\r\nKeunggulan Kelpak 11/0.031 SL:\r\nMerangsang pertumbuhan akar lebih cepat dan kuat\r\nMembantu pembentukan tunas dan anakan produktif\r\nMengurangi stres tanaman setelah pindah tanam\r\nMeningkatkan pertumbuhan vegetatif dan potensi hasil panen\r\nCocok digunakan pada berbagai tanaman hortikultura, pangan, dan perkebunan\r\nKandungan utama: Bio-Auxin: 11 mg/L dan Sitokinin: 0,031 mg/L\"\r\n\r\n', 'KELPAK_110_031SL_500ML.jpg', 204750, 195000, 198900, 159, 0, NULL, 'Botol', 'Box', '100', 'Pilih Tipe Produk', 520, 1, '2026-04-21 14:03:37', 0),
(481, 20, 'K1S4X2MZ664000083', 'Kelpak 11/0.031 SL 40 X 250 ml', '\"Kelpak 11/0.031 SL adalah zat pengatur tumbuh (ZPT) organik berbentuk cair (SL) yang dibuat dari ekstrak rumput laut Ecklonia maxima. Produk ini mengandung bio-auxin dan sitokinin yang berfungsi merangsang pertumbuhan akar, memperkuat pertumbuhan awal tanaman, meningkatkan jumlah anakan produktif, serta membantu meningkatkan kualitas dan hasil panen pada berbagai jenis tanaman.\r\n\r\nKeunggulan Kelpak 11/0.031 SL:\r\nMerangsang pertumbuhan akar lebih cepat dan kuat\r\nMembantu pembentukan tunas dan anakan produktif\r\nMengurangi stres tanaman setelah pindah tanam\r\nMeningkatkan pertumbuhan vegetatif dan potensi hasil panen\r\nCocok digunakan pada berbagai tanaman hortikultura, pangan, dan perkebunan\r\nKandungan utama: Bio-Auxin: 11 mg/L dan Sitokinin: 0,031 mg/L\"\r\n\r\n', 'KELPAK_110_031SL_250ML.jpg', 67200, 64000, 65280, 34, 0, NULL, 'Botol', 'Box', '120', 'Pilih Tipe Produk', 270, 1, '2026-04-21 14:04:43', 0),
(482, 20, 'K1S5X1MZ117500145', 'Kelpak 11/0.031 SL 50 X 100 ml', '\"Kelpak 11/0.031 SL adalah zat pengatur tumbuh (ZPT) organik berbentuk cair (SL) yang dibuat dari ekstrak rumput laut Ecklonia maxima. Produk ini mengandung bio-auxin dan sitokinin yang berfungsi merangsang pertumbuhan akar, memperkuat pertumbuhan awal tanaman, meningkatkan jumlah anakan produktif, serta membantu meningkatkan kualitas dan hasil panen pada berbagai jenis tanaman.\r\n\r\nKeunggulan Kelpak 11/0.031 SL:\r\nMerangsang pertumbuhan akar lebih cepat dan kuat\r\nMembantu pembentukan tunas dan anakan produktif\r\nMengurangi stres tanaman setelah pindah tanam\r\nMeningkatkan pertumbuhan vegetatif dan potensi hasil panen\r\nCocok digunakan pada berbagai tanaman hortikultura, pangan, dan perkebunan\r\nKandungan utama: Bio-Auxin: 11 mg/L dan Sitokinin: 0,031 mg/L\"\r\n\r\n', 'KELPAK_110_031SL_100ML.jpg', 18375, 17500, 17850, 134, 0, NULL, 'Botol', 'Box', '150', 'Pilih Tipe Produk', 120, 1, '2026-04-21 14:05:45', 0),
(483, 20, 'GB5X1MZ992000219', 'GG Bunga 50 X 100 ml', '\"Zat Pengatur Tumbuh (ZPT) & Nutrisi Tanaman ini diformulasikan untuk membantu merangsang pertumbuhan tunas dan pembungaan sehingga tanaman dapat tumbuh lebih optimal dan produktif. Produk ini bekerja dengan mendukung proses fisiologis tanaman, terutama pada fase vegetatif dan generatif.\r\n\r\nSpesifikasi Produk :\r\nJenis : Zat Pengatur Tumbuh (ZPT) & Nutrisi Tanaman\r\nBentuk : Cair / larutan (umumnya mudah dicampur dengan air)\"\r\n', 'GG_BUNGA_100ML.jpg', 96600, 92000, 93840, 194, 0, NULL, 'Botol', 'Box', '150', 'Pilih Tipe Produk', 120, 1, '2026-04-21 14:06:59', 0),
(484, 20, 'GB1X1X1M(Z222500277', 'GG Bunga 10 X 10 X 15 ml (M2U)', '\"Zat Pengatur Tumbuh (ZPT) & Nutrisi Tanaman ini diformulasikan untuk membantu merangsang pertumbuhan tunas dan pembungaan sehingga tanaman dapat tumbuh lebih optimal dan produktif. Produk ini bekerja dengan mendukung proses fisiologis tanaman, terutama pada fase vegetatif dan generatif.\r\n\r\nSpesifikasi Produk :\r\nJenis : Zat Pengatur Tumbuh (ZPT) & Nutrisi Tanaman\r\nBentuk : Cair / larutan (umumnya mudah dicampur dengan air)\"\r\n', 'GG_BUNGA_15ML.jpg', 23625, 22500, 22950, 0, 0, NULL, 'Botol', 'Box', '0', 'Pilih Tipe Produk', 17, 1, '2026-04-21 14:07:57', 0),
(485, 1, 'A2E4X2MF990000384', 'Asetor 250 EC 40 X 250 ml', '\"Asetor 250 EC adalah fungisida sistemik berbentuk pekatan yang dapat diemulsikan (Emulsifiable Concentrate / EC) yang mengandung bahan aktif Difenokonazol 250 g/L. Produk ini efektif untuk mengendalikan berbagai penyakit jamur pada tanaman, khususnya pada padi, serta bekerja secara preventif (pencegahan) dan kuratif (penyembuhan) sehingga tanaman tetap sehat dan produktif.\r\n\r\nSpesifikasi Produk :\r\nNama Produk : Asetor 250 EC\r\nBentuk Formulasi : EC (Emulsifiable Concentrate) – pekatan yang dapat diemulsikan dengan air\r\nJenis : Fungisida sistemik\r\n\r\nBahan Aktif : Difenokonazol 250 g/L\"', 'ASETOR_250EC_250ML.jpg', 94500, 90000, 91800, 215, 0, NULL, 'Botol', 'Box', '120', 'Pilih Tipe Produk', 270, 1, '2026-04-21 14:09:44', 0),
(486, 1, 'X5E2X9MF1130000567', 'Xycort 550/60 EC 20 X 900 ml', '\"Xycort 550/60 EC adalah insektisida berbentuk pekatan yang dapat diemulsikan (Emulsifiable Concentrate / EC) yang bekerja sebagai racun kontak dan lambung. Produk ini mengandung kombinasi bahan aktif Klorpirifos dan Sipermetrin yang memberikan efek pengendalian cepat dan efektif terhadap berbagai hama perusak tanaman.\r\n\r\nSpesifikasi Produk :\r\nNama Produk : Xycort 550/60 EC\r\nBentuk Formulasi : EC (Emulsifiable Concentrate) – pekatan yang dapat diemulsikan dengan air\r\nJenis : Insektisida racun kontak dan lambung\r\n\r\nBahan Aktif : Klorpirifos 550 g/L dan Sipermetrin 60 g/L\"\r\n\r\n', 'XYCORT_55060EC_900ML.jpg', 136500, 130000, 132600, 177, 0, NULL, 'Botol', 'Box', '100', 'Pilih Tipe Produk', 920, 1, '2026-04-21 14:12:47', 0),
(487, 9, 'K4S2X1LI555000538', 'Ken-mipo 400 SL 20 X 1 ltr', '\"Ken-Mipo 400 SL adalah insektisida sistemik berbentuk larutan (Soluble Liquid / SL) yang diformulasikan untuk mengendalikan berbagai hama pengisap pada tanaman. Produk ini bekerja efektif dengan cara diserap oleh jaringan tanaman sehingga memberikan perlindungan dari dalam terhadap serangan hama.\r\n\r\nSpesifikasi Produk :\r\nNama Produk : Ken-Mipo 400 SL\r\nBentuk Formulasi : SL (Soluble Liquid) – larutan yang mudah dicampur dengan air\r\nJenis : Insektisida sistemik\r\n\r\nBahan Aktif : Imidakloprid 400 g/L\"\r\n', 'KEN-MIPO_400_SL_1LITER.jpg', 57750, 55000, 56100, 334, 0, NULL, 'Botol', 'Box', '1000', 'Pilih Tipe Produk', 1200, 1, '2026-04-22 10:28:58', 0),
(488, 9, 'K4S2X5MI332500628', 'Ken-mipo 400 SL 24 X 500 ml', '\"Ken-Mipo 400 SL adalah insektisida sistemik berbentuk larutan (Soluble Liquid / SL) yang diformulasikan untuk mengendalikan berbagai hama pengisap pada tanaman. Produk ini bekerja efektif dengan cara diserap oleh jaringan tanaman sehingga memberikan perlindungan dari dalam terhadap serangan hama.\r\n\r\nSpesifikasi Produk :\r\nNama Produk : Ken-Mipo 400 SL\r\nBentuk Formulasi : SL (Soluble Liquid) – larutan yang mudah dicampur dengan air\r\nJenis : Insektisida sistemik\r\n\r\nBahan Aktif : Imidakloprid 400 g/L\"\r\n', 'KEN-MIPO_400_SL_500ML.jpg', 34125, 32500, 33150, 230, 0, NULL, 'Botol', 'Box', '120', 'Pilih Tipe Produk', 520, 1, '2026-04-22 10:30:28', 0),
(489, 1, 'A7W1X1KF1120000718', 'Asiacol 70 WP 12 X 1 kg', '\"Asiacol 70 WP adalah fungisida protektif berbentuk tepung yang dapat disuspensikan (Wettable Powder / WP. Produk ini mengandung bahan aktif Propineb 70% yang efektif melindungi tanaman dari serangan penyakit jamur, khususnya pada tanaman kentang.\r\n\r\nSpesifikasi Produk :\r\nNama Produk : Asiacol 70 WP\r\nBentuk Formulasi : WP (Wettable Powder) – tepung yang dapat disuspensikan dalam air\r\nJenis : Fungisida protektif\r\n\r\nBahan Aktif : Propineb 70%\"\r\n', 'ASIACOL_70WP_1KG.jpg', 126000, 120000, 122400, 0, 0, NULL, 'Botol', 'Box', '0', 'Pilih Tipe Produk', 1200, 1, '2026-04-22 10:31:58', 0),
(490, 1, 'A7W2X2GF440000773', 'Asiacol 70 WP 20 X 250 gr', '\"Asiacol 70 WP adalah fungisida protektif berbentuk tepung yang dapat disuspensikan (Wettable Powder / WP. Produk ini mengandung bahan aktif Propineb 70% yang efektif melindungi tanaman dari serangan penyakit jamur, khususnya pada tanaman kentang.\r\n\r\nSpesifikasi Produk :\r\nNama Produk : Asiacol 70 WP\r\nBentuk Formulasi : WP (Wettable Powder) – tepung yang dapat disuspensikan dalam air\r\nJenis : Fungisida protektif\r\n\r\nBahan Aktif : Propineb 70%\"\r\n', 'ASIACOL_70WP_250GR.jpg', 42000, 40000, 40800, 0, 0, NULL, 'Botol', 'Box', '0', 'Pilih Tipe Produk', 270, 1, '2026-04-22 10:32:53', 0),
(491, 9, 'M3E2X4MI988000932', 'Megaloman 30 EC 20 X 400 ml', '\"insektisida berbentuk pekatan yang dapat diemulsikan (Emulsifiable Concentrate / EC) yang bekerja sebagai racun kontak dan lambung. Produk ini mengandung bahan aktif Indoksakarb (Indoxacarb) yang efektif untuk mengendalikan berbagai hama ulat dan penggorok daun pada tanaman pertanian.\r\n\r\nSpesifikasi Produk :\r\nNama Produk : Megaloman 30 EC\r\nBentuk Formulasi : EC (Emulsifiable Concentrate) – pekatan yang dapat diemulsikan dengan air\r\nJenis : Insektisida racun kontak dan lambung\r\n\r\nBahan Aktif : Indoksakarb (Indoxacarb)\"', 'MEGALOMAN_30EC_400ML.jpg', 92400, 88000, 89760, 266, 0, NULL, 'Botol', 'Box', '100', 'Pilih Tipe Produk', 420, 1, '2026-04-22 10:35:32', 0),
(492, 17, 'B2X1LP&P1180000471', 'Biosoft 20 X 1 ltr', '\"Biosoft adalah produk surfactant premium (perekat, perata, dan penembus) yang didistribusikan oleh PT Trimarga Nusantara Indonesia. Produk ini diformulasikan khusus untuk meningkatkan kualitas air semprot serta memaksimalkan kinerja pestisida (insektisida & fungisida) dan pupuk cair pada tanaman.\r\n\r\nSpesifikasi Produk :\r\nNama Produk : Biosoft\r\nJenis : Surfaktan / Adjuvant Premium\r\nBentuk : Cair\r\n\r\nFungsi Utama :\r\nMeningkatkan daya basah dan penyebaran larutan pada permukaan daun\r\nMenurunkan dan menjaga pH larutan semprot agar tetap ideal\r\nMeningkatkan efektivitas pestisida, insektisida, fungisida, dan pupuk cair\r\nMembantu penyerapan bahan aktif lebih cepat ke jaringan tanaman\r\n\r\nKeunggulan :\r\nMeningkatkan kualitas air semprotan\r\nMembuat kinerja pestisida lebih maksimal dan efisien\r\nMengoptimalkan hasil aplikasi di lapangan\r\nCocok sebagai bahan pelengkap (adjuvant) untuk berbagai jenis campuran semprot\"\r\n\r\n', 'BIOSOFT_1LITER.jpg', 189000, 180000, 183600, 0, 0, NULL, 'Botol', 'Box', '0', 'Pilih Tipe Produk', 1200, 1, '2026-04-22 11:17:51', 0),
(493, 17, 'B2X5MP&P1105000545', 'Biosoft 20 X 500 ml', '\"Biosoft adalah produk surfactant premium (perekat, perata, dan penembus) yang didistribusikan oleh PT Trimarga Nusantara Indonesia. Produk ini diformulasikan khusus untuk meningkatkan kualitas air semprot serta memaksimalkan kinerja pestisida (insektisida & fungisida) dan pupuk cair pada tanaman.\r\n\r\nSpesifikasi Produk :\r\nNama Produk : Biosoft\r\nJenis : Surfaktan / Adjuvant Premium\r\nBentuk : Cair\r\n\r\nFungsi Utama :\r\nMeningkatkan daya basah dan penyebaran larutan pada permukaan daun\r\nMenurunkan dan menjaga pH larutan semprot agar tetap ideal\r\nMeningkatkan efektivitas pestisida, insektisida, fungisida, dan pupuk cair\r\nMembantu penyerapan bahan aktif lebih cepat ke jaringan tanaman\r\n\r\nKeunggulan :\r\nMeningkatkan kualitas air semprotan\r\nMembuat kinerja pestisida lebih maksimal dan efisien\r\nMengoptimalkan hasil aplikasi di lapangan\r\nCocok sebagai bahan pelengkap (adjuvant) untuk berbagai jenis campuran semprot\"\r\n\r\n', 'BIOSOFT_500ML.jpg', 110250, 105000, 107100, 1, 0, NULL, 'Botol', 'Box', '0', 'Pilih Tipe Produk', 520, 1, '2026-04-22 11:19:05', 0),
(494, 17, 'B5X1MP&P334000592', 'Biosoft 50 X 100 ml', '\"Biosoft adalah produk surfactant premium (perekat, perata, dan penembus) yang didistribusikan oleh PT Trimarga Nusantara Indonesia. Produk ini diformulasikan khusus untuk meningkatkan kualitas air semprot serta memaksimalkan kinerja pestisida (insektisida & fungisida) dan pupuk cair pada tanaman.\r\n\r\nSpesifikasi Produk :\r\nNama Produk : Biosoft\r\nJenis : Surfaktan / Adjuvant Premium\r\nBentuk : Cair\r\n\r\nFungsi Utama :\r\nMeningkatkan daya basah dan penyebaran larutan pada permukaan daun\r\nMenurunkan dan menjaga pH larutan semprot agar tetap ideal\r\nMeningkatkan efektivitas pestisida, insektisida, fungisida, dan pupuk cair\r\nMembantu penyerapan bahan aktif lebih cepat ke jaringan tanaman\r\n\r\nKeunggulan :\r\nMeningkatkan kualitas air semprotan\r\nMembuat kinerja pestisida lebih maksimal dan efisien\r\nMengoptimalkan hasil aplikasi di lapangan\r\nCocok sebagai bahan pelengkap (adjuvant) untuk berbagai jenis campuran semprot\"\r\n\r\n', 'BIOSOFT_100ML.jpg', 35700, 34000, 34680, 100, 0, NULL, 'Botol', 'Box', '0', 'Pilih Tipe Produk', 120, 1, '2026-04-22 11:19:52', 0),
(495, 9, 'P1Z4X2MI1130000708', 'Pilarclotrin 145/135 ZC 40 X 200 ml', '\"Biosoft adalah produk surfactant premium (perekat, perata, dan penembus) yang didistribusikan oleh PT Trimarga Nusantara Indonesia. Produk ini diformulasikan khusus untuk meningkatkan kualitas air semprot serta memaksimalkan kinerja pestisida (insektisida & fungisida) dan pupuk cair pada tanaman.\r\n\r\nSpesifikasi Produk :\r\nNama Produk : Biosoft\r\nJenis : Surfaktan / Adjuvant Premium\r\nBentuk : Cair\r\n\r\nFungsi Utama :\r\nMeningkatkan daya basah dan penyebaran larutan pada permukaan daun\r\nMenurunkan dan menjaga pH larutan semprot agar tetap ideal\r\nMeningkatkan efektivitas pestisida, insektisida, fungisida, dan pupuk cair\r\nMembantu penyerapan bahan aktif lebih cepat ke jaringan tanaman\r\n\r\nKeunggulan :\r\nMeningkatkan kualitas air semprotan\r\nMembuat kinerja pestisida lebih maksimal dan efisien\r\nMengoptimalkan hasil aplikasi di lapangan\r\nCocok sebagai bahan pelengkap (adjuvant) untuk berbagai jenis campuran semprot\"\r\n\r\n', 'PILARCLOTRIN_145135ZC_200ML.jpg', 136500, 130000, 132600, 434, 0, NULL, 'Botol', 'Box', '120', 'Pilih Tipe Produk', 220, 1, '2026-04-22 11:21:48', 0),
(496, 9, 'D5S1X1LI1157500216', 'Dmectin 530 SL 12 X 1 ltr', '\"D’Mectin 530 SL adalah insektisida kontak dan sistemik berspektrum luas yang mengombinasikan dua bahan aktif kuat, yaitu Dimehipo dan Abamektin, sehingga efektif mengendalikan berbagai jenis hama pada tanaman pangan dan hortikultura.\r\n\r\nSpesifikasi Produk :\r\nNama Produk : D’Mectin 530 SL\r\nBentuk Formulasi : SL (Soluble Liquid) – larutan cair yang mudah larut dalam air\r\nJenis : Insektisida kontak dan sistemik\r\n\r\nBahan Aktif : Dimehipo dan Abamektin\"\r\n\r\n', 'DMECTIN_530SL_1LITER.jpg', 165375, 157500, 160650, 0, 0, NULL, 'Botol', 'Box', '0', 'Pilih Tipe Produk', 1200, 1, '2026-04-22 11:30:16', 0),
(497, 9, 'D5S2X5MI987500691', 'Dmectin 530 SL 20 X 500 ml', '\"D’Mectin 530 SL adalah insektisida kontak dan sistemik berspektrum luas yang mengombinasikan dua bahan aktif kuat, yaitu Dimehipo dan Abamektin, sehingga efektif mengendalikan berbagai jenis hama pada tanaman pangan dan hortikultura.\r\n\r\nSpesifikasi Produk :\r\nNama Produk : D’Mectin 530 SL\r\nBentuk Formulasi : SL (Soluble Liquid) – larutan cair yang mudah larut dalam air\r\nJenis : Insektisida kontak dan sistemik\r\n\r\nBahan Aktif : Dimehipo dan Abamektin\"\r\n\r\n', 'DMECTIN_530SL_500ML.jpg', 91875, 87500, 89250, 100, 0, NULL, 'Botol', 'Box', '20', 'Pilih Tipe Produk', 520, 1, '2026-04-22 13:01:31', 0),
(498, 9, 'D5S2X2MI550000740', 'Dmectin 530 SL 24 X 250 ml', '\"D’Mectin 530 SL adalah insektisida kontak dan sistemik berspektrum luas yang mengombinasikan dua bahan aktif kuat, yaitu Dimehipo dan Abamektin, sehingga efektif mengendalikan berbagai jenis hama pada tanaman pangan dan hortikultura.\r\n\r\nSpesifikasi Produk :\r\nNama Produk : D’Mectin 530 SL\r\nBentuk Formulasi : SL (Soluble Liquid) – larutan cair yang mudah larut dalam air\r\nJenis : Insektisida kontak dan sistemik\r\n\r\nBahan Aktif : Dimehipo dan Abamektin\"\r\n\r\n', 'DMECTIN_530SL_250ML.jpg', 52500, 50000, 51000, 120, 0, NULL, 'Botol', 'Box', '24', 'Pilih Tipe Produk', 270, 1, '2026-04-22 13:02:20', 0);
INSERT INTO `products` (`id`, `category_id`, `sku`, `name`, `description`, `picture_name`, `price`, `price_3`, `price_2`, `stock`, `current_discount`, `product_unit`, `product_unit_1`, `product_unit_2`, `product_unit_value`, `product_type`, `product_unit_weight`, `is_available`, `add_date`, `user_level`) VALUES
(499, 20, 'GC5X1MZ555000823', 'GG Cuaca 50 X 100 ml', '\"GG Cuaca adalah nutrisi pelengkap tanaman berbentuk larutan yang diformulasikan sebagai perisai tanaman terhadap stres lingkungan, terutama akibat cuaca ekstrem seperti panas berlebih, hujan tinggi, atau perubahan iklim yang tidak menentu.\r\n\r\nSpesifikasi Produk :\r\nNama Produk : GG Cuaca\r\nJenis : Nutrisi pelengkap tanaman / ZPT (Zat Pengatur Tumbuh)\r\nBentuk : Larutan (SL)\r\n\r\nBahan Aktif Utama : Indole Butyric Acid (IBA)\r\nDiperkaya dengan enzim, vitamin, dan asam amino\"', 'GG_CUACA_100ML.jpg', 57750, 55000, 56100, 100, 0, NULL, 'Botol', 'Box', '50', 'Pilih Tipe Produk', 120, 1, '2026-04-22 13:03:43', 0),
(500, 19, 'GR2X5MPC767500880', 'GA Recovery 20 X 500 ml', '\"GA Premium Recovery adalah pupuk cair organik sekaligus Zat Pengatur Tumbuh (ZPT) organik yang diformulasikan khusus untuk memulihkan tanaman yang mengalami stres atau kerusakan akibat berbagai faktor lingkungan maupun kesalahan teknis budidaya.\r\n\r\nSpesifikasi Produk :\r\nNama Produk : GA Premium Recovery\r\nJenis : Pupuk Cair Organik / ZPT Organik\r\nBentuk : Cair\r\n\r\nFungsi Utama :\r\nMemulihkan tanaman yang layu, menguning, atau terhambat pertumbuhannya\r\nMerangsang kembali pertumbuhan akar, daun, dan tunas baru\r\nMengembalikan metabolisme tanaman agar kembali normal\"', 'GA_RECOVERY_500ML.jpg', 70875, 67500, 68850, 83, 0, NULL, 'Botol', 'Box', '0', 'Pilih Tipe Produk', 520, 1, '2026-04-22 13:04:40', 0),
(501, 20, 'GD5X1MZ775000137', 'GG Daun 50 X 100 ml', '\"GG DAUN adalah nutrisi pelengkap tanaman yang diformulasikan untuk menunjang seluruh fase pertumbuhan, mulai dari fase vegetatif (daun) hingga generatif (bunga, buah, dan umbi). Produk ini membantu tanaman tumbuh optimal dengan suplai nutrisi yang seimbang.\r\n\r\nSpesifikasi Produk :\r\nNama Produk : GG DAUN\r\nJenis : Nutrisi pelengkap tanaman\r\nBentuk : Cair\r\n\r\nFungsi Utama :\r\nMendukung pertumbuhan daun agar lebih hijau dan lebat\r\nMembantu proses pembentukan bunga dan buah\r\nMenjaga keseimbangan nutrisi selama masa pertumbuhan\r\nMeningkatkan kualitas dan kuantitas hasil panen\"', 'GG_CUACA_100ML1.jpg', 78750, 75000, 76500, 269, 0, NULL, 'Botol', 'Box', '0', '', 120, 1, '2026-04-22 13:08:57', 0),
(502, 1, 'B2E2X4MF1168000201', 'Bencore 250 EC 20 X 400 ml', '\"Bencore 250 EC adalah fungisida sistemik berbentuk pekatan yang dapat diemulsikan (Emulsifiable Concentrate / EC) yang mengandung bahan aktif Difenokonazol 250 g/l. Produk ini efektif untuk mengendalikan penyakit jamur pada tanaman, terutama pada padi.\r\n\r\nSpesifikasi Produk :\r\nNama Produk : Bencore 250 EC\r\nBentuk Formulasi : EC (Emulsifiable Concentrate)\r\nJenis : Fungisida sistemik\r\n\r\nBahan Aktif :Difenokonazol 250 g/l\"\r\n', 'BENCORE_250EC_400ML.jpg', 176400, 168000, 171360, 1, 0, NULL, 'Botol', 'Box', '0', 'Pilih Tipe Produk', 420, 1, '2026-04-22 13:10:01', 0),
(503, 1, 'B2E2X2MF987000298', 'Bencore 250 EC 20 X 200 ml', '\"Bencore 250 EC adalah fungisida sistemik berbentuk pekatan yang dapat diemulsikan (Emulsifiable Concentrate / EC) yang mengandung bahan aktif Difenokonazol 250 g/l. Produk ini efektif untuk mengendalikan penyakit jamur pada tanaman, terutama pada padi.\r\n\r\nSpesifikasi Produk :\r\nNama Produk : Bencore 250 EC\r\nBentuk Formulasi : EC (Emulsifiable Concentrate)\r\nJenis : Fungisida sistemik\r\n\r\nBahan Aktif :Difenokonazol 250 g/l\"\r\n', 'BENCORE_250EC_200ML.jpg', 91350, 87000, 88740, 3, 0, NULL, 'Botol', 'Box', '0', 'Pilih Tipe Produk', 220, 1, '2026-04-22 13:11:38', 0),
(504, 13, 'R4X2M2195000907', 'Robust 40 X 200 ml', '', NULL, 204750, 195000, 198900, 22, 0, NULL, 'Botol', 'Box', '100', 'Pilih Tipe Produk', 220, 1, '2026-05-05 10:48:27', 0),
(505, 9, 'A5E2X4MI336200108', 'Amabas 500 EC 20 X 400 ml', '', 'AMABAS_500EC_400ML1.jpg', 48510, 47124, 46200, 251, 0, NULL, 'Botol', 'Box', '100', '', 420, 1, '2026-05-12 09:15:08', 0),
(506, 9, 'L5E2X4MI00431', 'Licron 500 EC 20 X 400 ml', '\"Licron 500 EC adalah insektisida racun kontak dan lambung berbentuk pekatan yang dapat diemulsikan (Emulsifiable Concentrate / EC) yang mengandung bahan aktif Profenofos. Produk ini efektif untuk mengendalikan berbagai hama tanaman, terutama pada bawang merah seperti ulat grayak, ulat buah, kutu daun, jangkrik, dan penggerek.\r\n\r\nSpesifikasi Produk :\r\nNama Produk : Licron 500 EC\r\nBentuk Formulasi : EC (Emulsifiable Concentrate)\r\nJenis : Insektisida kontak dan lambung\r\n\r\nBahan Aktif : Profenofos\r\nTarget Hama : Ulat grayak, ulat buah, kutu daun, jangkrik, dan penggerek\r\nTanaman Sasaran : Bawang merah (utama) dan tanaman pertanian/perkebunan lainnya\"', 'LICRON_500_EC_400ML.jpg', 999, 999, 999, 36, 0, NULL, 'Pcs', 'Box', '20', '', 420, 1, '2026-05-13 13:40:31', 0),
(507, 2, 'P2S4X5LH00507', 'Passxone 276 SL 4 X 5 ltr', '\"Passxone 276 SL adalah herbisida kontak purna tumbuh berbentuk larutan (Soluble Liquid / SL) yang mengandung bahan aktif Parakuat Diklorida 276 g/l. Produk ini dikenal sebagai “herbisida pembakar” karena bekerja sangat cepat dalam mengendalikan gulma, dengan efek langsung membuat bagian tanaman yang terkena semprotan menjadi kering dan mati dalam waktu singkat.\r\n\r\nSpesifikasi Produk :\r\nNama Produk : Passxone 276 SL\r\nBentuk Formulasi : SL (Soluble Liquid)\r\nJenis : Herbisida kontak purna tumbuh\r\n\r\nBahan Aktif : Parakuat Diklorida 276 g/l\r\nCara Kerja : Kontak (hanya mematikan bagian tanaman yang terkena semprotan, tidak sampai ke akar)\r\nTarget Gulma : Berbagai jenis gulma daun lebar, rumput liar, dan gulma semusim lainnya\r\nAplikasi : Cocok digunakan pada lahan pertanian, perkebunan, dan area non-budidaya\"\r\n', 'PASSXONE_276SL_5LITER.jpg', 999, 999, 999, 272, 0, NULL, 'Botol', 'Box', '1000', '', 5200, 1, '2026-05-13 13:41:47', 0),
(508, 2, 'P2S2LH00548', 'Passxone 276 SL 20 ltr', '\"Passxone 276 SL adalah herbisida kontak purna tumbuh berbentuk larutan (Soluble Liquid / SL) yang mengandung bahan aktif Parakuat Diklorida 276 g/l. Produk ini dikenal sebagai “herbisida pembakar” karena bekerja sangat cepat dalam mengendalikan gulma, dengan efek langsung membuat bagian tanaman yang terkena semprotan menjadi kering dan mati dalam waktu singkat.\r\n\r\nSpesifikasi Produk :\r\nNama Produk : Passxone 276 SL\r\nBentuk Formulasi : SL (Soluble Liquid)\r\nJenis : Herbisida kontak purna tumbuh\r\n\r\nBahan Aktif : Parakuat Diklorida 276 g/l\r\nCara Kerja : Kontak (hanya mematikan bagian tanaman yang terkena semprotan, tidak sampai ke akar)\r\nTarget Gulma : Berbagai jenis gulma daun lebar, rumput liar, dan gulma semusim lainnya\r\nAplikasi : Cocok digunakan pada lahan pertanian, perkebunan, dan area non-budidaya\"\r\n', 'PASSXONE_276SL_20LITER.jpg', 999, 999, 999, 0, 0, NULL, 'Botol', 'Box', '10000', '', 22000, 1, '2026-05-13 13:42:28', 0),
(509, 2, 'C4S2X1LH00694', 'Chief 480 SL 20 X 1 ltr', '\"Chief 480 SL adalah herbisida sistemik purna tumbuh berbentuk larutan (Soluble Liquid / SL) yang mengandung bahan aktif Isopropil Amina Glifosat 480 g/l (setara dengan glifosat 356 g/l). Produk ini efektif untuk membasmi berbagai jenis gulma hingga ke akar, sehingga memberikan pengendalian yang lebih tuntas, terutama pada lahan perkebunan dan persiapan lahan pertanian.\r\n\r\nSpesifikasi Produk :\r\nNama Produk : Chief 480 SL\r\nBentuk Formulasi : SL (Soluble Liquid)\r\nJenis : Herbisida sistemik purna tumbuh\r\n\r\nBahan Aktif : Isopropil Amina Glifosat 480 g/l (setara glifosat 356 g/l)\r\nCara Kerja : Sistemik (diserap melalui daun dan ditranslokasikan ke seluruh bagian tanaman hingga ke akar dan rimpang)\r\nTarget Gulma : Gulma daun lebar, gulma golongan rumput, dan teki-tekian\r\nAplikasi : Cocok digunakan pada perkebunan (seperti kelapa sawit) dan persiapan lahan pertanian\"\r\n\r\n', 'CHIEF_480SL_1LITER.jpg', 999, 999, 999, 2278, 0, NULL, 'Botol', 'Box', '1000', '', 1200, 1, '2026-05-13 13:44:54', 0),
(510, 2, 'C4S4X5LH00736', 'Chief 480 SL 4 X 5 ltr', '\"Chief 480 SL adalah herbisida sistemik purna tumbuh berbentuk larutan (Soluble Liquid / SL) yang mengandung bahan aktif Isopropil Amina Glifosat 480 g/l (setara dengan glifosat 356 g/l). Produk ini efektif untuk membasmi berbagai jenis gulma hingga ke akar, sehingga memberikan pengendalian yang lebih tuntas, terutama pada lahan perkebunan dan persiapan lahan pertanian.\r\n\r\nSpesifikasi Produk :\r\nNama Produk : Chief 480 SL\r\nBentuk Formulasi : SL (Soluble Liquid)\r\nJenis : Herbisida sistemik purna tumbuh\r\n\r\nBahan Aktif : Isopropil Amina Glifosat 480 g/l (setara glifosat 356 g/l)\r\nCara Kerja : Sistemik (diserap melalui daun dan ditranslokasikan ke seluruh bagian tanaman hingga ke akar dan rimpang)\r\nTarget Gulma : Gulma daun lebar, gulma golongan rumput, dan teki-tekian\r\nAplikasi : Cocok digunakan pada perkebunan (seperti kelapa sawit) dan persiapan lahan pertanian\"\r\n\r\n', 'CHIEF_480SL_5LITER.jpg', 999, 999, 999, 135, 0, NULL, 'Botol', 'Box', '1000', '', 5200, 1, '2026-05-13 13:45:36', 0),
(511, 2, 'C4S2LH00777', 'Chief 480 SL 20 ltr', '\"Chief 480 SL adalah herbisida sistemik purna tumbuh berbentuk larutan (Soluble Liquid / SL) yang mengandung bahan aktif Isopropil Amina Glifosat 480 g/l (setara dengan glifosat 356 g/l). Produk ini efektif untuk membasmi berbagai jenis gulma hingga ke akar, sehingga memberikan pengendalian yang lebih tuntas, terutama pada lahan perkebunan dan persiapan lahan pertanian.\r\n\r\nSpesifikasi Produk :\r\nNama Produk : Chief 480 SL\r\nBentuk Formulasi : SL (Soluble Liquid)\r\nJenis : Herbisida sistemik purna tumbuh\r\n\r\nBahan Aktif : Isopropil Amina Glifosat 480 g/l (setara glifosat 356 g/l)\r\nCara Kerja : Sistemik (diserap melalui daun dan ditranslokasikan ke seluruh bagian tanaman hingga ke akar dan rimpang)\r\nTarget Gulma : Gulma daun lebar, gulma golongan rumput, dan teki-tekian\r\nAplikasi : Cocok digunakan pada perkebunan (seperti kelapa sawit) dan persiapan lahan pertanian\"\r\n\r\n', 'CHIEF_480SL_20LITER1.jpg', 999, 999, 999, 24, 0, NULL, 'Pilih Satuan Product', 'Pilih Satuan Product', '1000', '', 2200, 1, '2026-05-13 13:46:17', 0),
(512, 9, 'B2S4X1MI00280', 'Baledo 250/50 SC 40 X 100 ml', 'Baledo 250/50 SC 40 X 100 ml', 'BALEDO_25050SC_100ML.jpg', 999, 999, 999, 360, 0, NULL, 'Botol', 'Box', '10000', '', 120, 1, '2026-05-13 13:54:40', 0),
(513, 1, 'P8W1X1KF00413', 'Perozin 80 WP 14 X 1 kg', '\"Perozin 80 WP adalah fungisida kontak berbentuk tepung (Wettable Powder / WP) berwarna kuning muda yang mengandung bahan aktif Zineb 80% serta tambahan Zinc (Zn) 3%. Produk ini berfungsi sebagai fungisida pelindung yang sangat efektif dalam mengendalikan berbagai penyakit jamur pada tanaman, terutama bercak daun, hawar daun, dan karat.\r\nSpesifikasi Produk :\r\nNama Produk : Perozin 80 WP\r\nBentuk Formulasi : WP (Wettable Powder)\r\nJenis : Fungisida kontak (protektif)\r\nBahan Aktif : Zineb 80% + Zinc (Zn) 3%\r\nCara Kerja : Kontak (melindungi permukaan tanaman dari serangan jamur sebelum infeksi terjadi)\"\r\n', 'PEROZIN_80WP_1KG.jpg', 999, 999, 999, 554, 0, NULL, 'Botol', 'Box', '1000', '', 1200, 1, '2026-05-13 13:56:53', 0),
(514, 1, 'P2E4X2MF00597', 'Piraklo 250 EC 40 X 250 ml', '\"Piraklo 250 EC adalah fungisida sistemik berbentuk pekatan yang dapat diemulsikan (Emulsifiable Concentrate / EC) dengan bahan aktif Piraklostrobin 250 g/l. Produk ini bersifat protektif dan kuratif, efektif untuk mengendalikan penyakit jamur pada tanaman padi, bawang merah, dan cabai, sekaligus membantu meningkatkan kesehatan tanaman.\r\n\r\nSpesifikasi Produk :\r\nNama Produk : Piraklo 250 EC\r\nBentuk Formulasi : EC (Emulsifiable Concentrate)\r\nJenis : Fungisida sistemik\r\n\r\nBahan Aktif : Piraklostrobin 250 g/l\r\nCara Kerja : Sistemik, protektif, dan kuratif (mencegah serta mengobati penyakit dengan cara diserap ke dalam jaringan tanaman)\"\r\n', 'PIRAKLO_250EC_250ML1.jpg', 999, 999, 999, 65956, 0, NULL, 'Botol', 'Box', '1000', '', 270, 1, '2026-05-13 13:59:57', 0),
(515, 1, 'P2E1X1MF00633', 'Piraklo 250 EC 100 X 100 ml', '\"Piraklo 250 EC adalah fungisida sistemik berbentuk pekatan yang dapat diemulsikan (Emulsifiable Concentrate / EC) dengan bahan aktif Piraklostrobin 250 g/l. Produk ini bersifat protektif dan kuratif, efektif untuk mengendalikan penyakit jamur pada tanaman padi, bawang merah, dan cabai, sekaligus membantu meningkatkan kesehatan tanaman.\r\n\r\nSpesifikasi Produk :\r\nNama Produk : Piraklo 250 EC\r\nBentuk Formulasi : EC (Emulsifiable Concentrate)\r\nJenis : Fungisida sistemik\r\n\r\nBahan Aktif : Piraklostrobin 250 g/l\r\nCara Kerja : Sistemik, protektif, dan kuratif (mencegah serta mengobati penyakit dengan cara diserap ke dalam jaringan tanaman)\"\r\n', 'PIRAKLO_250EC_100ML.jpg', 999, 999, 999, 34590, 0, NULL, 'Botol', 'Box', '1000', '', 120, 1, '2026-05-13 14:00:33', 0),
(516, 9, 'A3W1X2X5GI00689', 'Armeira 30 WG 10 X 20 X 50 gr', '\"Armeira 30 WG adalah insektisida racun kontak dan lambung berbentuk butiran yang dapat terdispersi dalam air (Water Dispersible Granule / WG) berwarna putih, dengan bahan aktif Indosakarb 30%. Produk ini efektif mengendalikan hama ulat pada berbagai tanaman, terutama kubis, dengan cara kerja cepat menghentikan aktivitas makan hama.\r\n\r\nSpesifikasi Produk :\r\nNama Produk : Armeira 30 WG\r\nBentuk Formulasi : WG (Water Dispersible Granule)\r\nJenis : Insektisida kontak dan lambung\r\n\r\nBahan Aktif : Indosakarb 30%\r\nCara Kerja : Kontak dan lambung (menghentikan aktivitas makan hama sehingga cepat mati)\"', 'ARMEIRA_30WG_50GRAM.jpg', 999, 999, 999, 23972, 0, NULL, 'Pcs', 'Box', '1000', '', 70, 1, '2026-05-13 14:01:29', 0),
(517, 1, 'B1A5X2MF00746', 'Bactocyn 150 AL 50 X 200 ml', '\"Bactocyn 150 AL adalah bakterisida sekaligus fungisida sistemik berbentuk larutan (Aqueous Liquid / AL) berwarna coklat yang mengandung bahan aktif Oksitetrasiklin atau Copper Hydroxide 150 g/l. Produk ini efektif mengendalikan berbagai penyakit akibat bakteri dan jamur pada tanaman, sehingga membantu menjaga kesehatan dan produktivitas tanaman.\r\n\r\nSpesifikasi Produk :\r\nNama Produk : Bactocyn 150 AL\r\nBentuk Formulasi : AL (Aqueous Liquid)\r\nJenis : Bakterisida dan fungisida sistemik\r\n\r\nBahan Aktif : Oksitetrasiklin / Copper Hydroxide 150 g/l\r\nCara Kerja : Sistemik (diserap ke dalam jaringan tanaman dan bekerja mengendalikan bakteri serta jamur dari dalam)\"\r\n', 'BACTOCYN_150AL_200ML.jpg', 999, 999, 999, 31807, 0, NULL, 'Botol', 'Box', '1000', '', 220, 1, '2026-05-13 14:02:26', 0),
(518, 1, 'B1A1X1MF00781', 'Bactocyn 150 AL 100 X 100 ml', '\"Bactocyn 150 AL adalah bakterisida sekaligus fungisida sistemik berbentuk larutan (Aqueous Liquid / AL) berwarna coklat yang mengandung bahan aktif Oksitetrasiklin atau Copper Hydroxide 150 g/l. Produk ini efektif mengendalikan berbagai penyakit akibat bakteri dan jamur pada tanaman, sehingga membantu menjaga kesehatan dan produktivitas tanaman.\r\n\r\nSpesifikasi Produk :\r\nNama Produk : Bactocyn 150 AL\r\nBentuk Formulasi : AL (Aqueous Liquid)\r\nJenis : Bakterisida dan fungisida sistemik\r\n\r\nBahan Aktif : Oksitetrasiklin / Copper Hydroxide 150 g/l\r\nCara Kerja : Sistemik (diserap ke dalam jaringan tanaman dan bekerja mengendalikan bakteri serta jamur dari dalam)\"\r\n', 'BACTOCYN_150AL_100ML.jpg', 999, 999, 999, 11811, 0, NULL, 'Botol', 'Box', '1000', '', 120, 1, '2026-05-13 14:03:01', 0),
(519, 9, 'Q3E2X5MI00834', 'Qiumex 36 EC 20 X 500 ml', '\"Qiumex 36 EC adalah insektisida racun kontak dan lambung berbentuk pekatan yang dapat diemulsikan (Emulsifiable Concentrate / EC) berwarna kuning muda, dengan bahan aktif Abamektin 36 g/l. Produk ini efektif mengendalikan berbagai hama penghisap dan penggorok daun pada tanaman hortikultura dan pertanian.\r\n\r\nSpesifikasi Produk :\r\nNama Produk : Qiumex 36 EC\r\nBentuk Formulasi : EC (Emulsifiable Concentrate)\r\nJenis : Insektisida kontak dan lambung (translaminar)\r\n\r\nBahan Aktif : Abamektin 36 g/l\r\nCara Kerja : Kontak, lambung, dan sistemik terbatas (translaminar) yang bekerja pada sistem saraf hama sehingga menghentikan aktivitas makan dan perkembangan\"\r\n\r\n\r\n', 'QIUMEX_36EC_500ML.jpg', 999, 999, 999, 1885, 0, NULL, 'Botol', 'Box', '100', '', 520, 1, '2026-05-13 14:03:54', 0),
(520, 9, 'Q3E1X1MI00867', 'Qiumex 36 EC 100 X 100 ml', '\"Qiumex 36 EC adalah insektisida racun kontak dan lambung berbentuk pekatan yang dapat diemulsikan (Emulsifiable Concentrate / EC) berwarna kuning muda, dengan bahan aktif Abamektin 36 g/l. Produk ini efektif mengendalikan berbagai hama penghisap dan penggorok daun pada tanaman hortikultura dan pertanian.\r\n\r\nSpesifikasi Produk :\r\nNama Produk : Qiumex 36 EC\r\nBentuk Formulasi : EC (Emulsifiable Concentrate)\r\nJenis : Insektisida kontak dan lambung (translaminar)\r\n\r\nBahan Aktif : Abamektin 36 g/l\r\nCara Kerja : Kontak, lambung, dan sistemik terbatas (translaminar) yang bekerja pada sistem saraf hama sehingga menghentikan aktivitas makan dan perkembangan\"\r\n\r\n\r\n', 'QIUMEX_36EC_100ML.jpg', 999, 999, 999, 7444, 0, NULL, 'Botol', 'Box', '100', '', 120, 1, '2026-05-13 14:04:27', 0),
