(522, 9, 'Q3E1X1LI00951', 'Qiumex 36 EC 10 X 1 ltr', '\"Qiumex 36 EC adalah insektisida racun kontak dan lambung berbentuk pekatan yang dapat diemulsikan (Emulsifiable Concentrate / EC) berwarna kuning muda, dengan bahan aktif Abamektin 36 g/l. Produk ini efektif mengendalikan berbagai hama penghisap dan penggorok daun pada tanaman hortikultura dan pertanian.\r\n\r\nSpesifikasi Produk :\r\nNama Produk : Qiumex 36 EC\r\nBentuk Formulasi : EC (Emulsifiable Concentrate)\r\nJenis : Insektisida kontak dan lambung (translaminar)\r\n\r\nBahan Aktif : Abamektin 36 g/l\r\nCara Kerja : Kontak, lambung, dan sistemik terbatas (translaminar) yang bekerja pada sistem saraf hama sehingga menghentikan aktivitas makan dan perkembangan\"\r\n', 'QIUMEX_36EC_1LITER.jpg', 999, 999, 999, 749, 0, NULL, 'Botol', 'Box', '1000', '', 1200, 1, '2026-05-13 14:05:51', 0),
(523, 9, 'U1S4X2MI00110', 'Unihit 100/20 SC 40 X 250 ml', '\"Unihit 100/20 SC adalah insektisida sekaligus akarisida majemuk berbentuk pekatan suspensi (Suspension Concentrate / SC) yang mengandung bahan aktif Klorfenapir dan Emamektin Benzoat. Produk ini bekerja secara kontak dan lambung serta memiliki efek translaminar, sehingga efektif mengendalikan hama ulat, kutu, dan tungau pada berbagai tanaman.\r\n\r\nSpesifikasi Produk :\r\nNama Produk : Unihit 100/20 SC\r\nBentuk Formulasi : SC (Suspension Concentrate)\r\nJenis : Insektisida dan akarisida\r\n\r\nBahan Aktif : Klorfenapir + Emamektin Benzoat\r\nCara Kerja : Kontak, lambung, dan translaminar (menembus jaringan daun untuk perlindungan lebih merata)\"\r\n\r\n', 'UNIHIT_10020_SC_250ML.jpg', 999, 999, 999, 78, 0, NULL, 'Botol', 'Box', '1000', '', 270, 1, '2026-05-13 14:08:30', 0),
