(573, 2, 'N2O4X2MH774000176', 'Nikodem 240/10 OD 40 X 250 ml', '\"Nikodem 240/10 OD adalah herbisida selektif sistemik purna-tumbuh berbentuk larutan minyak (Oil Dispersion/OD) yang dirancang khusus untuk membasmi gulma berdaun lebar maupun sempit pada tanaman jagung. Produk ini efektif memberikan pengendalian gulma yang tuntas dan mendukung pertumbuhan tanaman yang sehat.\r\n\r\nPotensi Hasil: Mengendalikan gulma secara selektif, melindungi tanaman jagung, dan mendukung hasil panen optimal\r\nBahan Aktif: Atrazine 240 g/L, Topramezone 10 g/L\r\nBentuk Formulasi: Oil Dispersion (OD)\r\nTanaman Sasaran: Jagung\r\nKemasan: 1 liter, 500ml, 250ml\"\r\n\r\n', 'NIKODEM_250ML1.jpg', 77700, 74000, 75480, 8644, 0, NULL, 'Botol', 'Box', '120', 'Pilih Tipe Produk', 270, 1, '2026-05-20 14:29:36', 0),
(574, 1, 'B2W4X2GF1108000330', 'Bump 25/40 WP 40 X 250 gr', '\"BUMP 25/40 WP adalah fungisida sistemik berbentuk tepung (Wettable Powder/WP) yang efektif untuk proteksi maupun kuratif terhadap penyakit blas (Pyricularia oryzae) atau patah leher pada tanaman padi sawah. Produk ini membantu menjaga kesehatan tanaman dan mendukung hasil panen optimal.\r\n\r\nPotensi Hasil: Melindungi tanaman dari penyakit blas, mencegah kerusakan batang dan daun, serta mendukung hasil panen maksimal\r\nBahan Aktif: Isoprotiolan 25%, Trisiklazol 40%\r\nBentuk Formulasi: Wettable Powder (WP)\r\nTanaman Sasaran: Padi sawah\r\nKemasan: 250, 100, 25 gram\"\r\n\r\n', 'BUMP_2540WP_250GRAM1.jpg', 113400, 108000, 110160, 2165, 0, NULL, 'Pcs', 'Box', '120', 'Pilih Tipe Produk', 270, 1, '2026-05-20 14:32:10', 0),
(575, 1, 'B2W1X1GF445000394', 'Bump 25/40 WP 100 X 100 gr', '\"BUMP 25/40 WP adalah fungisida sistemik berbentuk tepung (Wettable Powder/WP) yang efektif untuk proteksi maupun kuratif terhadap penyakit blas (Pyricularia oryzae) atau patah leher pada tanaman padi sawah. Produk ini membantu menjaga kesehatan tanaman dan mendukung hasil panen optimal.\r\n\r\nPotensi Hasil: Melindungi tanaman dari penyakit blas, mencegah kerusakan batang dan daun, serta mendukung hasil panen maksimal\r\nBahan Aktif: Isoprotiolan 25%, Trisiklazol 40%\r\nBentuk Formulasi: Wettable Powder (WP)\r\nTanaman Sasaran: Padi sawah\r\nKemasan: 250, 100, 25 gram\"\r\n\r\n', 'BUMP_2540WP_100GRAM1.jpg', 47250, 45000, 45900, 9389, 0, NULL, 'Pcs', 'Box', '100', 'Pilih Tipe Produk', 120, 1, '2026-05-20 14:33:14', 0),
(576, 1, 'B2W5X4X2GF112750446', 'Bump 25/40 WP 5 X 40 X 25 gr', '\"BUMP 25/40 WP adalah fungisida sistemik berbentuk tepung (Wettable Powder/WP) yang efektif untuk proteksi maupun kuratif terhadap penyakit blas (Pyricularia oryzae) atau patah leher pada tanaman padi sawah. Produk ini membantu menjaga kesehatan tanaman dan mendukung hasil panen optimal.\r\n\r\nPotensi Hasil: Melindungi tanaman dari penyakit blas, mencegah kerusakan batang dan daun, serta mendukung hasil panen maksimal\r\nBahan Aktif: Isoprotiolan 25%, Trisiklazol 40%\r\nBentuk Formulasi: Wettable Powder (WP)\r\nTanaman Sasaran: Padi sawah\r\nKemasan: 250, 100, 25 gram\"\r\n\r\n', 'BUMP_2540WP_25GRAM1.jpg', 13388, 12750, 13005, 2300, 0, NULL, 'Pcs', 'Box', '100', 'Pilih Tipe Produk', 27, 1, '2026-05-20 14:34:06', 0),
(577, 13, 'TB3X4GLL228500548', 'Topsil B/K 30 X 450 gr', '\"Topsil B/K adalah pupuk daun majemuk berbentuk bubuk yang larut dalam air, dirancang khusus untuk meningkatkan hasil panen, mencegah kerontokan bunga atau buah, dan mempercepat pematangan. Pupuk ini mengandung N (16%), P (1%), K (21%), serta unsur mikro lengkap, sehingga ideal digunakan pada fase generatif (pembuahan/pembungaan) tanaman.\r\n\r\nPotensi Hasil: Meningkatkan hasil panen, mencegah kerontokan bunga/buah, dan mempercepat pematangan\r\nBahan Aktif: N 16%, P 1%, K 21%, + unsur mikro\r\nBentuk Formulasi: Bubuk larut air\r\nTanaman Sasaran: Tanaman buah, sayuran, dan tanaman generatif lainnya\r\nKemasan: 450 gram\"', 'TOPSIL_B_450GRAM1.jpg', 29925, 28500, 29070, 5710, 0, NULL, 'Pcs', 'Box', '120', 'Pilih Tipe Produk', 470, 1, '2026-05-20 14:35:48', 0),
(578, 2, 'S1S2X1LH228000673', 'Starquat 135 SL 20 X 1 ltr', '\"Starquat 135 SL adalah herbisida kontak purna-tumbuh berbentuk larutan biru kehijauan dengan bahan aktif Parakuat Diklorida. Produk ini efektif membasmi gulma berdaun lebar maupun sempit (rumput) pada tanaman kelapa sawit, jagung, dan lahan tanpa tanaman. Starquat 135 SL bekerja cepat (2–3 jam) mematikan bagian hijau gulma dan tahan terhadap hujan.\r\n\r\nPotensi Hasil: Membasmi gulma secara efektif, melindungi tanaman pokok, dan mendukung pertumbuhan optimal\r\nBahan Aktif: Parakuat Diklorida 135 g/L\r\nBentuk Formulasi: Soluble Liquid (SL)\r\nTanaman Sasaran: Kelapa sawit, jagung, dan lahan tanpa tanaman\r\nKemasan: 20, 5, 1 liter\"\r\n\r\n', 'STARQUAT_135SL_1LITER1.jpg', 28350, 27000, 27540, 2890, 0, NULL, 'Botol', 'Box', '100', '', 1200, 1, '2026-05-20 14:37:53', 0),
(579, 2, 'S1S4X5LH113500731', 'Starquat 135 SL 4 X 5 ltr', '\"Starquat 135 SL adalah herbisida kontak purna-tumbuh berbentuk larutan biru kehijauan dengan bahan aktif Parakuat Diklorida. Produk ini efektif membasmi gulma berdaun lebar maupun sempit (rumput) pada tanaman kelapa sawit, jagung, dan lahan tanpa tanaman. Starquat 135 SL bekerja cepat (2–3 jam) mematikan bagian hijau gulma dan tahan terhadap hujan.\r\n\r\nPotensi Hasil: Membasmi gulma secara efektif, melindungi tanaman pokok, dan mendukung pertumbuhan optimal\r\nBahan Aktif: Parakuat Diklorida 135 g/L\r\nBentuk Formulasi: Soluble Liquid (SL)\r\nTanaman Sasaran: Kelapa sawit, jagung, dan lahan tanpa tanaman\r\nKemasan: 20, 5, 1 liter\"\r\n\r\n', 'STARQUAT_135SL_5LITER1.jpg', 136500, 130000, 132600, 100, 0, NULL, 'Botol', 'Box', '8', '', 5200, 1, '2026-05-20 14:38:51', 0),
(580, 2, 'S1S2LH5520000795', 'Starquat 135 SL 20 ltr', '\"Starquat 135 SL adalah herbisida kontak purna-tumbuh berbentuk larutan biru kehijauan dengan bahan aktif Parakuat Diklorida. Produk ini efektif membasmi gulma berdaun lebar maupun sempit (rumput) pada tanaman kelapa sawit, jagung, dan lahan tanpa tanaman. Starquat 135 SL bekerja cepat (2–3 jam) mematikan bagian hijau gulma dan tahan terhadap hujan.\r\n\r\nPotensi Hasil: Membasmi gulma secara efektif, melindungi tanaman pokok, dan mendukung pertumbuhan optimal\r\nBahan Aktif: Parakuat Diklorida 135 g/L\r\nBentuk Formulasi: Soluble Liquid (SL)\r\nTanaman Sasaran: Kelapa sawit, jagung, dan lahan tanpa tanaman\r\nKemasan: 20, 5, 1 liter\"\r\n\r\n', 'STARQUAT_135SL_20LITER1.jpg', 525000, 500000, 510000, 25, 0, NULL, 'Botol', 'Box', '0', '', 22000, 1, '2026-05-20 14:39:55', 0),
(581, 13, 'TD3X4GLL228500854', 'Topsil D/H 30 X 450 gr', '\"Topsil D (Daun) adalah pupuk daun majemuk berbentuk bubuk yang larut dalam air, dirancang untuk memacu pertumbuhan vegetatif tanaman, termasuk daun dan ranting. Mengandung nutrisi makro (N, P, K) dan mikro lengkap, pupuk ini meningkatkan fotosintesis, kesuburan daun, dan pertumbuhan awal tanaman.\r\n\r\nPotensi Hasil: Mempercepat pertumbuhan vegetatif, meningkatkan fotosintesis, dan mendukung daun serta ranting yang sehat\r\nBahan Aktif: N, P, K + unsur mikro\r\nBentuk Formulasi: Bubuk larut air\r\nTanaman Sasaran: Semua tanaman pada fase vegetatif\r\nDosis: 10–30 gr/10 liter air\r\nKemasan: 450 gram\"', 'TOPSIL_D_450GRAM1.jpg', 29925, 28500, 29070, 2454, 0, NULL, 'Pcs', 'Box', '120', 'Pilih Tipe Produk', 470, 1, '2026-05-20 14:40:54', 0),
(582, 9, 'M2W4X2GI1135000980', 'Mutual 25/25 WP 40 X 250 gr', '\"Mutual 25/25 WP adalah insektisida sistemik, kontak, dan lambung berbentuk tepung (Wettable Powder/WP) yang sangat efektif mengendalikan hama penghisap seperti thrips, kutu kebul, kutu coklat, dan kutu loncat. Produk ini bekerja dengan meracuni hama sekaligus menghambat pertumbuhan mereka, sehingga pengendalian hama lebih tuntas.\r\n\r\nPotensi Hasil: Mengendalikan hama penghisap secara efektif, mencegah kerusakan tanaman, dan mendukung hasil panen optimal\r\nBahan Aktif: Asetamiprid 25%, Buprofezin 25%\r\nBentuk Formulasi: Wettable Powder (WP)\r\nTanaman Sasaran: Padi, jagung, cabai, sayuran\r\nKemasan: 100 dan 250 gram\"\r\n', 'MUTUAL_250GRAM1.jpg', 166950, 159000, 162180, 1922, 0, NULL, 'Pcs', 'Box', '120', '', 270, 1, '2026-05-20 14:43:00', 0),
(583, 9, 'M2W1X1GI660000030', 'Mutual 25/25 WP 100 X 100 gr', '\"Mutual 25/25 WP adalah insektisida sistemik, kontak, dan lambung berbentuk tepung (Wettable Powder/WP) yang sangat efektif mengendalikan hama penghisap seperti thrips, kutu kebul, kutu coklat, dan kutu loncat. Produk ini bekerja dengan meracuni hama sekaligus menghambat pertumbuhan mereka, sehingga pengendalian hama lebih tuntas.\r\n\r\nPotensi Hasil: Mengendalikan hama penghisap secara efektif, mencegah kerusakan tanaman, dan mendukung hasil panen optimal\r\nBahan Aktif: Asetamiprid 25%, Buprofezin 25%\r\nBentuk Formulasi: Wettable Powder (WP)\r\nTanaman Sasaran: Padi, jagung, cabai, sayuran\r\nKemasan: 100 dan 250 gram\"\r\n', 'MUTUAL_100GRAM1.jpg', 72450, 69000, 70380, 6905, 0, NULL, 'Pcs', 'Box', '100', '', 120, 1, '2026-05-20 14:43:50', 0),
(584, 2, 'AU4S2X1LH447000250', 'Amco Up 486 SL 20 X 1 ltr', '\"Amco Up 486 SL adalah herbisida sistemik purna-tumbuh berbahan aktif Isopropil Amina Glifosat, berbentuk larutan kuning jernih. Produk ini efektif mengendalikan gulma berdaun lebar maupun sempit hingga ke akar, sehingga tanaman terlindungi dari persaingan gulma. Amco Up 486 SL cocok digunakan pada jagung (TOT), kelapa sawit (TBM), dan karet.\r\n\r\nPotensi Hasil: Membasmi gulma secara tuntas, melindungi tanaman pokok, dan mendukung pertumbuhan optimal\r\nBahan Aktif: Isopropil Amina Glifosat\r\nBentuk Formulasi: Soluble Liquid (SL)\r\nTanaman Sasaran: Jagung (TOT), kelapa sawit (TBM), karet\r\nKemasan: 20, 5, 1 liter\"\r\n\r\n', 'AMCOUP_486SL_1LITER1.jpg', 47250, 45900, 45000, 6515, 0, NULL, 'Botol', 'Box', '100', '', 1200, 1, '2026-05-20 14:47:30', 0),
(585, 2, 'AU4S4X5LH2230000311', 'Amco Up 486 SL 4 X 5 ltr', '\"Amco Up 486 SL adalah herbisida sistemik purna-tumbuh berbahan aktif Isopropil Amina Glifosat, berbentuk larutan kuning jernih. Produk ini efektif mengendalikan gulma berdaun lebar maupun sempit hingga ke akar, sehingga tanaman terlindungi dari persaingan gulma. Amco Up 486 SL cocok digunakan pada jagung (TOT), kelapa sawit (TBM), dan karet.\r\n\r\nPotensi Hasil: Membasmi gulma secara tuntas, melindungi tanaman pokok, dan mendukung pertumbuhan optimal\r\nBahan Aktif: Isopropil Amina Glifosat\r\nBentuk Formulasi: Soluble Liquid (SL)\r\nTanaman Sasaran: Jagung (TOT), kelapa sawit (TBM), karet\r\nKemasan: 20, 5, 1 liter\"\r\n\r\n', 'AMCOUP_486SL_5LITER1.jpg', 231000, 224400, 220000, 0, 0, NULL, 'Botol', 'Box', '0', '', 5200, 1, '2026-05-20 14:48:31', 0),
(586, 2, 'AU4S2LH9900000388', 'Amco Up 486 SL 20 ltr', '\"Amco Up 486 SL adalah herbisida sistemik purna-tumbuh berbahan aktif Isopropil Amina Glifosat, berbentuk larutan kuning jernih. Produk ini efektif mengendalikan gulma berdaun lebar maupun sempit hingga ke akar, sehingga tanaman terlindungi dari persaingan gulma. Amco Up 486 SL cocok digunakan pada jagung (TOT), kelapa sawit (TBM), dan karet.\r\n\r\nPotensi Hasil: Membasmi gulma secara tuntas, melindungi tanaman pokok, dan mendukung pertumbuhan optimal\r\nBahan Aktif: Isopropil Amina Glifosat\r\nBentuk Formulasi: Soluble Liquid (SL)\r\nTanaman Sasaran: Jagung (TOT), kelapa sawit (TBM), karet\r\nKemasan: 20, 5, 1 liter\"\r\n\r\n', 'AMCOUP_486SL_20LITER1.jpg', 903000, 87720, 86000, 0, 0, NULL, 'Botol', 'Box', '0', '', 22000, 1, '2026-05-20 14:49:48', 0),
(587, 13, 'ODD14X1GLL221500489', 'Osmocote Dekastar Daun 17-11-10 40 X 100 gr', '\"Osmocote Dekastar Daun 17-11-10 adalah pupuk majemuk slow release (lepas lambat) berkualitas tinggi yang dirancang untuk merangsang pertumbuhan vegetatif tanaman, termasuk daun dan batang, agar lebih subur dan hijau. Dengan kandungan N 17%, P 11%, K 10%, serta mikro-nutrisi lengkap, pupuk ini melepaskan hara secara terkendali hingga 170 hari, sehingga ideal untuk tanaman hias, aglaonema, bonsai, dan pembibitan.\r\n\r\nPotensi Hasil: Mempercepat pertumbuhan vegetatif, meningkatkan kesuburan daun dan batang, dan mendukung tanaman yang sehat dan hijau\r\nBahan Aktif: N 17%, P 11%, K 10% + mikro-nutrisi\r\nBentuk Formulasi: Slow Release Granule\r\nTanaman Sasaran: Tanaman hias, aglaonema, bonsai, pembibitan\r\nKemasan: 100 gram\"', 'OSMOCOTE_DEKASTAR_DAUN_100GRAM1.jpg', 22575, 21500, 21930, 40, 0, NULL, 'Pcs', 'Box', '120', 'Pilih Tipe Produk', 120, 1, '2026-05-20 14:51:29', 0),
(588, 12, 'BPMSP657000978', 'Benang Pe mlg', '\"Benang PE Malang adalah sarana produksi pertanian (saprotan) berupa tali/benang sintetis yang sangat serbaguna. Terbuat dari serat polietilen yang kuat, benang ini tersedia dalam bentuk anyaman (braided) atau pilinan (twisted), dan sangat diandalkan untuk mendukung berbagai aktivitas perkebunan maupun hortikultura.\r\n\r\nPotensi Hasil: Memudahkan pengikatan tanaman, mendukung perawatan tanaman, dan meningkatkan efisiensi kerja di lapangan\r\nBahan Aktif: Serat Polietilen (PE)\r\nBentuk Formulasi: Anyaman (Braided) / Pilinan (Twisted)\r\nPenggunaan: Perkebunan, hortikultura, pembibitan, dan kegiatan pertanian umum\"', 'BENANG_PE_MLG_25KG1.jpg', 61047, 57000, 58140, 0, 0, NULL, 'Pcs', 'Sak', '0', 'Pilih Tipe Produk', 270, 1, '2026-05-21 14:52:58', 0),
(589, 14, 'JB92X1KB1100000045', 'Jagung Bisi 959 20 X 1 kg', '\"Jagung Bisi 959 adalah benih jagung hibrida F1 unggulan yang memiliki ketahanan terhadap penyakit seperti bulai, karat, dan hawar daun, Benih ini cocok ditanam di dataran rendah hingga tinggi dengan umur panen sekitar 100–103 HST, dan memiliki biji tipe semi-mutiara berwarna oranye kekuningan.\r\n\r\nPotensi Hasil: Produktivitas tinggi, tahan terhadap penyakit, dan cocok untuk berbagai kondisi lahan\r\nJenis Benih: Hibrida F1\r\nUmur Panen: 100–103 HST\r\nBentuk Biji: Semi-mutiara, oranye kekuningan\r\nTanah Sasaran: Dataran rendah hingga tinggi\r\n\"', 'JAGUNG_BISI959_1KG1.jpg', 105000, 100000, 102000, 20, 0, NULL, 'Pcs', 'Box', '100', 'Pilih Tipe Produk', 1200, 1, '2026-05-21 14:54:05', 0),
(590, 9, 'DF1S2X5MI1189000121', 'DK Fenzo 120 SC 20 X 500 ml', '\"DK FENZO 120 SC adalah insektisida racun kontak dan lambung produksi Danken Indonesia yang diformulasikan dengan kombinasi bahan aktif klorfenapir 100 g/l dan emamektin benzoat 20 g/l. Insektisida ini bekerja sangat cepat dan efektif untuk mengendalikan berbagai hama penting pada tanaman sayuran dan tanaman pangan, sehingga tanaman tetap sehat dan hasil panen lebih optimal.\r\n\r\nPotensi Hasil: Pengendalian hama lebih tuntas, tanaman terlindungi lebih lama, dan produktivitas meningkat\r\nBahan Aktif: Klorfenapir 100 g/l + Emamektin Benzoat 20 g/l\r\nBentuk Formulasi: SC (Suspension Concentrate) – pekatan suspensi berwarna putih pucat\r\nCara Kerja: Racun kontak dan lambung dengan daya kerja cepat\r\n\r\nKeunggulan:\r\nMampu menghentikan aktivitas makan ulat dalam waktu 3–5 jam, efektif membasmi hingga ke telur, serta memiliki risiko resistensi yang rendah sehingga lebih aman untuk penggunaan berulang sesuai anjuran.\r\n\r\nDosis Umum: 1 – 2 ml per liter air\r\n\r\nTarget Hama:\r\nUlat grayak, ulat tanah, sundep/penggerek batang, wereng, kutu kebul, belalang, walang sangit\r\n\r\nTanaman Sasaran:\r\nBawang merah, kubis, kentang, tomat, cabai, jagung, dan berbagai tanaman hortikultura lainnya\r\n\r\nUkuran Kemasan:\r\n100 ml, 250 ml, 500 ml\"\r\n\r\n', 'DKFENZO_120SC_500ML1.jpg', 198450, 189000, 192780, 0, 0, NULL, 'Botol', 'Box', '0', 'Pilih Tipe Produk', 520, 1, '2026-05-21 14:55:21', 0),
(591, 9, 'DF1S4X2MI198000165', 'DK Fenzo 120 SC 40 X 250 ml', '\"DK FENZO 120 SC adalah insektisida racun kontak dan lambung produksi Danken Indonesia yang diformulasikan dengan kombinasi bahan aktif klorfenapir 100 g/l dan emamektin benzoat 20 g/l. Insektisida ini bekerja sangat cepat dan efektif untuk mengendalikan berbagai hama penting pada tanaman sayuran dan tanaman pangan, sehingga tanaman tetap sehat dan hasil panen lebih optimal.\r\n\r\nPotensi Hasil: Pengendalian hama lebih tuntas, tanaman terlindungi lebih lama, dan produktivitas meningkat\r\nBahan Aktif: Klorfenapir 100 g/l + Emamektin Benzoat 20 g/l\r\nBentuk Formulasi: SC (Suspension Concentrate) – pekatan suspensi berwarna putih pucat\r\nCara Kerja: Racun kontak dan lambung dengan daya kerja cepat\r\n\r\nKeunggulan:\r\nMampu menghentikan aktivitas makan ulat dalam waktu 3–5 jam, efektif membasmi hingga ke telur, serta memiliki risiko resistensi yang rendah sehingga lebih aman untuk penggunaan berulang sesuai anjuran.\r\n\r\nDosis Umum: 1 – 2 ml per liter air\r\n\r\nTarget Hama:\r\nUlat grayak, ulat tanah, sundep/penggerek batang, wereng, kutu kebul, belalang, walang sangit\r\n\r\nTanaman Sasaran:\r\nBawang merah, kubis, kentang, tomat, cabai, jagung, dan berbagai tanaman hortikultura lainnya\r\n\r\nUkuran Kemasan:\r\n100 ml, 250 ml, 500 ml\"\r\n\r\n', 'DKFENZO_120SC_250ML1.jpg', 102900, 98000, 99960, 0, 0, NULL, 'Botol', 'Box', '0', 'Pilih Tipe Produk', 270, 1, '2026-05-21 14:56:05', 0),
(592, 9, 'DF1S5X1MI440500204', 'DK Fenzo 120 SC 50 X 100 ml', '\"DK FENZO 120 SC adalah insektisida racun kontak dan lambung produksi Danken Indonesia yang diformulasikan dengan kombinasi bahan aktif klorfenapir 100 g/l dan emamektin benzoat 20 g/l. Insektisida ini bekerja sangat cepat dan efektif untuk mengendalikan berbagai hama penting pada tanaman sayuran dan tanaman pangan, sehingga tanaman tetap sehat dan hasil panen lebih optimal.\r\n\r\nPotensi Hasil: Pengendalian hama lebih tuntas, tanaman terlindungi lebih lama, dan produktivitas meningkat\r\nBahan Aktif: Klorfenapir 100 g/l + Emamektin Benzoat 20 g/l\r\nBentuk Formulasi: SC (Suspension Concentrate) – pekatan suspensi berwarna putih pucat\r\nCara Kerja: Racun kontak dan lambung dengan daya kerja cepat\r\n\r\nKeunggulan:\r\nMampu menghentikan aktivitas makan ulat dalam waktu 3–5 jam, efektif membasmi hingga ke telur, serta memiliki risiko resistensi yang rendah sehingga lebih aman untuk penggunaan berulang sesuai anjuran.\r\n\r\nDosis Umum: 1 – 2 ml per liter air\r\n\r\nTarget Hama:\r\nUlat grayak, ulat tanah, sundep/penggerek batang, wereng, kutu kebul, belalang, walang sangit\r\n\r\nTanaman Sasaran:\r\nBawang merah, kubis, kentang, tomat, cabai, jagung, dan berbagai tanaman hortikultura lainnya\r\n\r\nUkuran Kemasan:\r\n100 ml, 250 ml, 500 ml\"\r\n\r\n', 'DKFENZO_120SC_100ML1.jpg', 42525, 40500, 41525, 0, 0, NULL, 'Botol', 'Box', '0', 'Pilih Tipe Produk', 120, 1, '2026-05-21 14:56:44', 0),
(593, 2, 'B2S2LH9940000254', 'Bravoxone 276 SL 20 ltr', '\"Herbisida ini mengandung Paraquat Dichloride 276 g/l yang bekerja secara kontak untuk membasmi dan mengendalikan gulma berdaun lebar, gulma daun sempit, serta gulma teki dengan cepat dan efektif.\r\n\r\nKeunggulan:\r\nMampu mengeringkan gulma dalam waktu singkat, cocok untuk pembersihan lahan dan pengendalian gulma pada tanaman belum menghasilkan (TBM).\r\n\r\nTanaman Sasaran:\r\nKopi TBM, kelapa sawit TBM, kakao TBM, lada, jagung, tebu, HTI, Acacia mangium, serta persiapan lahan padi sawah sistem TOT (tanpa olah tanah) dan pasang surut.\"\r\n\r\n', 'BRAVOXONE_276SL_20LITER1.jpg', 987000, 940000, 958800, 22, 0, NULL, 'Botol', 'Box', '0', 'Pilih Tipe Produk', 20000, 1, '2026-05-21 14:57:34', 0),
(594, 2, 'B2S4X5LH2240000303', 'Bravoxone 276 SL 4 X 5 ltr', '\"Herbisida ini mengandung Paraquat Dichloride 276 g/l yang bekerja secara kontak untuk membasmi dan mengendalikan gulma berdaun lebar, gulma daun sempit, serta gulma teki dengan cepat dan efektif.\r\n\r\nKeunggulan:\r\nMampu mengeringkan gulma dalam waktu singkat, cocok untuk pembersihan lahan dan pengendalian gulma pada tanaman belum menghasilkan (TBM).\r\n\r\nTanaman Sasaran:\r\nKopi TBM, kelapa sawit TBM, kakao TBM, lada, jagung, tebu, HTI, Acacia mangium, serta persiapan lahan padi sawah sistem TOT (tanpa olah tanah) dan pasang surut.\"\r\n\r\n', 'BRAVOXONE_276SL_5LITER1.jpg', 252000, 240000, 244800, 318, 0, NULL, 'Botol', 'Box', '8', 'Pilih Tipe Produk', 50000, 1, '2026-05-21 14:58:23', 0),
(595, 2, 'B2S2X1LH549000492', 'Bravoxone 276 SL 20 X 1 ltr', '\"Herbisida ini mengandung Paraquat Dichloride 276 g/l yang bekerja secara kontak untuk membasmi dan mengendalikan gulma berdaun lebar, gulma daun sempit, serta gulma teki dengan cepat dan efektif.\r\n\r\nKeunggulan:\r\nMampu mengeringkan gulma dalam waktu singkat, cocok untuk pembersihan lahan dan pengendalian gulma pada tanaman belum menghasilkan (TBM).\r\n\r\nTanaman Sasaran:\r\nKopi TBM, kelapa sawit TBM, kakao TBM, lada, jagung, tebu, HTI, Acacia mangium, serta persiapan lahan padi sawah sistem TOT (tanpa olah tanah) dan pasang surut.\"\r\n\r\n', 'BRAVOXONE_276SL_1LITER1.jpg', 51450, 49000, 49980, 18097, 0, NULL, 'Botol', 'Box', '100', 'Pilih Tipe Produk', 1200, 1, '2026-05-21 15:01:32', 0),
(596, 9, 'D4S2X4GI881000543', 'Dumil 40 SP 25 X 400 gr', '\"Dumil 40 SP adalah insektisida sistemik berbentuk tepung (SP) berwarna biru dengan bahan aktif Metomil 40% yang bekerja sebagai racun kontak dan lambung untuk mengendalikan berbagai hama penting pada tanaman.\r\n\r\nKeunggulan:\r\nEfektif dan cepat mengendalikan hama penghisap maupun pengunyah, meresap ke dalam jaringan tanaman sehingga perlindungan lebih maksimal.\r\nBahan Aktif:\r\nMetomil 40%\r\nCara Kerja:\r\nSistemik, kontak, dan lambung — diserap oleh tanaman lalu meracuni hama saat terkena langsung atau saat memakan bagian tanaman.\r\nTarget Hama:\r\nUlat grayak, ulat api, penggerek buah, kutu kebul, belalang, wereng, lalat buah, dan hama perusak daun lainnya.\r\nTanaman Sasaran:\r\nPadi, cabai, bawang merah, teh, tomat, kentang, melon, dan semangka.\"\r\n', 'DUMIL_40SP_400GRAM1.jpg', 85050, 81000, 82620, 0, 0, NULL, 'Pcs', 'Box', '100', 'Pilih Tipe Produk', 420, 1, '2026-05-21 15:02:23', 0),
(597, 9, 'D4S1X1GI222000577', 'Dumil 40 SP 100 X 100 gr', '\"Dumil 40 SP adalah insektisida sistemik berbentuk tepung (SP) berwarna biru dengan bahan aktif Metomil 40% yang bekerja sebagai racun kontak dan lambung untuk mengendalikan berbagai hama penting pada tanaman.\r\n\r\nKeunggulan:\r\nEfektif dan cepat mengendalikan hama penghisap maupun pengunyah, meresap ke dalam jaringan tanaman sehingga perlindungan lebih maksimal.\r\nBahan Aktif:\r\nMetomil 40%\r\nCara Kerja:\r\nSistemik, kontak, dan lambung — diserap oleh tanaman lalu meracuni hama saat terkena langsung atau saat memakan bagian tanaman.\r\nTarget Hama:\r\nUlat grayak, ulat api, penggerek buah, kutu kebul, belalang, wereng, lalat buah, dan hama perusak daun lainnya.\r\nTanaman Sasaran:\r\nPadi, cabai, bawang merah, teh, tomat, kentang, melon, dan semangka.\"\r\n', 'DUMIL_40SP_100GRAM1.jpg', 23100, 22000, 22025, 0, 0, NULL, 'Pcs', 'Box', '100', 'Pilih Tipe Produk', 120, 1, '2026-05-21 15:02:57', 0),
(598, 20, 'P0W8X1X2GZ110000620', 'Pilaroptim 0.136 WP 8 X 100 X 2 gr', '\"Pilaroptim 0.136 WP adalah Zat Pengatur Tumbuh (ZPT) majemuk berbentuk tepung larut air (WP) yang diformulasikan untuk merangsang pertumbuhan, meningkatkan kualitas, serta memaksimalkan produktivitas tanaman. Kombinasi hormon tumbuh di dalamnya bekerja sinergis untuk memperkuat tanaman sejak fase vegetatif hingga generatif.\r\n\r\nKandungan Bahan Aktif:\r\nAsam Giberelat (Gibberellic acid), Asam Indol-3-asetat (IAA), dan 14-hydroxylated brassinosteroid.\r\n\r\nFungsi & Manfaat:\r\nMerangsang pertumbuhan vegetatif (akar, batang, dan daun), meningkatkan pembungaan dan pembuahan, membantu mengurangi kerontokan bunga dan buah, serta meningkatkan ketahanan tanaman terhadap stres lingkungan seperti kekeringan dan serangan penyakit.\r\n\r\nCara Kerja:\r\nDiserap oleh jaringan tanaman dan mengatur aktivitas fisiologis sehingga pertumbuhan lebih optimal, seragam, dan hasil panen meningkat baik dari segi jumlah maupun kualitas.\"', 'PILAROPTIM_2GRAM1.jpg', 10500, 10000, 10200, 0, 0, NULL, 'Pcs', 'Box', '100', 'Pilih Tipe Produk', 7, 1, '2026-05-21 15:03:40', 0),
(599, 9, 'A7S5X1GI223000688', 'Ace-One 75 SP 50 X 100 gr', '\"Ace-One 75 SP adalah insektisida sistemik dengan racun kontak dan lambung berbentuk tepung kuning muda yang mudah larut dalam air. Mengandung bahan aktif Asefat 75% yang efektif untuk mengendalikan berbagai hama penghisap dan pengunyah pada tanaman hortikultura sehingga tanaman tumbuh sehat dan produktif.\r\n\r\nKandungan Bahan Aktif:\r\nAsefat (Acephate) 75%\r\n\r\nCara Kerja:\r\nDiserap oleh jaringan tanaman (sistemik) serta bekerja sebagai racun kontak dan lambung, sehingga hama mati baik saat terkena semprotan maupun saat memakan bagian tanaman.\r\n\r\nTarget Hama:\r\nUlat daun, ulat krop (Plutella xylostella), ulat grayak, kutu daun, sundep/penggerek, lalat buah, dan hama penghisap lainnya.\r\n\r\nTanaman Sasaran:\r\nCabai, kubis, bawang merah, kelapa sawit, serta berbagai tanaman hortikultura lainnya.\"\r\n', 'ACE-ONE_75SP_100GRAM1.jpg', 24150, 23460, 23000, 13, 0, NULL, 'Pcs', 'Box', '100', '', 120, 1, '2026-05-21 15:04:48', 0),
(600, 9, 'A7S2X4GI989000736', 'Ace-One 75 SP 25 X 400 gr', '\"Ace-One 75 SP adalah insektisida sistemik dengan racun kontak dan lambung berbentuk tepung kuning muda yang mudah larut dalam air. Mengandung bahan aktif Asefat 75% yang efektif untuk mengendalikan berbagai hama penghisap dan pengunyah pada tanaman hortikultura sehingga tanaman tumbuh sehat dan produktif.\r\n\r\nKandungan Bahan Aktif:\r\nAsefat (Acephate) 75%\r\n\r\nCara Kerja:\r\nDiserap oleh jaringan tanaman (sistemik) serta bekerja sebagai racun kontak dan lambung, sehingga hama mati baik saat terkena semprotan maupun saat memakan bagian tanaman.\r\n\r\nTarget Hama:\r\nUlat daun, ulat krop (Plutella xylostella), ulat grayak, kutu daun, sundep/penggerek, lalat buah, dan hama penghisap lainnya.\r\n\r\nTanaman Sasaran:\r\nCabai, kubis, bawang merah, kelapa sawit, serta berbagai tanaman hortikultura lainnya.\"\r\n', 'ACE-ONE_75SP_400GRAM1.jpg', 93450, 90780, 89000, 1256, 0, NULL, 'Pcs', 'Box', '100', '', 420, 1, '2026-05-21 15:05:36', 0),
(601, 20, 'B4S4X2MZ445500814', 'Braphon 488 SL 40 X 250 ml', '\"Braphon 488 SL adalah Zat Pengatur Tumbuh (ZPT) berbahan aktif Etefon 488 g/l berbentuk larutan pekat (SL) yang mudah dilarutkan dalam air. Produk ini berfungsi untuk mengatur pertumbuhan tanaman, mempercepat dan menyeragamkan kematangan buah, serta meningkatkan kualitas dan hasil panen. Cocok digunakan pada tanaman nenas, padi, pisang, tembakau, apel, kedelai, kopi, cabai, dan berbagai tanaman hortikultura lainnya.\r\n\r\nBahan Aktif: Etefon 488 g/l\r\nBentuk Formulasi: SL (Soluble Liquid)\r\nFungsi: Mempercepat pemasakan buah, merangsang pembungaan, menyeragamkan panen, dan meningkatkan mutu hasil\r\nCara Kerja: Diserap jaringan tanaman dan melepaskan hormon etilen untuk mengatur proses pertumbuhan dan pematangan.\"\r\n', 'BRAPHON_488SL_250ML1.jpg', 47775, 45500, 46410, 802, 0, NULL, 'Botol', 'Box', '100', 'Pilih Tipe Produk', 270, 1, '2026-05-21 15:06:54', 0),
(602, 20, 'B4S5X1MZ224000856', 'Braphon 488 SL 50 X 100 ml', '\"Braphon 488 SL adalah Zat Pengatur Tumbuh (ZPT) berbahan aktif Etefon 488 g/l berbentuk larutan pekat (SL) yang mudah dilarutkan dalam air. Produk ini berfungsi untuk mengatur pertumbuhan tanaman, mempercepat dan menyeragamkan kematangan buah, serta meningkatkan kualitas dan hasil panen. Cocok digunakan pada tanaman nenas, padi, pisang, tembakau, apel, kedelai, kopi, cabai, dan berbagai tanaman hortikultura lainnya.\r\n\r\nBahan Aktif: Etefon 488 g/l\r\nBentuk Formulasi: SL (Soluble Liquid)\r\nFungsi: Mempercepat pemasakan buah, merangsang pembungaan, menyeragamkan panen, dan meningkatkan mutu hasil\r\nCara Kerja: Diserap jaringan tanaman dan melepaskan hormon etilen untuk mengatur proses pertumbuhan dan pematangan.\"\r\n', 'BRAPHON_488SL_100ML1.jpg', 25200, 24000, 24480, 3, 0, NULL, 'Botol', 'Box', '100', 'Pilih Tipe Produk', 120, 1, '2026-05-21 15:07:36', 0),
(603, 2, 'B2S1X1LH885000963', 'Bastnate 200 SL 12 X 1 ltr', '\"Bastnate 200 SL adalah herbisida purna tumbuh non-selektif berbentuk larutan berwarna biru kehijauan dengan bahan aktif amonium glufosinat 200 g/l. Produk ini bekerja secara kontak dan sistemik untuk mengendalikan gulma berdaun lebar, gulma daun sempit, serta teki hingga ke akar. Cocok digunakan pada lahan perkebunan, pertanian, maupun area pekarangan karena memiliki daya kerja cepat dan hasil yang efektif.\r\n\r\nSpesifikasi Produk:\r\nBahan Aktif: Amonium Glufosinat 200 g/l (setara glufosinat 182,7 g/l)\r\nJenis: Herbisida purna tumbuh non-selektif\r\nBentuk Formulasi: SL (Soluble Liquid)\r\nCara Kerja: Kontak dan sistemik\r\n\r\nKeunggulan:\r\nAksi cepat, gulma menguning dalam 24–48 jam\r\nGulma mati sempurna hingga akar dalam 2–3 minggu\r\nEfektif untuk berbagai jenis gulma termasuk ilalang dan lulangan\r\nCocok untuk pertanaman muda maupun lahan terbuka\r\nMudah dicampur dan diaplikasikan\r\n\r\nTanaman & Area Aplikasi:\r\nKelapa sawit, karet, kakao, kopi, jagung, dan area non-budidaya/pekarangan.\"', 'BASTNATE_200SL_1LITER1.jpg', 89250, 85000, 86750, 1793, 0, NULL, 'Botol', 'Box', '100', 'Pilih Tipe Produk', 1200, 1, '2026-05-21 15:09:23', 0),
(604, 9, 'L4E2X5MI879000960', 'Logamate 440 EC 20 X 500 ml', '\"Logamate 440 EC adalah insektisida racun kontak dan lambung yang bersifat sistemik dengan bahan aktif Dimetoat 440 g/l. Berbentuk pekatan cair berwarna kekuningan, produk ini bekerja dengan cara meresap ke dalam jaringan tanaman sehingga mampu mengendalikan hama penghisap maupun pengunyah secara efektif. Cocok digunakan pada berbagai tanaman hortikultura dan tanaman pangan untuk menjaga pertumbuhan tetap optimal dan hasil panen maksimal.\r\n\r\nSpesifikasi Produk :Bahan Aktif: Dimetoat 440 g/l\r\nBentuk Formulasi : EC (Emulsifiable Concentrate)\r\nCara Kerja : Kontak, lambung, dan sistemik\r\nTarget Hama : Kutu daun (Myzus persicae), thrips, lalat buah, walang sangit, dan ulat perusak daun.\r\n\r\nTanaman Sasaran:\r\nKubis, cabai, padi, dan tanaman hortikultura lainnya.\"\r\n\r\n', 'LOGAMATE_440EC_500ML1.jpg', 82950, 79000, 80850, 0, 0, NULL, 'Botol', 'Box', '1000', 'Pilih Tipe Produk', 520, 1, '2026-05-22 13:56:00', 0),
(605, 9, 'L4E4X2MI441000011', 'Logamate 440 EC 40 x 250 ml', '\"Logamate 440 EC adalah insektisida racun kontak dan lambung yang bersifat sistemik dengan bahan aktif Dimetoat 440 g/l. Berbentuk pekatan cair berwarna kekuningan, produk ini bekerja dengan cara meresap ke dalam jaringan tanaman sehingga mampu mengendalikan hama penghisap maupun pengunyah secara efektif. Cocok digunakan pada berbagai tanaman hortikultura dan tanaman pangan untuk menjaga pertumbuhan tetap optimal dan hasil panen maksimal.\r\n\r\nSpesifikasi Produk :Bahan Aktif: Dimetoat 440 g/l\r\nBentuk Formulasi : EC (Emulsifiable Concentrate)\r\nCara Kerja : Kontak, lambung, dan sistemik\r\nTarget Hama : Kutu daun (Myzus persicae), thrips, lalat buah, walang sangit, dan ulat perusak daun.\r\n\r\nTanaman Sasaran:\r\nKubis, cabai, padi, dan tanaman hortikultura lainnya.\"\r\n\r\n', 'LOGAMATE_440EC_250ML1.jpg', 43050, 41000, 41820, 0, 0, NULL, 'Botol', 'Box', '100', 'Pilih Tipe Produk', 270, 1, '2026-05-22 13:56:51', 0),
(606, 9, 'L4E5X1MI117000046', 'Logamate 440 EC 50 x 100 ml', '\"Logamate 440 EC adalah insektisida racun kontak dan lambung yang bersifat sistemik dengan bahan aktif Dimetoat 440 g/l. Berbentuk pekatan cair berwarna kekuningan, produk ini bekerja dengan cara meresap ke dalam jaringan tanaman sehingga mampu mengendalikan hama penghisap maupun pengunyah secara efektif. Cocok digunakan pada berbagai tanaman hortikultura dan tanaman pangan untuk menjaga pertumbuhan tetap optimal dan hasil panen maksimal.\r\n\r\nSpesifikasi Produk :Bahan Aktif: Dimetoat 440 g/l\r\nBentuk Formulasi : EC (Emulsifiable Concentrate)\r\nCara Kerja : Kontak, lambung, dan sistemik\r\nTarget Hama : Kutu daun (Myzus persicae), thrips, lalat buah, walang sangit, dan ulat perusak daun.\r\n\r\nTanaman Sasaran:\r\nKubis, cabai, padi, dan tanaman hortikultura lainnya.\"\r\n\r\n', 'LOGAMATE_440EC_100ML1.jpg', 17850, 17000, 17340, 265, 0, NULL, 'Botol', 'Box', '100', 'Pilih Tipe Produk', 120, 1, '2026-05-22 13:57:26', 0),
(607, 2, 'S1S4X5LH1145000100', 'Spyker 135 SL 4 X 5 ltr', '\"Spyker 135 SL adalah herbisida kontak purna tumbuh berbentuk larutan dalam air yang diformulasikan dengan bahan aktif Parakuat Diklorida 135 g/l. Produk ini bekerja cepat dengan cara merusak jaringan hijau gulma yang terkena semprotan sehingga gulma mengering seperti terbakar. Efektif digunakan untuk mengendalikan berbagai jenis gulma berdaun lebar maupun berdaun sempit (rumput) pada lahan perkebunan, pertanian, dan tanaman sayuran, sehingga lahan tetap bersih dan tanaman utama dapat tumbuh optimal tanpa persaingan unsur hara.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Parakuat Diklorida (Paraquat Dichloride) 135 g/l\r\nBentuk Formulasi : SL (Soluble Liquid)\r\nJenis : Herbisida kontak non-selektif (purna tumbuh)\r\nCara Kerja : Merusak jaringan hijau gulma yang terkena semprotan (efek bakar cepat)\r\nTarget Gulma : Gulma berdaun lebar dan gulma berdaun sempit (rumput)\r\n\r\nTanaman Sasaran :\r\nKelapa sawit, jagung, tanaman perkebunan, tanaman pangan, dan sayuran.\"\r\n', 'SPYKER_135SL_5LITER1.jpg', 152250, 145000, 147900, 0, 0, NULL, 'Botol', 'Box', '100', 'Pilih Tipe Produk', 5200, 1, '2026-05-22 13:58:20', 0),
(608, 2, 'S1S2X1LH330000146', 'Spyker 135 SL 20 X 1 ltr', '\"Spyker 135 SL adalah herbisida kontak purna tumbuh berbentuk larutan dalam air yang diformulasikan dengan bahan aktif Parakuat Diklorida 135 g/l. Produk ini bekerja cepat dengan cara merusak jaringan hijau gulma yang terkena semprotan sehingga gulma mengering seperti terbakar. Efektif digunakan untuk mengendalikan berbagai jenis gulma berdaun lebar maupun berdaun sempit (rumput) pada lahan perkebunan, pertanian, dan tanaman sayuran, sehingga lahan tetap bersih dan tanaman utama dapat tumbuh optimal tanpa persaingan unsur hara.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Parakuat Diklorida (Paraquat Dichloride) 135 g/l\r\nBentuk Formulasi : SL (Soluble Liquid)\r\nJenis : Herbisida kontak non-selektif (purna tumbuh)\r\nCara Kerja : Merusak jaringan hijau gulma yang terkena semprotan (efek bakar cepat)\r\nTarget Gulma : Gulma berdaun lebar dan gulma berdaun sempit (rumput)\r\n\r\nTanaman Sasaran :\r\nKelapa sawit, jagung, tanaman perkebunan, tanaman pangan, dan sayuran.\"\r\n', 'SPYKER_135SL_1LITER1.jpg', 31500, 30000, 30600, 197, 0, NULL, 'Botol', 'Box', '100', 'Pilih Tipe Produk', 1200, 1, '2026-05-22 13:59:06', 0),
(609, 9, 'A5E3X5MI1137000200', 'Aneto 50 EC 30 X 500 ml', '\"Aneto 50 EC adalah insektisida sistemik berbahan aktif Fipronil 50 g/l dalam formulasi pekatan yang dapat diemulsikan (EC) yang bekerja cepat sebagai racun kontak, lambung, dan pernapasan. Produk ini mampu mengganggu sistem saraf serangga dengan memblokir saluran klorida sehingga hama berhenti makan, lumpuh, dan akhirnya mati. Efektif digunakan untuk mengendalikan berbagai hama penting, termasuk yang telah resisten terhadap insektisida golongan organofosfat dan karbamat, sehingga tanaman dapat tumbuh optimal dan terlindungi sejak dini.\r\n\r\nKarakteristik dan Keunggulan Aneto 50 EC :\r\nBahan Aktif : Fipronil 50 g/l\r\nBentuk Formulasi : EC (Emulsifiable Concentrate)\r\nCara Kerja : Sistemik, kontak, dan lambung (racun saraf)\r\nTarget Hama : Wereng coklat (Nilaparvata lugens), penggerek batang (Scirpophaga incertulas), ulat, kutu-kutuan, semut, dan rayap\r\nTanaman Sasaran : Padi, jagung, kakao, kubis, cabai, dan berbagai tanaman pertanian lainnya\r\n\r\nDosis Umum :\r\nDigunakan dengan penyemprotan volume tinggi, umumnya sekitar 1 – 2 ml/liter air atau disesuaikan dengan jenis tanaman serta tingkat serangan hama di lapangan.\"\r\n\r\n', 'ANETO_50EC_500ML1.jpg', 143850, 137000, 139740, 0, 0, NULL, 'Botol', 'Box', '100', 'Pilih Tipe Produk', 520, 1, '2026-05-22 14:00:00', 0);
