(681, 1, 'SO6W2X2X2GF9999363', 'Switch Off 62.5 WG 20 X 20 X 20 gr', 'Switch Off 62.5 WG adalah fungisida sistemik dan kontak berspektrum luas yang diformulasikan untuk mengendalikan berbagai penyakit jamur pada tanaman hortikultura. Dengan kombinasi bahan aktif Siprodinil 37,5% dan Fludioksonil 25%, produk ini memberikan perlindungan ganda, baik dari dalam maupun luar jaringan tanaman. Sangat efektif untuk mengendalikan penyakit seperti jamur abu-abu (Botrytis), bercak ungu, dan berbagai penyakit jamur lainnya pada bawang merah, cabai, serta aneka tanaman sayuran.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Siprodinil 37,5% + Fludioksonil 25%\r\nBentuk Formulasi : WG (Water Dispersible Granule)\r\nCara Kerja : Sistemik dan kontak\r\nKemasan : 20 gram', 'Switchoff.jpg', 999, 999, 999, 3467, 0, NULL, 'Pcs', 'Box', '0', 'Pilih Tipe Produk', 70, 1, '2026-05-30 11:12:43', 0),
(682, 1, 'H5S2X1LF9999683', 'Hexacar 50/50 SC 20 X 1 ltr', 'Hexacar 100 SC adalah fungisida sistemik berspektrum luas yang bersifat protektif dan kuratif, diformulasikan dalam bentuk pekatan suspensi (SC) berwarna putih. Produk ini mengandung kombinasi bahan aktif Heksakonazol 50 g/L dan Karbendazim 50 g/L yang bekerja efektif untuk mencegah sekaligus mengendalikan berbagai penyakit jamur pada tanaman pangan dan hortikultura.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Heksakonazol 50 g/L + Karbendazim 50 g/L\r\nBentuk Formulasi : SC (Suspension Concentrate)\r\nWarna : Putih\r\nCara Kerja : Sistemik, protektif, dan kuratif', 'Hexacar_1ltr.jpg', 999, 999, 999, 200, 0, NULL, 'Pcs', 'Box', '0', 'Pilih Tipe Produk', 1200, 1, '2026-05-30 11:34:43', 0),
(683, 1, 'H5S2X5MF9999727', 'Hexacar 50/50 SC 25 X 500 ml', 'Hexacar 100 SC adalah fungisida sistemik berspektrum luas yang bersifat protektif dan kuratif, diformulasikan dalam bentuk pekatan suspensi (SC) berwarna putih. Produk ini mengandung kombinasi bahan aktif Heksakonazol 50 g/L dan Karbendazim 50 g/L yang bekerja efektif untuk mencegah sekaligus mengendalikan berbagai penyakit jamur pada tanaman pangan dan hortikultura.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Heksakonazol 50 g/L + Karbendazim 50 g/L\r\nBentuk Formulasi : SC (Suspension Concentrate)\r\nWarna : Putih\r\nCara Kerja : Sistemik, protektif, dan kuratif', 'Hexacar_500ml.jpg', 999, 999, 999, 1617, 0, NULL, 'Pilih Satuan Product', 'Pilih Satuan Product', '0', 'Pilih Tipe Produk', 520, 1, '2026-05-30 11:35:27', 0),
(684, 1, 'H5S4X2MF9999780', 'Hexacar 50/50 SC 40 X 250 ml', 'Hexacar 100 SC adalah fungisida sistemik berspektrum luas yang bersifat protektif dan kuratif, diformulasikan dalam bentuk pekatan suspensi (SC) berwarna putih. Produk ini mengandung kombinasi bahan aktif Heksakonazol 50 g/L dan Karbendazim 50 g/L yang bekerja efektif untuk mencegah sekaligus mengendalikan berbagai penyakit jamur pada tanaman pangan dan hortikultura.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Heksakonazol 50 g/L + Karbendazim 50 g/L\r\nBentuk Formulasi : SC (Suspension Concentrate)\r\nWarna : Putih\r\nCara Kerja : Sistemik, protektif, dan kuratif', 'Hexacar_250ml.jpg', 999, 999, 999, 1825, 0, NULL, 'Pcs', 'Box', '0', 'Pilih Tipe Produk', 270, 1, '2026-05-30 11:36:20', 0),
(685, 1, 'H1S1X1MF9999812', 'Hexacar 100 SC 100 X 100 ml', 'Hexacar 100 SC adalah fungisida sistemik berspektrum luas yang bersifat protektif dan kuratif, diformulasikan dalam bentuk pekatan suspensi (SC) berwarna putih. Produk ini mengandung kombinasi bahan aktif Heksakonazol 50 g/L dan Karbendazim 50 g/L yang bekerja efektif untuk mencegah sekaligus mengendalikan berbagai penyakit jamur pada tanaman pangan dan hortikultura.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Heksakonazol 50 g/L + Karbendazim 50 g/L\r\nBentuk Formulasi : SC (Suspension Concentrate)\r\nWarna : Putih\r\nCara Kerja : Sistemik, protektif, dan kuratif', 'Hexacar_100ml.jpg', 999, 999, 999, 2010, 0, NULL, 'Pcs', 'Box', '0', 'Pilih Tipe Produk', 120, 1, '2026-05-30 11:36:52', 0),
(686, 9, 'K1E1X1MI9999269', 'Ken-Mida 12/50 EC 100 X 100 ml', 'Ken-Mida 12/50 EC adalah insektisida racun kontak dan lambung berbentuk pekatan yang dapat diemulsikan (EC) berwarna kuning, produksi Kenso Indonesia. Produk ini diformulasikan dengan kombinasi bahan aktif Emamektin Benzoat 12 g/l dan Imidakloprid 50 g/l yang bekerja efektif untuk mengendalikan hama pengunyah maupun penghisap pada berbagai tanaman budidaya.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Emamektin Benzoat 12 g/l + Imidakloprid 50 g/l\r\nBentuk Formulasi : EC (Emulsifiable Concentrate)\r\nWarna : Kuning\r\nCara Kerja : Racun kontak dan lambung', 'WhatsApp_Image_2026-05-30_at_10_13_08(2).jpeg', 999, 999, 999, 1804, 0, NULL, 'Botol', 'Box', '0', 'Pilih Tipe Produk', 120, 1, '2026-05-30 11:44:29', 0),
(687, 9, 'PAK1E2M+K3E2M2X1PI9999133', 'Paket Ampuh Ken-Mida 12/50 EC 250 ml + Kenmectin 39 EC 250 ml 24 X 1 paket', 'Paket Ampuh Ken-Mida + Kenmectin adalah paket insektisida kombinasi dari Kenso Indonesia yang diformulasikan untuk mengendalikan berbagai hama utama pada tanaman hortikultura, terutama ulat buah, ulat grayak, thrips, kutu daun, dan kutu kebul. Perpaduan dua produk dengan bahan aktif berbeda memberikan pengendalian yang lebih luas, cepat, dan efektif sehingga tanaman dapat tumbuh lebih sehat dan produktif.\r\n\r\n1. Ken-Mida 12/50 EC (250 ml)\r\n\r\nKen-Mida 12/50 EC merupakan insektisida racun kontak dan lambung yang mengandung kombinasi bahan aktif Emamektin Benzoat 12 g/l dan Imidakloprid 50 g/l.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Emamektin Benzoat 12 g/l + Imidakloprid 50 g/l\r\nBentuk Formulasi : EC (Emulsifiable Concentrate)\r\nCara Kerja : Kontak dan lambung\r\n\r\nFungsi :\r\nMengendalikan ulat buah, ulat grayak, kutu daun, thrips, dan kutu kebul.\r\nImidakloprid bekerja secara sistemik sehingga mampu melindungi tanaman dari hama penghisap yang bersembunyi pada jaringan tanaman.\r\nSangat efektif membantu mengatasi kutu kebul penyebab keriting daun pada cabai.\r\n\r\n2. Kenmectin 39 EC (250 ml)\r\n\r\nKenmectin 39 EC adalah insektisida berbahan aktif Abamektin 39 g/l yang bekerja sebagai racun kontak dan lambung dengan sifat translaminar.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Abamektin 39 g/l\r\nBentuk Formulasi : EC (Emulsifiable Concentrate)\r\nCara Kerja : Kontak, lambung, dan translaminar\r\n\r\nFungsi :\r\nEfektif mengendalikan ulat grayak (Spodoptera exigua), thrips, dan tungau.\r\nMampu menembus lapisan daun sehingga hama yang bersembunyi di bawah permukaan daun tetap dapat dikendalikan.\r\nMembantu menghentikan aktivitas makan hama dengan cepat.', 'WhatsApp_Image_2026-05-30_at_10_13_16.jpeg', 999, 999, 999, 755, 0, NULL, 'Pcs', 'Box', '0', 'Pilih Tipe Produk', 270, 1, '2026-05-30 11:58:53', 0),
(688, 13, 'S1X1MLL9999518', 'Silken 100 X 100 ml', 'Silken adalah surfaktan organosilikon berkualitas tinggi yang diformulasikan untuk meningkatkan efektivitas aplikasi pestisida dan pupuk daun. Dengan kandungan Polyether Modified Polysiloxane 1020 g/L, Silken berfungsi sebagai perekat, perata, penembus, dan pembasah, sehingga larutan semprot dapat menyebar lebih merata dan menembus permukaan daun secara optimal.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Polyether Modified Polysiloxane 1020 g/L\r\nJenis : Surfaktan Organosilikon\r\nBentuk Formulasi : Cairan pekat', 'WhatsApp_Image_2026-05-30_at_10_13_05(1).jpeg', 999, 999, 999, 0, 0, NULL, 'Pcs', 'Box', '0', 'Pilih Tipe Produk', 120, 1, '2026-05-30 13:45:18', 0),
(689, 1, 'T4S2X4MF9999053', 'Tinker 400 SC 20 X 400 ml', 'Tinker 400 SC adalah fungisida kontak dan sistemik berbentuk pekatan suspensi (SC) yang diformulasikan untuk mencegah dan mengendalikan berbagai penyakit jamur pada tanaman hortikultura. Dengan kombinasi dua bahan aktif yang saling melengkapi, produk ini efektif memberikan perlindungan sekaligus pengendalian terhadap penyakit busuk daun dan penyakit jamur penting lainnya pada tanaman.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Fluazinam 200 g/l + Dimetomorf 200 g/l*\r\nBentuk Formulasi : SC (Suspension Concentrate)\r\nCara Kerja : Kontak dan sistemik\r\nSifat Kerja : Protektif dan kuratif', 'WhatsApp_Image_2026-05-30_at_10_13_08(1).jpeg', 999, 999, 999, 180, 0, NULL, 'Pcs', 'Box', '0', 'Pilih Tipe Produk', 420, 1, '2026-05-30 13:54:13', 0),
(690, 1, 'T4S4X2MF9999148', 'Tinker 400 SC 40 X 200 ml', 'Tinker 400 SC adalah fungisida kontak dan sistemik berbentuk pekatan suspensi (SC) yang diformulasikan untuk mencegah dan mengendalikan berbagai penyakit jamur pada tanaman hortikultura. Dengan kombinasi dua bahan aktif yang saling melengkapi, produk ini efektif memberikan perlindungan sekaligus pengendalian terhadap penyakit busuk daun dan penyakit jamur penting lainnya pada tanaman.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Fluazinam 200 g/l + Dimetomorf 200 g/l*\r\nBentuk Formulasi : SC (Suspension Concentrate)\r\nCara Kerja : Kontak dan sistemik\r\nSifat Kerja : Protektif dan kuratif', 'Tinker_200ml.jpg', 999, 999, 999, 349, 0, NULL, 'Pcs', 'Box', '0', 'Pilih Tipe Produk', 220, 1, '2026-05-30 13:55:48', 0),
(691, 1, 'P5S4X2MF9999243', 'Popzole 525 SE 48 X 240 ml', 'Popzole 525 SE adalah fungisida sistemik ganda berbentuk Suspo-Emulsion (SE) yang mengandung kombinasi bahan aktif Propikonazol 125 g/L dan Trisiklazol 400 g/L. Produk ini bekerja secara protektif dan kuratif untuk mencegah serta mengendalikan berbagai penyakit jamur penting pada tanaman pangan dan hortikultura. Dengan penyerapan yang cepat melalui daun dan jaringan tanaman, Popzole 525 SE memberikan perlindungan menyeluruh dan tahan lama.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Propikonazol 125 g/L + Trisiklazol 400 g/L\r\nBentuk Formulasi : SE (Suspo-Emulsion)\r\nCara Kerja : Sistemik ganda\r\nSifat Kerja : Protektif dan kuratif', NULL, 999, 999, 999, 1014, 0, NULL, 'Pilih Satuan Product', 'Pilih Satuan Product', '0', 'Pilih Tipe Produk', 270, 1, '2026-05-30 13:57:23', 0),
(692, 1, 'P5S6X1MF9999276', 'Popzole 525 SE 64 X 100 ml', 'Popzole 525 SE adalah fungisida sistemik ganda berbentuk Suspo-Emulsion (SE) yang mengandung kombinasi bahan aktif Propikonazol 125 g/L dan Trisiklazol 400 g/L. Produk ini bekerja secara protektif dan kuratif untuk mencegah serta mengendalikan berbagai penyakit jamur penting pada tanaman pangan dan hortikultura. Dengan penyerapan yang cepat melalui daun dan jaringan tanaman, Popzole 525 SE memberikan perlindungan menyeluruh dan tahan lama.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Propikonazol 125 g/L + Trisiklazol 400 g/L\r\nBentuk Formulasi : SE (Suspo-Emulsion)\r\nCara Kerja : Sistemik ganda\r\nSifat Kerja : Protektif dan kuratif', 'Popzole_100ml.jpg', 999, 999, 999, 789, 0, NULL, 'Pcs', 'Box', '0', 'Pilih Tipe Produk', 120, 1, '2026-05-30 13:57:56', 0),
