(715, 1, 'A1E4X2MF2199000852', 'Adrift 125 EC 40 X 250 ml', 'Adrift 125 EC adalah fungisida sistemik berbentuk pekatan yang dapat diemulsikan (EC) dengan bahan aktif Miklobutanil 125 g/l yang diproduksi oleh PT Trimarga Nusantara. Produk ini bekerja dengan cara diserap oleh tanaman dan ditranslokasikan ke jaringan untuk memberikan perlindungan dari dalam, sehingga efektif digunakan untuk mencegah maupun mengendalikan berbagai penyakit jamur.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Miklobutanil 125 g/l\r\nBentuk Formulasi : EC (Emulsifiable Concentrate)\r\nJenis : Fungisida sistemik\r\nCara Kerja : Diserap tanaman dan bekerja dari dalam jaringan\r\n\r\nTarget Penyakit :\r\nBercak daun, embun tepung (powdery mildew), serta berbagai penyakit jamur lainnya.', 'Adrift_250ml.jpg', 208950, 202980, 199000, 118, 0, NULL, 'Botol', 'Box', '120', 'Pilih Tipe Produk', 270, 1, '2026-06-17 14:20:52', 0),
(716, 1, 'A1E5X1MF995000912', 'Adrift 125 EC 50 X 100 ml', 'Adrift 125 EC adalah fungisida sistemik berbentuk pekatan yang dapat diemulsikan (EC) dengan bahan aktif Miklobutanil 125 g/l yang diproduksi oleh PT Trimarga Nusantara. Produk ini bekerja dengan cara diserap oleh tanaman dan ditranslokasikan ke jaringan untuk memberikan perlindungan dari dalam, sehingga efektif digunakan untuk mencegah maupun mengendalikan berbagai penyakit jamur.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Miklobutanil 125 g/l\r\nBentuk Formulasi : EC (Emulsifiable Concentrate)\r\nJenis : Fungisida sistemik\r\nCara Kerja : Diserap tanaman dan bekerja dari dalam jaringan\r\n\r\nTarget Penyakit :\r\nBercak daun, embun tepung (powdery mildew), serta berbagai penyakit jamur lainnya.', 'Adrift_100ml.jpg', 99750, 96900, 95000, 202, 0, NULL, 'Botol', 'Box', '50', 'Pilih Tipe Produk', 120, 1, '2026-06-17 14:21:52', 0),
(717, 9, 'A2S4X2MI992000090', 'Agapro 280 SL 40 X 200 ml', 'Agapro 280 SL adalah insektisida sistemik dan kontak berbentuk larutan (SL) yang bekerja sebagai racun lambung untuk mengendalikan berbagai hama perusak tanaman. Produk ini bekerja dengan cara diserap oleh jaringan tanaman serta membunuh hama melalui kontak langsung maupun saat hama memakan bagian tanaman yang telah diaplikasikan. Efektif digunakan untuk melindungi tanaman pangan, sayuran, dan buah-buahan dari serangan hama utama.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Kombinasi Imidakloprid + Fipronil*\r\nBentuk Formulasi : SL (Soluble Liquid)\r\nCara Kerja : Sistemik, kontak, dan racun lambung', 'WhatsApp_Image_2026-06-17_at_13_26_11.jpeg', 96600, 93840, 92000, 196, 0, NULL, 'Botol', 'Box', '40', 'Pilih Tipe Produk', 270, 1, '2026-06-17 14:24:50', 0),
(718, 2, 'A1E4X2MH1117500206', 'Agil 100 EC 40 X 250 ml', 'Agil 100 EC adalah herbisida sistemik purna tumbuh berbentuk pekatan yang dapat diemulsikan (EC) dengan bahan aktif Propaquizafop 100 g/l. Produk ini bekerja secara selektif dengan cara diserap melalui daun gulma lalu ditranslokasikan ke seluruh bagian tanaman hingga akar, sehingga efektif mengendalikan gulma berdaun sempit tanpa mengganggu tanaman budidaya.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Propaquizafop 100 g/l\r\nBentuk Formulasi : EC (Emulsifiable Concentrate)\r\nJenis : Herbisida sistemik selektif\r\nWaktu Aplikasi : Purna tumbuh (setelah gulma muncul)', 'WhatsApp_Image_2026-06-17_at_13_27_45.jpeg', 123375, 119850, 117500, 120, 0, NULL, 'Botol', 'Box', '40', 'Pilih Tipe Produk', 270, 1, '2026-06-17 14:26:46', 0),
(719, 20, 'A4S3X1X3MZ225000338', 'Agrogibb 40 SL 30 X 15 X 35 ml', 'Agrogibb 40 SL adalah zat pengatur tumbuh (ZPT) berbentuk larutan cair dengan bahan aktif Asam Giberelat 40 g/l yang berfungsi untuk merangsang pertumbuhan tanaman, mempercepat pembungaan, membantu pembentukan buah, serta meningkatkan ukuran dan kualitas hasil panen. Produk ini bekerja dengan meningkatkan aktivitas pertumbuhan tanaman sehingga cocok digunakan pada berbagai komoditas pangan dan hortikultura.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Asam Giberelat (GA3) 40 g/l\r\nBentuk Formulasi : SL (Soluble Liquid)\r\nJenis : Zat Pengatur Tumbuh (ZPT)\r\nFungsi : Merangsang pertumbuhan, pembungaan, dan pembesaran hasil panen', 'WhatsApp_Image_2026-06-17_at_13_29_05.jpeg', 26250, 25500, 25000, 77827, 0, NULL, 'Botol', 'Box', '450', 'Pilih Tipe Produk', 37, 1, '2026-06-17 14:28:58', 0),
(720, 2, 'A2O2X5MH1125000896', 'Algojo 200/10/15 OD 20 X 500 ml', 'Algojo 200/10/15 OD adalah herbisida sistemik selektif berbentuk Oil Dispersion (OD) produksi Agricon yang diformulasikan khusus untuk mengendalikan berbagai jenis gulma pada tanaman jagung. Produk ini bekerja secara ganda sebagai herbisida pra-tumbuh maupun purna tumbuh, sehingga efektif menekan pertumbuhan gulma sejak awal hingga gulma yang sudah berkembang.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Kombinasi tiga bahan aktif (sesuai formulasi 200/10/15)\r\nBentuk Formulasi : OD (Oil Dispersion)\r\nJenis : Herbisida sistemik selektif', 'WhatsApp_Image_2026-06-17_at_13_30_32.jpeg', 131250, 127500, 125000, 100, 0, NULL, 'Botol', 'Box', '20', 'Pilih Tipe Produk', 520, 1, '2026-06-17 14:38:16', 0),
(721, 9, 'A1S4X2MI197000020', 'Almix 141/106 SC 40 X 250 ml', 'Almix 141/106 SC adalah insektisida sistemik berspektrum luas berbentuk Suspension Concentrate (SC) yang diproduksi oleh PT Sinar General Industries. Produk ini diformulasikan dengan kombinasi dua bahan aktif Tiametoksam 141 g/l dan Lamda Sihalotrin 106 g/l yang bekerja secara sinergis untuk mengendalikan berbagai jenis hama penghisap maupun pengunyah pada tanaman.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Tiametoksam 141 g/l + Lamda Sihalotrin 106 g/l\r\nBentuk Formulasi : SC (Suspension Concentrate)\r\nCara Kerja : Sistemik, racun kontak, dan racun lambung', 'WhatsApp_Image_2026-06-17_at_13_31_47.jpeg', 101850, 98940, 97000, 875, 0, NULL, 'Botol', 'Box', '40', 'Pilih Tipe Produk', 270, 1, '2026-06-17 14:40:20', 0),
(722, 9, 'B1E1X5M(I442000173', 'Bamex 18 EC 100 X 50 ml (M2U)', 'Bamex 18 EC adalah insektisida dan akarisida berbentuk pekatan yang dapat diemulsikan (EC) dengan bahan aktif Abamektin 18 g/l. Produk ini bekerja sebagai racun kontak dan lambung dengan kemampuan translaminar, yaitu mampu menembus jaringan daun sehingga efektif mengendalikan hama yang bersembunyi di permukaan bawah daun maupun bagian tanaman lainnya.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Abamektin 18 g/l\r\nBentuk Formulasi : EC (Emulsifiable Concentrate)\r\nJenis : Insektisida dan akarisida\r\nCara Kerja : Kontak, lambung, dan translaminar', 'Bamex_50_ml.jpg', 44100, 42840, 42000, 1000, 0, NULL, 'Botol', 'Box', '100', '', 70, 1, '2026-06-17 14:59:33', 0),
(723, 9, 'B1E5X1M(I879000483', 'Bamex 18 EC 50 X 100 ml (M2U)', 'Bamex 18 EC adalah insektisida dan akarisida berbentuk pekatan yang dapat diemulsikan (EC) dengan bahan aktif Abamektin 18 g/l. Produk ini bekerja sebagai racun kontak dan lambung dengan kemampuan translaminar, yaitu mampu menembus jaringan daun sehingga efektif mengendalikan hama yang bersembunyi di permukaan bawah daun maupun bagian tanaman lainnya.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Abamektin 18 g/l\r\nBentuk Formulasi : EC (Emulsifiable Concentrate)\r\nJenis : Insektisida dan akarisida\r\nCara Kerja : Kontak, lambung, dan translaminar', 'Bamex_100ml.jpg', 82950, 82580, 79000, 150, 0, NULL, 'Botol', 'Box', '50', 'Pilih Tipe Produk', 120, 1, '2026-06-17 15:04:43', 0),
(724, 19, 'BCS2X5MPC1175000855', 'Basfoliar Combi Stipp 20 X 500 ml', 'Basfoliar Combi Stipp adalah pupuk cair mikro dengan kandungan utama Kalsium (Ca) 15%, Nitrogen (N) 9%, dan Boron (B) 0,02% yang diformulasikan dengan teknologi berlisensi Jerman untuk membantu memenuhi kebutuhan nutrisi mikro tanaman. Produk ini berfungsi memperkuat jaringan tanaman, meningkatkan kualitas buah, serta mencegah gangguan fisiologis akibat kekurangan kalsium.\r\n\r\nSpesifikasi Produk :\r\nKandungan : Kalsium (Ca) 15% + Nitrogen (N) 9% + Boron (B) 0,02%\r\nJenis : Pupuk cair mikro\r\nBentuk : Cair\r\nFungsi : Nutrisi tambahan untuk memperkuat tanaman dan meningkatkan kualitas hasil panen', 'Basfoliar_Strip_500ml.jpg', 183750, 178500, 175000, 967, 0, NULL, 'Botol', 'Box', '20', 'Pilih Tipe Produk', 520, 1, '2026-06-17 15:27:35', 0),
(725, 9, 'B1E2X2M(I1145000041', 'Bamex 18 EC 20 X 200 ml (M2U)', 'Bamex 18 EC adalah insektisida dan akarisida berbentuk pekatan yang dapat diemulsikan (EC) dengan bahan aktif Abamektin 18 g/l. Produk ini bekerja sebagai racun kontak dan lambung dengan kemampuan translaminar, yaitu mampu menembus jaringan daun sehingga efektif mengendalikan hama yang bersembunyi di permukaan bawah daun maupun bagian tanaman lainnya.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Abamektin 18 g/l\r\nBentuk Formulasi : EC (Emulsifiable Concentrate)\r\nJenis : Insektisida dan akarisida\r\nCara Kerja : Kontak, lambung, dan translaminar', 'Bamex_200ml.jpg', 152250, 147900, 145000, 100, 0, NULL, 'Botol', 'Box', '20', 'Pilih Tipe Produk', 270, 1, '2026-06-17 15:30:41', 0),
(726, 2, 'B1S2X5MH227500540', 'Basrata 150 SL 20 X 500 ml', 'Basrata 150 SL adalah herbisida non-selektif purna tumbuh berbentuk larutan SL (Soluble Concentrate) yang digunakan untuk mengendalikan berbagai jenis gulma dan rumput liar yang mengganggu tanaman. Produk ini mengandung bahan aktif Amonium Glufosinat 150 g/l yang bekerja secara kontak dan sistemik lokal dengan cara diserap melalui bagian hijau tanaman seperti daun dan batang.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Amonium Glufosinat 150 g/l\r\nBentuk Formulasi : SL (Soluble Concentrate)\r\nJenis : Herbisida non-selektif purna tumbuh\r\nCara Kerja : Kontak dan sistemik lokal', 'WhatsApp_Image_2026-06-17_at_15_40_24.jpeg', 28875, 28050, 27500, 19, 0, NULL, 'Botol', 'Box', '20', '', 520, 1, '2026-06-17 15:39:00', 0),
(727, 9, 'B5E2X5MI775000731', 'Baycarb 500 EC 20 X 500 ml', 'Baycarb 500 EC adalah insektisida racun kontak dan lambung berbentuk pekatan yang dapat diemulsikan (EC) produksi Bayer Indonesia. Produk ini mengandung bahan aktif Fenobucarb (BPMC) 500 g/l yang efektif mengendalikan berbagai hama penghisap dan perusak tanaman, terutama pada tanaman pangan dan perkebunan.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Fenobucarb / BPMC 500 g/l\r\nBentuk Formulasi : EC (Emulsifiable Concentrate)\r\nWarna : Cairan pekat coklat jernih\r\nCara Kerja : Racun kontak dan racun lambung', 'WhatsApp_Image_2026-06-17_at_13_38_56.jpeg', 78750, 76500, 75000, 2040, 0, NULL, 'Botol', 'Box', '20', 'Pilih Tipe Produk', 520, 1, '2026-06-17 15:42:11', 0),
(728, 9, 'BP1S4X2MI1150000935', 'Benabel Plus 120/35 SC 48 X 250 ml', 'Benabel Plus 120/35 SC adalah insektisida sistemik dengan kombinasi dua bahan aktif berbentuk Suspension Concentrate (SC) yang bekerja sebagai racun kontak dan lambung. Produk ini diformulasikan dengan kombinasi Klorantraniliprol 120 g/L dan Emamektin Benzoat 35 g/L yang memberikan perlindungan efektif terhadap berbagai jenis hama ulat pada tanaman pangan.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Klorantraniliprol 120 g/L + Emamektin Benzoat 35 g/L\r\nBentuk Formulasi : SC (Suspension Concentrate)\r\nCara Kerja : Sistemik, racun kontak, dan racun lambung', 'WhatsApp_Image_2026-06-17_at_13_39_59.jpeg', 157500, 153000, 150000, 4961, 0, NULL, 'Botol', 'Box', '48', 'Pilih Tipe Produk', 270, 1, '2026-06-17 15:45:35', 0),
(729, 9, 'BP1S6X1MI663000997', 'Benabel Plus 120/35 SC 64 X 100 ml', 'Benabel Plus 120/35 SC adalah insektisida sistemik dengan kombinasi dua bahan aktif berbentuk Suspension Concentrate (SC) yang bekerja sebagai racun kontak dan lambung. Produk ini diformulasikan dengan kombinasi Klorantraniliprol 120 g/L dan Emamektin Benzoat 35 g/L yang memberikan perlindungan efektif terhadap berbagai jenis hama ulat pada tanaman pangan.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Klorantraniliprol 120 g/L + Emamektin Benzoat 35 g/L\r\nBentuk Formulasi : SC (Suspension Concentrate)\r\nCara Kerja : Sistemik, racun kontak, dan racun lambung', 'WhatsApp_Image_2026-06-17_at_13_40_00.jpeg', 66150, 64260, 63000, 1304, 0, NULL, 'Botol', 'Pilih Satuan Product', '64', '1', 120, 1, '2026-06-17 15:46:37', 0),
(730, 2, 'BO3S2X1LH662000999', 'Bestani OK 300 SL 20 X 1 ltr*', 'Bestani OK 300 SL adalah herbisida kontak purna tumbuh berbentuk larutan SL (Soluble Liquid) dengan bahan aktif Amonium Glufosinat 300 g/L yang efektif mengendalikan berbagai jenis gulma pada lahan pertanian maupun perkebunan. Produk ini bekerja dengan cara diserap oleh bagian hijau tanaman seperti daun dan batang untuk menghambat aktivitas pertumbuhan gulma hingga mengalami pengeringan.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Amonium Glufosinat 300 g/L\r\nBentuk Formulasi : SL (Soluble Liquid)\r\nJenis : Herbisida kontak purna tumbuh\r\nWarna : Cairan biru kehijauan\r\nCara Kerja : Kontak dan sistemik lokal', 'bestani_ok_1_liter.jpeg', 65100, 63240, 62000, 2674, 0, NULL, 'Botol', 'Box', '20', 'Pilih Tipe Produk', 1200, 1, '2026-06-18 14:33:19', 0),
(731, 0, 'B2S2X1L551000282', 'Bestar 200 SL 20 X 1 ltr', 'Bestar 200 SL adalah herbisida purna tumbuh berspektrum luas berbentuk larutan SL (Soluble Liquid) dengan bahan aktif Amonium Glufosinat 200 g/l. Produk ini bekerja sebagai herbisida kontak dan sistemik terbatas yang efektif mengendalikan berbagai jenis gulma dan rumput liar membandel pada lahan pertanian maupun perkebunan.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Amonium Glufosinat 200 g/l (setara Glufosinat 182,7 g/l)\r\nBentuk Formulasi : SL (Soluble Liquid)\r\nJenis : Herbisida purna tumbuh non-selektif\r\nWarna : Cairan biru kehijauan\r\nCara Kerja : Kontak dan sistemik terbatas', 'bestar_1_liter.jpeg', 53550, 52020, 51000, 4081, 0, NULL, 'Botol', 'Box', '20', 'Pilih Tipe Produk', 1200, 1, '2026-06-18 14:38:02', 0),
(732, 19, 'BVB2X1LPC885000445', 'Biochems Vit B1+B6 20 X 1 ltr', 'Biochems Vit B1+B6 adalah pupuk organik cair (POC) yang diformulasikan khusus untuk membantu pertumbuhan dan pemulihan tanaman. Produk ini mengandung kombinasi Vitamin B1, Vitamin B6, Asam Salisilat, serta unsur hara makro dan mikro yang berfungsi sebagai nutrisi tambahan sekaligus biostimulan untuk meningkatkan kesehatan tanaman.\r\n\r\nSpesifikasi Produk :\r\nJenis : Pupuk Organik Cair (POC)\r\nKandungan Utama : Vitamin B1, Vitamin B6, Asam Salisilat, unsur hara makro dan mikro\r\nBentuk : Cair\r\nFungsi : Stimulan pertumbuhan, pemulihan tanaman, dan peningkatan daya tahan tanaman', 'biochem_1_liter.jpeg', 89250, 86700, 85000, 27, 0, NULL, 'Botol', 'Box', '20', 'Pilih Tipe Produk', 1200, 1, '2026-06-18 14:40:45', 0),
(733, 19, 'BVB3X5MPC445000528', 'Biochems Vit B1+B6 30 X 500 ml', 'Biochems Vit B1+B6 adalah pupuk organik cair (POC) yang diformulasikan khusus untuk membantu pertumbuhan dan pemulihan tanaman. Produk ini mengandung kombinasi Vitamin B1, Vitamin B6, Asam Salisilat, serta unsur hara makro dan mikro yang berfungsi sebagai nutrisi tambahan sekaligus biostimulan untuk meningkatkan kesehatan tanaman.\r\n\r\nSpesifikasi Produk :\r\nJenis : Pupuk Organik Cair (POC)\r\nKandungan Utama : Vitamin B1, Vitamin B6, Asam Salisilat, unsur hara makro dan mikro\r\nBentuk : Cair\r\nFungsi : Stimulan pertumbuhan, pemulihan tanaman, dan peningkatan daya tahan tanaman', 'biochem_500ml.jpeg', 47250, 45900, 45000, 34, 0, NULL, 'Botol', 'Box', '30', 'Pilih Tipe Produk', 520, 1, '2026-06-18 14:42:08', 0),
(734, 19, 'BVB4X2MPC225000583', 'Biochems Vit B1+B6 40 X 250 ml', 'Biochems Vit B1+B6 adalah pupuk organik cair (POC) yang diformulasikan khusus untuk membantu pertumbuhan dan pemulihan tanaman. Produk ini mengandung kombinasi Vitamin B1, Vitamin B6, Asam Salisilat, serta unsur hara makro dan mikro yang berfungsi sebagai nutrisi tambahan sekaligus biostimulan untuk meningkatkan kesehatan tanaman.\r\n\r\nSpesifikasi Produk :\r\nJenis : Pupuk Organik Cair (POC)\r\nKandungan Utama : Vitamin B1, Vitamin B6, Asam Salisilat, unsur hara makro dan mikro\r\nBentuk : Cair\r\nFungsi : Stimulan pertumbuhan, pemulihan tanaman, dan peningkatan daya tahan tanaman', 'biochem_250ml.jpeg', 26250, 25500, 25000, 1009, 0, NULL, 'Botol', 'Box', '40', 'Pilih Tipe Produk', 270, 1, '2026-06-18 14:43:03', 0),
(735, 20, 'BBB2L2X5MZ447500089', 'Blacer Booster Buah 25.79 L 24 X 500 ml', 'Blacer 25,79 L Booster Buah adalah Zat Pengatur Tumbuh (ZPT) cair yang diformulasikan dengan kandungan unsur mikro untuk membantu merangsang proses pembungaan, pembentukan buah, serta meningkatkan kualitas dan bobot hasil panen. Produk ini berfungsi sebagai booster tanaman pada fase generatif agar tanaman lebih optimal dalam menghasilkan buah.\r\n\r\nSpesifikasi Produk :\r\nJenis : Zat Pengatur Tumbuh (ZPT) cair\r\nKandungan : ZPT + unsur mikro esensial\r\nBentuk : Cair\r\nFungsi : Perangsang bunga, buah, dan peningkatan hasil panen', 'Blacer_buah_500ml.jpg', 49875, 48875, 47500, 670, 0, NULL, 'Botol', 'Box', '24', '1', 520, 1, '2026-06-18 14:51:29', 0),
(736, 20, 'BBD1L2X5MZ447500441', 'Blacer Booster Daun 16.85 L 24 X 500 ml', 'BLACER 25,79 L Booster Buah adalah Zat Pengatur Tumbuh (ZPT) tanaman berbentuk larutan yang diformulasikan dengan kandungan unsur mikro untuk membantu merangsang fase generatif tanaman. Produk ini berfungsi meningkatkan pembentukan bunga, mengurangi kerontokan bunga dan buah, serta membantu meningkatkan bobot dan kualitas hasil panen pada berbagai komoditas pertanian.\r\n\r\nSpesifikasi Produk :\r\nJenis : Zat Pengatur Tumbuh (ZPT) cair\r\nBentuk Formulasi : Larutan cair\r\nKandungan : ZPT + unsur mikro esensial\r\nFungsi : Booster pembungaan dan pembuahan tanaman', 'Blacer_daun_500ml.jpg', 49875, 48450, 47500, 1362, 0, NULL, 'Botol', 'Box', '24', 'Pilih Tipe Produk', 520, 1, '2026-06-18 14:57:21', 0),
(737, 0, 'B2S2X5M775000758', 'Blast 200 SC 20 X 500 ml', 'Blast 200 SC adalah fungisida protektif berbentuk pekatan suspensi berwarna cokelat untuk mengendalikan penyakit blas pada tanaman padi.Spesifikasi UtamaBahan Aktif: Trisiklazol 200 g/lSasaran Penyakit: Blas daun (pyricularia oryzae/grisea), potong leher, dan kresekManfaat Tambahan: Menjaga warna gabah tetap kuning cerah dan bisa digunakan untuk perlakuan benih', 'Blast_500ml.jpg', 78750, 76500, 75000, 1870, 0, NULL, 'Botol', 'Box', '20', '1', 520, 1, '2026-06-18 15:02:38', 0),
(738, 1, 'B2S4X1MF223000971', 'Blast 200 SC 48 X 100 ml', 'Blast 200 SC adalah fungisida protektif berbentuk pekatan suspensi (SC) berwarna cokelat yang diformulasikan khusus untuk mengendalikan penyakit blas pada tanaman padi. Produk ini mengandung bahan aktif Trisiklazol 200 g/l yang bekerja melindungi tanaman dari serangan jamur penyebab penyakit serta membantu menjaga kesehatan tanaman hingga masa panen.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Trisiklazol 200 g/l\r\nBentuk Formulasi : SC (Suspension Concentrate)\r\nWarna : Pekatan suspensi berwarna cokelat\r\nJenis : Fungisida protektif', 'Blast_100ml.jpg', 24150, 23460, 23000, 3542, 0, NULL, 'Botol', 'Box', '48', 'Pilih Tipe Produk', 120, 1, '2026-06-18 15:06:11', 0),
(739, 14, 'BBF1X1X1GB1120000924', 'Blewah Blaster F1 12 X 15 X 15 gr', 'Blewah Hibrida adalah varietas blewah unggul dengan karakter buah berkualitas tinggi, memiliki produktivitas baik, aroma harum, serta tekstur daging yang lembut. Varietas ini cocok dibudidayakan terutama di daerah dataran rendah dengan pertumbuhan yang stabil dan hasil panen yang optimal.\r\n\r\nSpesifikasi Produk :\r\nJenis : Benih Blewah Hibrida\r\nBentuk Buah : Bulat lonjong\r\nWarna Kulit : Hijau gelap\r\nWarna Daging : Oranye\r\nBerat Buah : ± 1,6 kg/buah\r\nUmur Panen : ± 52 HST (Hari Setelah Tanam)\r\nPotensi Hasil : ± 12 ton/ha', 'blewwah_blaster.jpeg', 126000, 122400, 120000, 7820, 0, NULL, 'Pcs', 'Box', '180', '', 17, 1, '2026-06-18 15:22:04', 0),
(740, 1, 'B8W2X1KF986000833', 'Bluezeb 80 WP 20 X 1 kg', 'Bluezeb 80 WP adalah fungisida kontak protektif berbentuk tepung (Wettable Powder/WP) berwarna biru dengan bahan aktif Mankozeb 80%. Produk ini bekerja dengan membentuk lapisan perlindungan pada permukaan tanaman untuk mencegah perkembangan jamur penyebab penyakit, sehingga efektif digunakan sebagai perlindungan awal tanaman.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Mankozeb 80%\r\nBentuk Formulasi : WP (Wettable Powder)\r\nWarna : Tepung berwarna biru\r\nJenis : Fungisida kontak protektif\r\nCara Kerja : Kontak langsung pada permukaan tanaman', 'WhatsApp_Image_2026-06-18_at_15_30_30.jpeg', 90300, 87720, 86000, 1035, 0, NULL, 'Pcs', 'Box', '20', '1', 1200, 1, '2026-06-18 15:37:13', 0),
(741, 1, 'BT2S4X2MF1105000340', 'BM Trox 200/125 SC 40 X 250 ml', 'BM Trox 200/125 SC adalah fungisida sistemik kombinasi berbentuk Suspension Concentrate (SC) yang diformulasikan dengan dua bahan aktif yaitu Azoksistrobin 200 g/l dan Difenokonazol 125 g/l. Produk ini bekerja secara ganda sebagai preventif (pencegahan) dan kuratif (pengendalian penyakit yang sudah menyerang) untuk melindungi tanaman dari berbagai penyakit akibat jamur.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Azoksistrobin 200 g/l + Difenokonazol 125 g/l\r\nBentuk Formulasi : SC (Suspension Concentrate)\r\nJenis : Fungisida sistemik\r\nCara Kerja : Preventif dan kuratif', 'bm_trox_250ml.jpeg', 110250, 107100, 105000, 1673, 0, NULL, 'Botol', 'Box', '40', '1', 270, 1, '2026-06-18 15:45:40', 0),
(742, 13, 'BP3X1PLL878500755', 'Boom Padi 30 X 1 Paket', 'Boom Padi Max adalah paket nutrisi dan perlindungan tanaman yang diformulasikan khusus untuk mendukung fase generatif tanaman padi. Produk ini dirancang untuk membantu proses pembentukan malai, pengisian bulir, meningkatkan bobot gabah, serta membantu mengurangi risiko bulir hampa pada tanaman padi.\r\n\r\nSpesifikasi Produk :\r\nJenis : Paket nutrisi dan perlindungan tanaman padi\r\nFungsi : Booster fase generatif padi\r\nKomposisi Paket : Umumnya terdiri dari pupuk cair/nutrisi, fungisida, insektisida, dan bahan pendukung aplikasi (tergantung paket)\r\nFase Aplikasi : Fase bunting hingga pengisian malai', 'Boom_Padi_Max.jpg', 82425, 80070, 78500, 0, 0, NULL, 'Pcs', 'Box', '0', '1', 0, 1, '2026-06-18 15:52:35', 0),
(743, 14, 'CDF1X1X1GB1160000014', 'Cabe Darmais F1 12 X 15 X 10 gr', 'Cabai Darmais F1 adalah varietas cabai merah besar hibrida unggulan produksi Bintang Asia yang dikenal memiliki produktivitas tinggi, buah berukuran besar, daging tebal, serta daya tahan simpan yang baik. Varietas ini cocok dibudidayakan oleh petani karena memiliki adaptasi luas dan performa tanaman yang kuat.\r\n\r\nSpesifikasi Produk :\r\nJenis : Benih Cabai Merah Besar Hibrida\r\nProdusen : Bintang Asia\r\nTipe Tanaman : Vigor kokoh dan adaptif\r\nAdaptasi : Dataran rendah hingga dataran tinggi\r\nUmur Panen : ± 79–110 HST\r\nPotensi Hasil : Hingga ± 1,5 kg/tanaman\r\n\r\nKarakteristik Buah :\r\nBentuk Buah : Cabai merah besar\r\nPanjang Buah : ± 16–19 cm\r\nDiameter : ± 2 cm\r\nWarna Buah : Hijau gelap saat muda dan berubah menjadi merah menyala/mengkilap saat matang\r\nTekstur : Daging buah tebal dan keras', 'cabe_darmais.jpeg', 168000, 163200, 160000, 3529, 0, NULL, 'Pcs', 'Box', '180', '1', 12, 1, '2026-06-19 09:43:34', 0),
(744, 14, 'CIIF2X1X2BB1150000344', 'Cabe Imperial Ijo F1 20 X 12 X 2250 biji', 'Cabe Imperial Ijo F1 adalah benih cabai hibrida unggul produksi PT Bisi International (Cap Kapal Terbang) yang menghasilkan cabai besar/keriting dengan karakter buah berkualitas tinggi. Varietas ini banyak digunakan petani karena memiliki tanaman yang kuat, adaptasi luas, tahan terhadap serangan virus, serta mampu berproduksi optimal pada berbagai kondisi tanam termasuk musim penghujan.\r\n\r\nSpesifikasi Produk :\r\nJenis : Benih Cabai Hibrida\r\nProdusen : PT Bisi International (Cap Kapal Terbang)\r\nTipe Tanaman : Cabai besar/keriting hibrida\r\nAdaptasi : Dataran rendah hingga tinggi\r\nKetahanan : Tahan terhadap serangan penyakit terutama virus\r\n\r\nKarakteristik Buah :\r\nPanjang Buah : ± 17 cm\r\nDiameter : ± 1,2 cm\r\nWarna Buah : Hijau gelap saat muda dan merah mengkilap saat matang\r\nTekstur : Kulit buah tebal dan kuat', 'WhatsApp_Image_2026-06-17_at_15_17_03(2).jpeg', 157500, 153000, 150000, 1251, 0, NULL, 'Pcs', 'Box', '240', '1', 22, 1, '2026-06-19 09:49:04', 0),
(745, 14, 'CMF2X1X2BB2235000486', 'Cabe Matador F1 20 X 12 X 2250 biji', 'Cabai Matador F1 adalah benih cabai merah besar hibrida unggulan produksi PT BISI International Tbk yang dikenal memiliki daya adaptasi tinggi, tanaman kuat, serta ketahanan terhadap berbagai gangguan penyakit. Varietas ini banyak diminati petani karena menghasilkan buah berukuran besar, lentur, berkualitas, dan cocok untuk kebutuhan pasar segar maupun distribusi jarak jauh.\r\n\r\nSpesifikasi Produk :\r\nJenis : Benih Cabai Merah Besar Hibrida\r\nProdusen : PT BISI International Tbk\r\nTipe Tanaman : Cabai merah besar hibrida\r\nAdaptasi : Dataran rendah hingga dataran tinggi\r\nUmur Panen : ± 78–80 hari setelah pindah tanam\r\nPotensi Hasil : ± 17,4–25 ton/ha (tergantung perawatan dan kondisi lahan)\r\n\r\nKarakteristik Buah :\r\nPanjang Buah : ± 16–16,4 cm\r\nDiameter Buah : ± 1,3–1,4 cm\r\nWarna : Hijau gelap saat muda dan merah mengkilap saat matang\r\nTekstur : Lentur, kuat, dan tahan pengangkutan', NULL, 246750, 239700, 235000, 111, 0, NULL, 'Pcs', 'Box', '240', '1', 22, 1, '2026-06-19 09:51:26', 0),
(746, 14, 'CO21X2X1GB658000627', 'Cabe Ori 212 10 X 25 X 10 gr', 'Cabe Ori 212 adalah varietas benih cabai rawit unggul tipe lokal (non-hibrida/open pollinated) produksi CV Aura Seed Indonesia yang dikenal memiliki produktivitas tinggi, tanaman kokoh, serta buah padat dengan daya simpan yang baik. Varietas ini banyak diminati petani karena pertumbuhannya rimbun, cabang produktif, dan mampu menghasilkan buah dalam jumlah banyak.\r\n\r\nSpesifikasi Produk :\r\nJenis : Benih Cabai Rawit Unggul\r\nTipe : Lokal / Non-Hibrida (Open Pollinated)\r\nProdusen : CV Aura Seed Indonesia\r\nTipe Tanaman : Tegak, kokoh, dan rimbun\r\nKarakter : Produktif dengan percabangan banyak\r\n\r\nKarakteristik Tanaman :\r\nBentuk Tanaman : Tumbuh tegak dan kuat\r\nBatang : Kokoh dengan ruas pendek\r\nPercabangan : Banyak dan produktif sehingga mendukung pembentukan buah lebih lebat', 'cabe_sret.jpeg', 60900, 59160, 58000, 2700, 0, NULL, 'Pcs', 'Box', '250', '1', 12, 1, '2026-06-19 09:53:47', 0),
(747, 9, 'A2S5X8MI440000070', 'Agapro 280 SL 50 X 80 ml', 'Agapro 280 SL adalah insektisida sistemik dan kontak berbentuk larutan (SL) yang bekerja sebagai racun lambung untuk mengendalikan berbagai hama perusak tanaman. Produk ini bekerja dengan cara diserap oleh jaringan tanaman serta membunuh hama melalui kontak langsung maupun saat hama memakan bagian tanaman yang telah diaplikasikan. Efektif digunakan untuk melindungi tanaman pangan, sayuran, dan buah-buahan dari serangan hama utama.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Kombinasi Imidakloprid + Fipronil*\r\nBentuk Formulasi : SL (Soluble Liquid)\r\nCara Kerja : Sistemik, kontak, dan racun lambung', 'WhatsApp_Image_2026-06-22_at_11_40_00.jpeg', 42000, 40800, 40000, 415, 0, NULL, 'Botol', 'Box', '50', '', 82, 1, '2026-06-19 10:01:10', 0),
(748, 2, 'A2O2X1LH2220000141', 'Algojo 200/10/15 OD 20 X 1 ltr', 'Algojo 200/10/15 OD adalah herbisida sistemik selektif berbentuk Oil Dispersion (OD) produksi Agricon yang diformulasikan khusus untuk mengendalikan berbagai jenis gulma pada tanaman jagung. Produk ini bekerja secara ganda sebagai herbisida pra-tumbuh maupun purna tumbuh, sehingga efektif menekan pertumbuhan gulma sejak awal hingga gulma yang sudah berkembang.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Kombinasi tiga bahan aktif (sesuai formulasi 200/10/15)\r\nBentuk Formulasi : OD (Oil Dispersion)\r\nJenis : Herbisida sistemik selektif\r\nTanaman Sasaran : Jagung', 'WhatsApp_Image_2026-06-22_at_11_07_33(4).jpeg', 231000, 224400, 220000, 840, 0, NULL, 'Botol', 'Box', '20', '', 1200, 1, '2026-06-19 10:02:21', 0),
(749, 9, 'A1S2X5MI1185000194', 'Almix 141/106 SC 20 X 500 ml', 'Almix 141/106 SC adalah insektisida sistemik berspektrum luas berbentuk Suspension Concentrate (SC) yang diproduksi oleh PT Sinar General Industries. Produk ini diformulasikan dengan kombinasi dua bahan aktif Tiametoksam 141 g/l dan Lamda Sihalotrin 106 g/l yang bekerja secara sinergis untuk mengendalikan berbagai jenis hama penghisap maupun pengunyah pada tanaman.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Tiametoksam 141 g/l + Lamda Sihalotrin 106 g/l\r\nBentuk Formulasi : SC (Suspension Concentrate)\r\nCara Kerja : Sistemik, racun kontak, dan racun lambung\r\n\r\nTarget Hama :\r\nBerbagai hama penghisap dan pengunyah seperti kutu daun, thrips, wereng, ulat, serta hama perusak tanaman lainnya.', 'WhatsApp_Image_2026-06-22_at_11_07_32(2).jpeg', 194250, 188700, 185000, 100, 0, NULL, 'Botol', 'Box', '20', '', 520, 1, '2026-06-19 10:03:14', 0),
(750, 9, 'A1S5X1MI440000319', 'Almix 141/106 SC 50 X 100 ml', 'Almix 141/106 SC adalah insektisida sistemik berspektrum luas berbentuk Suspension Concentrate (SC) yang diproduksi oleh PT Sinar General Industries. Produk ini diformulasikan dengan kombinasi dua bahan aktif Tiametoksam 141 g/l dan Lamda Sihalotrin 106 g/l yang bekerja secara sinergis untuk mengendalikan berbagai jenis hama penghisap maupun pengunyah pada tanaman.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Tiametoksam 141 g/l + Lamda Sihalotrin 106 g/l\r\nBentuk Formulasi : SC (Suspension Concentrate)\r\nCara Kerja : Sistemik, racun kontak, dan racun lambung\r\n\r\nTarget Hama :\r\nBerbagai hama penghisap dan pengunyah seperti kutu daun, thrips, wereng, ulat, serta hama perusak tanaman lainnya.', 'WhatsApp_Image_2026-06-22_at_11_07_31.jpeg', 42000, 40800, 40000, 440, 0, NULL, 'Botol', 'Box', '50', '', 120, 1, '2026-06-19 10:05:19', 0);
INSERT INTO `products` (`id`, `category_id`, `sku`, `name`, `description`, `picture_name`, `price`, `price_3`, `price_2`, `stock`, `current_discount`, `product_unit`, `product_unit_1`, `product_unit_2`, `product_unit_value`, `product_type`, `product_unit_weight`, `is_available`, `add_date`, `user_level`) VALUES
(751, 9, 'A5E1X1LI988000414', 'Amabas 500 EC 16 X 1 ltr', 'Amabas 500 EC adalah insektisida racun kontak dan lambung berbentuk pekatan yang dapat diemulsikan (EC) dengan bahan aktif Fenobucarb (BPMC) 500 g/l. Produk ini bekerja cepat dengan efek knockdown untuk mengendalikan berbagai jenis hama penghisap maupun pengunyah pada tanaman pangan dan hortikultura.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Fenobucarb / BPMC 500 g/l\r\nBentuk Formulasi : EC (Emulsifiable Concentrate)\r\nJenis : Insektisida kontak dan lambung\r\nCara Kerja : Kontak langsung dan racun lambung dengan efek knockdown cepat', 'WhatsApp_Image_2026-06-22_at_11_07_04.jpeg', 92400, 89760, 88000, 1, 0, NULL, 'Botol', 'Box', '16', '', 1200, 1, '2026-06-19 10:06:54', 0),
(752, 9, 'A1M4X2MI1185000551', 'Ambest 100 ME 40 X 250 ml', 'Ambest 100 ME adalah insektisida sistemik berspektrum luas berbentuk mikro emulsi (ME) yang bekerja sebagai racun kontak dan lambung untuk mengendalikan berbagai jenis hama pada tanaman. Produk ini mengandung kombinasi dua bahan aktif yaitu Fipronil 50 g/L dan Asetamiprid 50 g/L yang memberikan efek pengendalian hama secara cepat dan optimal.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Fipronil 50 g/L + Asetamiprid 50 g/L\r\nBentuk Formulasi : ME (Micro Emulsion)\r\nJenis : Insektisida sistemik berspektrum luas\r\nCara Kerja : Racun kontak, lambung, dan sistemik', 'WhatsApp_Image_2026-06-22_at_11_07_34(1).jpeg', 194250, 188700, 185000, 120, 0, NULL, 'Botol', 'Box', '40', '', 270, 1, '2026-06-19 10:09:11', 0),
(753, 9, 'A1M5X1MI196000605', 'Ambest 100 ME 50 X 100 ml', 'Ambest 100 ME adalah insektisida sistemik berspektrum luas berbentuk mikro emulsi (ME) yang bekerja sebagai racun kontak dan lambung untuk mengendalikan berbagai jenis hama pada tanaman. Produk ini mengandung kombinasi dua bahan aktif yaitu Fipronil 50 g/L dan Asetamiprid 50 g/L yang memberikan efek pengendalian hama secara cepat dan optimal.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Fipronil 50 g/L + Asetamiprid 50 g/L\r\nBentuk Formulasi : ME (Micro Emulsion)\r\nJenis : Insektisida sistemik berspektrum luas\r\nCara Kerja : Racun kontak, lambung, dan sistemik', 'WhatsApp_Image_2026-06-22_at_11_07_33(2).jpeg', 100800, 97920, 96000, 158, 0, NULL, 'Botol', 'Box', '50', '', 120, 1, '2026-06-19 10:10:05', 0),
(754, 1, 'A3S1X1GF995000796', 'Antramix 30/22.5 SG 100 X 100 gr', 'Antramix 30/22.5 SG adalah fungisida berspektrum luas dengan kombinasi bahan aktif Cymoxanil 30% dan Famoxadone 22,5% yang bekerja sebagai fungisida protektif dan kuratif untuk mengendalikan berbagai penyakit yang disebabkan oleh jamur pada tanaman. Produk ini berbentuk butiran larut air (SG) yang mudah diaplikasikan dan memberikan perlindungan optimal pada tanaman.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Cymoxanil 30% + Famoxadone 22,5%\r\nBentuk Formulasi : SG (Soluble Granule)\r\nJenis : Fungisida kontak dan sistemik lokal\r\nCara Kerja : Protektif dan kuratif', 'WhatsApp_Image_2026-06-22_at_11_07_33(1).jpeg', 99750, 96900, 95000, 993, 0, NULL, 'Pcs', 'Box', '100', '', 120, 1, '2026-06-19 10:13:16', 0),
(755, 9, 'A4S4X2MI3310000377', 'Arcanate 40/160 SC 40 X 250 ml', 'Arcanate 40/160 SC adalah insektisida berspektrum luas dengan kombinasi dua bahan aktif yaitu Emamektin Benzoat 40 g/L dan Indoksakarb 160 g/L. Produk ini bekerja secara ganda sebagai racun kontak dan lambung untuk mengendalikan berbagai jenis hama ulat serta hama penggorok daun pada tanaman pangan dan hortikultura.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Emamektin Benzoat 40 g/L + Indoksakarb 160 g/L\r\nBentuk Formulasi : SC (Suspension Concentrate / Pekatan Suspensi)\r\nJenis : Insektisida kontak dan lambung\r\nCara Kerja : Kontak, lambung, dan sistemik lokal', 'WhatsApp_Image_2026-06-22_at_11_07_33.jpeg', 325500, 316200, 310000, 2880, 0, NULL, 'Botol', 'Box', '40', '', 270, 1, '2026-06-19 10:39:37', 0),
(756, 9, 'B6E5X2MI773000207', 'Bahsan 650 EC 50 X 200 ml', 'Bahsan 650 EC adalah insektisida racun kontak dan lambung berbentuk pekatan yang dapat diemulsikan (EC) dengan bahan aktif Fentoat 650 g/l. Produk ini diproduksi oleh PT Bahtera Boniaga Lestari dan berfungsi untuk mengendalikan berbagai jenis hama perusak tanaman secara efektif, terutama hama pengunyah dan penghisap pada tanaman pangan maupun hortikultura.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Fentoat 650 g/l\r\nBentuk Formulasi : EC (Emulsifiable Concentrate)\r\nCara Kerja : Racun kontak dan lambung', 'WhatsApp_Image_2026-06-22_at_11_07_02.jpeg', 76650, 74460, 73000, 558, 0, NULL, 'Botol', 'Box', '50', '', 270, 1, '2026-06-19 10:53:27', 0),
(757, 9, 'B2S2X2MI1150000390', 'Bellator 265 SC 25 X 200 ml', 'Bellator 265 SC adalah insektisida berspektrum luas berbentuk pekatan suspensi (SC) yang diformulasikan untuk mengendalikan berbagai jenis hama ulat pada tanaman pangan dan hortikultura. Produk ini bekerja secara ganda sebagai racun kontak dan lambung dengan kombinasi dua bahan aktif yaitu Sihalodiamid 100 g/l dan Klorfenapir 165 g/l.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Sihalodiamid 100 g/l + Klorfenapir 165 g/l\r\nBentuk Formulasi : SC (Suspension Concentrate / Pekatan Suspensi)\r\nJenis : Insektisida kontak dan lambung\r\nCara Kerja : Kontak dan racun lambung', 'WhatsApp_Image_2026-06-22_at_11_07_03.jpeg', 157500, 153000, 150000, 95, 0, NULL, 'Botol', 'Box', '0', '', 220, 1, '2026-06-19 10:56:30', 0),
(758, 2, 'B1W1X2GH115000506', 'Benfuron 12/18 WP 160 X 25 gr', 'Benfuron 12/18 WP adalah herbisida sistemik selektif berbentuk tepung yang dapat disuspensikan (WP) yang diformulasikan khusus untuk mengendalikan berbagai jenis gulma pada tanaman padi sawah. Produk ini dapat digunakan mulai dari fase pra-tumbuh hingga pasca-tumbuh dan bekerja efektif membasmi gulma tanpa mengganggu pertumbuhan tanaman padi.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Metil Bensulfuron 12% + Sodium Bispiribak 18%\r\nBentuk Formulasi : WP (Wettable Powder)\r\nJenis : Herbisida sistemik selektif\r\nCara Kerja : Pra-tumbuh dan pasca-tumbuh', 'WhatsApp_Image_2026-06-22_at_11_07_01.jpeg', 15750, 15300, 15000, 37430, 0, NULL, 'Pcs', 'Box', '160', '', 27, 1, '2026-06-19 10:58:26', 0),
(759, 17, 'B8X3MP&P88000584', 'Betasticker 80 X 30 ml', 'roduk ini adalah bahan perata dan perekat pestisida yang diformulasikan untuk meningkatkan efektivitas aplikasi penyemprotan pada tanaman pangan maupun perkebunan. Produk ini membantu pestisida, fungisida, maupun herbisida agar dapat menyebar lebih merata, menempel lebih kuat, dan terserap lebih optimal oleh permukaan daun tanaman.\r\n\r\nDengan kandungan aktif Alkilaril Poliglikol Eter 450 g/l, senyawa ini bekerja dengan cara menurunkan tegangan permukaan air semprot, sehingga larutan pestisida tidak mudah menggumpal atau mengalir jatuh, tetapi dapat menyebar lebih luas di permukaan daun.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Alkilaril Poliglikol Eter 450 g/l\r\nJenis : Perekat dan perata (adjuvant pestisida)\r\nFungsi Utama : Meningkatkan daya sebar dan daya lekat semprotan', 'WhatsApp_Image_2026-06-22_at_11_07_32.jpeg', 8400, 8160, 8000, 320, 0, NULL, 'Pcs', 'Box', '80', '', 50, 1, '2026-06-19 11:49:44', 0),
(760, 1, 'BC2E2X5MF1185000816', 'BM Conzole 250 EC 20 X 500 ml', 'BM Conzole 250 EC adalah fungisida sistemik berbentuk pekatan yang dapat diemulsikan (EC) dengan bahan aktif Propikonazol 250 g/L. Produk ini bekerja sebagai fungisida protektif (pencegah) sekaligus kuratif (penyembuh) untuk mengendalikan berbagai penyakit jamur pada tanaman pangan dan hortikultura.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Propikonazol 250 g/L\r\nBentuk Formulasi : EC (Emulsifiable Concentrate)\r\nJenis : Fungisida sistemik\r\nCara Kerja : Preventif dan kuratif (sistemik)', 'WhatsApp_Image_2026-06-22_at_11_07_34(2).jpeg', 194250, 188700, 185000, 390, 0, NULL, 'Botol', 'Box', '20', '', 520, 1, '2026-06-19 11:53:36', 0),
(761, 1, 'BC2E4X2MF198000900', 'BM Conzole 250 EC 40 X 250 ml', 'BM Conzole 250 EC adalah fungisida sistemik berbentuk pekatan yang dapat diemulsikan (EC) dengan bahan aktif Propikonazol 250 g/L. Produk ini bekerja sebagai fungisida protektif (pencegah) sekaligus kuratif (penyembuh) untuk mengendalikan berbagai penyakit jamur pada tanaman pangan dan hortikultura.\r\n\r\nSpesifikasi Produk :\r\nBahan Aktif : Propikonazol 250 g/L\r\nBentuk Formulasi : EC (Emulsifiable Concentrate)\r\nJenis : Fungisida sistemik\r\nCara Kerja : Preventif dan kuratif (sistemik)', 'WhatsApp_Image_2026-06-22_at_11_11_47.jpeg', 102900, 99960, 98000, 910, 0, NULL, 'Botol', 'Box', '40', '', 270, 1, '2026-06-19 11:55:00', 0),
(762, 19, 'BOKP2X5MPC1150000009', 'BM Optimas Kelp Premium 20 X 500 ml', 'BM Optimas Kelp Premium (sering disebut juga Basfoliar Kelp Premium) adalah pupuk cair biostimulan berbahan dasar ekstrak rumput laut Ecklonia maxima yang diperkaya asam amino serta unsur hara makro dan mikro. Produk ini dirancang untuk meningkatkan pertumbuhan vegetatif, memperkuat perakaran, serta membantu pembentukan bunga dan buah agar lebih optimal.\r\n\r\nSpesifikasi Produk :\r\nJenis : Pupuk cair biostimulan (plant growth stimulant)\r\nBahan Utama : Ekstrak rumput laut Ecklonia maxima + asam amino + unsur hara\r\nBentuk : Larutan cair siap aplikasi\r\n\r\nKandungan Utama :\r\nNitrogen (N) : 8,0%\r\nKalium (K₂O) : 4,3%\r\nAsam Amino : ±10% (termasuk Glycine)\r\nUnsur Mikro : Boron (B), Tembaga (Cu), Besi (Fe), Mangan (Mn), Seng (Zn), Molibdenum (Mo)', 'WhatsApp_Image_2026-06-22_at_11_07_34.jpeg', 157500, 153000, 150000, 100, 0, NULL, 'Botol', 'Box', '20', '', 520, 1, '2026-06-19 11:56:49', 0),
(763, 2, 'BG2S2X1LH9890000119', 'Braunxone Gold 276 SL 20 ltr', 'Braunxone Gold 276 SL adalah herbisida kontak purna tumbuh yang digunakan untuk mengendalikan berbagai jenis gulma seperti gulma berdaun lebar, rumput, dan teki-tekian. Produk ini bekerja sangat cepat dengan mematikan jaringan hijau gulma yang terkena semprotan, sehingga efektif digunakan pada tahap pra-tanam atau sebelum pemupukan dan pengolahan lahan.\r\n\r\nSpesifikasi Produk :\r\nJenis Bahan Aktif : Parakuat Diklorida 276 g/L\r\nBentuk Formulasi : SL (Soluble Liquid / larutan air)\r\nJenis : Herbisida kontak non-selektif\r\nCara Kerja : Kontak langsung pada jaringan hijau gulma', 'WhatsApp_Image_2026-06-22_at_11_07_32(1).jpeg', 934500, 907800, 890000, 140, 0, NULL, 'Botol', 'Box', '20', '', 1200, 1, '2026-06-19 11:58:39', 0),
(764, 2, 'BG2S2X1LH446500200', 'Braunxone Gold 276 SL 20 X 1 ltr', 'Braunxone Gold 276 SL adalah herbisida kontak purna tumbuh yang digunakan untuk mengendalikan berbagai jenis gulma seperti gulma berdaun lebar, rumput, dan teki-tekian. Produk ini bekerja sangat cepat dengan mematikan jaringan hijau gulma yang terkena semprotan, sehingga efektif digunakan pada tahap pra-tanam atau sebelum pemupukan dan pengolahan lahan.\r\n\r\nSpesifikasi Produk :\r\nJenis Bahan Aktif : Parakuat Diklorida 276 g/L\r\nBentuk Formulasi : SL (Soluble Liquid / larutan air)\r\nJenis : Herbisida kontak non-selektif\r\nCara Kerja : Kontak langsung pada jaringan hijau gulma', 'WhatsApp_Image_2026-06-22_at_11_07_35.jpeg', 48825, 47430, 46500, 7640, 0, NULL, 'Botol', 'Box', '20', '', 1200, 1, '2026-06-19 12:00:00', 0),
(765, 2, 'BG2S4X5LH2227500256', 'Braunxone Gold 276 SL 4 X 5 ltr', 'Braunxone Gold 276 SL adalah herbisida kontak purna tumbuh yang digunakan untuk mengendalikan berbagai jenis gulma seperti gulma berdaun lebar, rumput, dan teki-tekian. Produk ini bekerja sangat cepat dengan mematikan jaringan hijau gulma yang terkena semprotan, sehingga efektif digunakan pada tahap pra-tanam atau sebelum pemupukan dan pengolahan lahan.\r\n\r\nSpesifikasi Produk :\r\nJenis Bahan Aktif : Parakuat Diklorida 276 g/L\r\nBentuk Formulasi : SL (Soluble Liquid / larutan air)\r\nJenis : Herbisida kontak non-selektif\r\nCara Kerja : Kontak langsung pada jaringan hijau gulma', NULL, 238875, 238875, 227500, 8, 0, NULL, 'Botol', 'Box', '4', '1', 5200, 1, '2026-06-19 12:00:56', 0),
(766, 14, 'CS1X1X1GB338000376', 'Cabe Sret 12 X 15 X 10 gr', 'Cabai Rawit Frutescens adalah varietas cabai rawit yang termasuk dalam spesies Capsicum frutescens dengan karakter produksi tinggi dan buah lebat. Varietas ini banyak dibudidayakan di dataran rendah karena memiliki adaptasi yang baik serta potensi hasil panen yang tinggi.\r\n\r\nSpesifikasi Produk :\r\nJenis : Cabai Rawit (Capsicum frutescens)\r\nAdaptasi : Dataran rendah\r\nUmur Panen : ± 87 HST\r\nPotensi Hasil : ± 17 ton/ha\r\n\r\nKarakteristik Buah :\r\nBentuk Buah : Kecil memanjang\r\nUkuran Buah : ± 4 x 1 cm\r\nWarna Buah : Putih kekuningan saat muda dan merah saat matang', 'cabe_sret1.jpeg', 39900, 38760, 38000, 630, 0, NULL, 'Pcs', 'Box', '180', '1', 12, 1, '2026-06-19 12:02:56', 0),
(767, 14, 'CWF2X1X2BB2250000600', 'Cabe Warrior F1 20 X 12 X 2250 biji', 'Cabe Warrior F1 adalah benih cabai merah besar hibrida unggulan produksi PT Bisi International, Tbk (Cap Kapal Terbang) yang dikenal memiliki ketahanan tinggi terhadap penyakit virus serta produktivitas yang sangat baik. Varietas ini banyak dipilih petani karena stabil di berbagai kondisi musim dan memiliki hasil panen yang tinggi.\r\n\r\nSpesifikasi Produk :\r\nJenis : Benih Cabai Merah Besar Hibrida\r\nProdusen : PT Bisi International, Tbk\r\nTipe Tanaman : Vigor kuat dan adaptif\r\nAdaptasi : Dataran rendah hingga menengah\r\n\r\nKarakteristik Buah :\r\nBentuk Buah : Cabai merah besar\r\nBobot Buah : Besar dan padat\r\nWarna : Hijau saat muda dan merah saat matang\r\nKualitas : Tahan simpan dan tahan angkut', 'WhatsApp_Image_2026-06-17_at_15_17_04.jpeg', 262500, 255000, 250000, 102, 0, NULL, 'Pcs', 'Box', '120', '1', 12, 1, '2026-06-19 12:06:40', 0),
(768, 13, 'CD2X1KLL219800679', 'Calcium D-Diana 20 X 1 kg', 'Pupuk Kalsium D’Diana adalah pupuk pertanian berkualitas tinggi yang diformulasikan khusus untuk membantu mencegah kerontokan bunga dan buah, mengurangi serangan penyakit jamur, serta memperkuat struktur tanaman. Produk ini juga diperkaya dengan unsur boron yang berperan penting dalam pembentukan dan kualitas buah.\r\n\r\nSpesifikasi Produk :\r\nJenis : Pupuk kalsium + boron\r\nFungsi Utama : Pencegah kerontokan bunga dan buah\r\nBentuk : Pupuk larut/siap aplikasi (sesuai formulasi produk)\r\n\r\nKandungan Utama :\r\nKalsium (Ca) : Berperan memperkuat dinding sel tanaman\r\nBoron (B) : Mendukung pembentukan buah dan jaringan tanaman', 'd_diana.jpeg', 20790, 20196, 19800, 1040, 0, NULL, 'Pcs', 'Box', '20', '1', 1200, 1, '2026-06-19 12:07:59', 0),
(769, 2, 'C4S2LH9860000841', 'Calgary 480 SL 20 ltr', 'Calgary 480 SL adalah herbisida sistemik purna tumbuh yang digunakan untuk mengendalikan berbagai jenis gulma hingga ke bagian akar. Produk ini berbentuk larutan air berwarna kuning keemasan dengan bahan aktif Isopropil amina glifosat 480 g/L.\r\n\r\nSpesifikasi Produk :\r\nJenis : Herbisida sistemik purna tumbuh\r\nBahan Aktif : Isopropil amina glifosat 480 g/L\r\nFormulasi : SL (Soluble Liquid / larutan air)\r\n\r\nCara Kerja :\r\nCalgary 480 SL diserap melalui daun gulma, kemudian ditranslokasikan ke seluruh jaringan tanaman hingga ke akar. Proses ini menyebabkan gulma mati secara menyeluruh dan menghambat pertumbuhan kembali.', NULL, 903000, 877200, 860000, 10, 0, NULL, 'Botol', 'Box', '10', '1', 22000, 1, '2026-06-19 12:10:41', 0),
(770, 2, 'C4S2X1LH445000897', 'Calgary 480 SL 20 X 1 ltr', 'Calgary 480 SL adalah herbisida sistemik purna tumbuh yang digunakan untuk mengendalikan berbagai jenis gulma hingga ke bagian akar. Produk ini berbentuk larutan air berwarna kuning keemasan dengan bahan aktif Isopropil amina glifosat 480 g/L.\r\n\r\nSpesifikasi Produk :\r\nJenis : Herbisida sistemik purna tumbuh\r\nBahan Aktif : Isopropil amina glifosat 480 g/L\r\nFormulasi : SL (Soluble Liquid / larutan air)\r\n\r\nCara Kerja :\r\nCalgary 480 SL diserap melalui daun gulma, kemudian ditranslokasikan ke seluruh jaringan tanaman hingga ke akar. Proses ini menyebabkan gulma mati secara menyeluruh dan menghambat pertumbuhan kembali.', NULL, 47250, 45900, 45000, 534, 0, NULL, 'Botol', 'Box', '20', '1', 1200, 1, '2026-06-19 12:11:37', 0),
(771, 2, 'CG2S2LH7740000988', 'Camix Gold 200 SL 20 ltr', 'Camix Gold 200 SL adalah herbisida kontak purna tumbuh berspektrum luas yang digunakan untuk mengendalikan berbagai jenis gulma pada lahan pertanian dan perkebunan. Produk ini bekerja cepat untuk mematikan bagian hijau gulma yang terkena semprotan.\r\n\r\nSpesifikasi Produk :\r\nJenis : Herbisida kontak non-selektif\r\nFormulasi : SL (Soluble Liquid / larutan air)\r\nBahan Aktif : Golongan Parakuat (Paraquat dichloride)\r\n\r\nCara Kerja :\r\nBekerja sebagai herbisida kontak yang merusak jaringan hijau (klorofil) gulma secara langsung. Gulma akan mengering dan mati pada bagian yang terkena semprotan dalam waktu relatif cepat.', NULL, 777000, 754800, 740000, 10, 0, NULL, 'Botol', 'Box', '10', '1', 22000, 1, '2026-06-19 12:13:08', 0),
(772, 2, 'CG2S2X1LH439000051', 'Camix Gold 200 SL 20 X 1 ltr', 'Camix Gold 200 SL adalah herbisida kontak purna tumbuh berspektrum luas yang digunakan untuk mengendalikan berbagai jenis gulma pada lahan pertanian dan perkebunan. Produk ini bekerja cepat untuk mematikan bagian hijau gulma yang terkena semprotan.\r\n\r\nSpesifikasi Produk :\r\nJenis : Herbisida kontak non-selektif\r\nFormulasi : SL (Soluble Liquid / larutan air)\r\nBahan Aktif : Golongan Parakuat (Paraquat dichloride)\r\n\r\nCara Kerja :\r\nBekerja sebagai herbisida kontak yang merusak jaringan hijau (klorofil) gulma secara langsung. Gulma akan mengering dan mati pada bagian yang terkena semprotan dalam waktu relatif cepat.', 'camix_gold_1_liter.jpeg', 40950, 39780, 39000, 1479, 0, NULL, 'Botol', 'Box', '20', '1', 1200, 1, '2026-06-19 12:14:11', 0),
(773, 2, 'CG2S4X5LH1190000122', 'Camix Gold 200 SL 4 X 5 ltr', 'Camix Gold 200 SL adalah herbisida kontak purna tumbuh berspektrum luas yang digunakan untuk mengendalikan berbagai jenis gulma pada lahan pertanian dan perkebunan. Produk ini bekerja cepat untuk mematikan bagian hijau gulma yang terkena semprotan.\r\n\r\nSpesifikasi Produk :\r\nJenis : Herbisida kontak non-selektif\r\nFormulasi : SL (Soluble Liquid / larutan air)\r\nBahan Aktif : Golongan Parakuat (Paraquat dichloride)\r\n\r\nCara Kerja :\r\nBekerja sebagai herbisida kontak yang merusak jaringan hijau (klorofil) gulma secara langsung. Gulma akan mengering dan mati pada bagian yang terkena semprotan dalam waktu relatif cepat.', NULL, 199500, 193800, 190000, 144, 0, NULL, 'Botol', 'Box', '4', '1', 5200, 1, '2026-06-19 12:15:22', 0),
(774, 9, 'CF3E5X1MI333000259', 'Cash Flow 30 EC 50 X 100 ml', 'Cash Flow 30 EC adalah insektisida berbentuk pekatan yang dapat diemulsikan (EC) dengan bahan aktif Emamektin Benzoat 30 g/L. Produk ini bekerja sebagai racun kontak, lambung, serta translaminar yang efektif untuk mengendalikan berbagai jenis hama ulat pada tanaman pertanian dan hortikultura.\r\n\r\nSpesifikasi Produk :\r\nJenis : Insektisida kontak, lambung, dan translaminar\r\nBahan Aktif : Emamektin Benzoat 30 g/L\r\nFormulasi : EC (Emulsifiable Concentrate)', 'cash_flow_100ml.jpeg', 34650, 33660, 33000, 150, 0, NULL, 'Botol', 'Box', '0', '1', 120, 1, '2026-06-19 12:17:39', 0),
(775, 14, 'CFKF5X1X1GB1135000966', 'Cauli Flower Kiran F1 50 X 10 X 10 gr', 'Bunga Kol TM Kiran F1 adalah varietas kubis bunga (cauliflower) hibrida unggulan dari PT. Tani Murni Indonesia yang dirancang khusus untuk adaptasi di dataran rendah hingga menengah. Varietas ini dikenal genjah, produktif, dan memiliki ketahanan penyakit yang baik sehingga banyak digunakan oleh petani sayuran komersial.\r\n\r\nSpesifikasi Produk :\r\nJenis : Kubis bunga (Cauliflower) hibrida F1\r\nProdusen : PT. Tani Murni Indonesia\r\nRekomendasi Dataran : Rendah hingga menengah\r\nUmur Panen : 45–50 hari setelah tanam (HST)\r\n\r\nKarakteristik Tanaman :\r\nVigor tanaman : Kuat dan adaptif\r\nKondisi tumbuh : Cocok di tanah berpasir maupun lahan sawah\r\nKetahanan : Toleran terhadap panas dan beberapa penyakit utama', 'WhatsApp_Image_2026-06-17_at_15_17_03.jpeg', 141750, 137700, 135000, 2380, 0, NULL, 'Pcs', 'Box', '500', '1', 12, 1, '2026-06-19 12:29:26', 0),
(776, 14, 'CFWS2X1X1GB1120000017', 'Cauli Flower White Shot 25 X 10 X 10 gr', 'Cauliflower White Shot F1 adalah benih kembang kol (cauliflower) hibrida unggulan produksi Sakata Seed (Jepang) yang populer di Indonesia. Varietas ini dikenal memiliki vigor tanaman yang kuat, adaptasi luas, serta hasil panen yang tinggi dengan kualitas krop premium.\r\n\r\nSpesifikasi Produk :\r\nJenis : Kembang kol hibrida F1\r\nProdusen : Sakata Seed (Jepang)\r\nAdaptasi : Dataran rendah hingga menengah\r\nMusim tanam : Cocok musim hujan maupun kemarau', 'WhatsApp_Image_2026-06-17_at_15_17_03(1).jpeg', 126000, 122400, 120000, 80, 0, NULL, 'Pcs', 'Box', '0', '1', 12, NULL, '2026-06-19 12:30:17', 0),
(777, 2, 'C2S1X1LH445000609', 'Celquat 276 SL 10 X 1 ltr', 'Celquat 276 SL adalah herbisida kontak purna tumbuh berspektrum luas dengan bahan aktif Parakuat Diklorida 276 g/L yang bekerja sangat cepat untuk mengendalikan gulma di lahan pertanian dan perkebunan.\r\n\r\nProduk ini bekerja dengan cara merusak jaringan hijau (klorofil) gulma yang terkena semprotan, sehingga gulma akan cepat mengering. Karena bersifat kontak, efeknya hanya mengenai bagian tanaman yang terkena langsung.\r\n\r\nKarakteristik utama :\r\n\r\nJenis : Herbisida kontak non-selektif\r\nBahan aktif : Parakuat Diklorida 276 g/L\r\nTarget : Gulma berdaun lebar, rumput, alang-alang, paku-pakuan\r\nPenggunaan : Perkebunan, tegalan, dan persiapan lahan', 'Celquat_1ltr.jpg', 47250, 45900, 45000, 1, 0, NULL, 'Botol', 'Box', '10', '1', 1200, 1, '2026-06-19 12:40:09', 0),
(778, 9, 'C31X2KI329500817', 'Centa-Fur 3GR 10 X 2 kg', 'Centa-Fur 3GR adalah insektisida sekaligus nematisida sistemik berbentuk butiran (granule) berwarna ungu yang mengandung bahan aktif Karbofuran 3%. Produk ini bekerja sebagai racun kontak dan lambung untuk mengendalikan hama yang hidup di dalam tanah, akar, dan jaringan tanaman.\r\n\r\nSpesifikasi Produk :\r\nJenis : Insektisida + nematisida sistemik granular\r\nBahan Aktif : Karbofuran 3%\r\nFormulasi : 3GR (Granule)\r\n\r\nCara Kerja :\r\nKarbofuran diserap oleh tanaman melalui akar dan tersebar ke seluruh jaringan tanaman. Senyawa ini bekerja dengan mengganggu sistem saraf hama sehingga menyebabkan kematian pada hama tanah maupun hama pengisap.', NULL, 30975, 30090, 29500, 1306, 0, NULL, 'Pcs', 'Box', '10', '1', 5, 1, '2026-06-19 12:43:37', 0),
(779, 9, 'C1S2X2MI3320000041', 'Chlordin 100/200 SC 20 X 250 ml', 'Chlordin 100/200 SC adalah insektisida sistemik ganda berbentuk pekatan suspensi (SC) dari PT Mitra Kreasidharma yang diformulasikan untuk mengendalikan berbagai jenis hama pada tanaman pertanian dan hortikultura. Produk ini memiliki kombinasi bahan aktif yang kuat sehingga efektif terhadap hama yang sudah resisten.\r\n\r\nSpesifikasi Produk :\r\nJenis : Insektisida sistemik, kontak, dan lambung\r\nFormulasi : SC (Suspension Concentrate)\r\nBahan Aktif :\r\n\r\nKlorantraniliprol 100 g/L\r\nKlorfenapir 200 g/L\r\n\r\nCara Kerja :\r\nChlordin 100/200 SC bekerja dengan cara diserap dan disebarkan ke seluruh jaringan tanaman (sistemik), serta bekerja sebagai racun kontak dan lambung. Hama akan mati saat terkena langsung maupun ketika memakan jaringan tanaman yang sudah terpapar bahan aktif.', 'clhordin_250ml.jpeg', 336000, 326400, 320000, 9049, 0, NULL, 'Botol', 'Box', '20', '1', 270, 1, '2026-06-19 12:47:21', 0),
(780, 9, 'C1S2X5MI6615000492', 'Chlordin 100/200 SC 20 X 500 ml', 'Chlordin 100/200 SC adalah insektisida sistemik ganda berbentuk pekatan suspensi (SC) dari PT Mitra Kreasidharma yang diformulasikan untuk mengendalikan berbagai jenis hama pada tanaman pertanian dan hortikultura. Produk ini memiliki kombinasi bahan aktif yang kuat sehingga efektif terhadap hama yang sudah resisten.\r\n\r\nSpesifikasi Produk :\r\nJenis : Insektisida sistemik, kontak, dan lambung\r\nFormulasi : SC (Suspension Concentrate)\r\nBahan Aktif :\r\n\r\nKlorantraniliprol 100 g/L\r\nKlorfenapir 200 g/L\r\n\r\nCara Kerja :\r\nChlordin 100/200 SC bekerja dengan cara diserap dan disebarkan ke seluruh jaringan tanaman (sistemik), serta bekerja sebagai racun kontak dan lambung. Hama akan mati saat terkena langsung maupun ketika memakan jaringan tanaman yang sudah terpapar bahan aktif.', NULL, 645750, 627300, 615000, 960, 0, NULL, 'Botol', 'Box', '20', '1', 520, 1, '2026-06-19 12:54:52', 0),
(781, 9, 'C1S5X1MI1142000561', 'Chlordin 100/200 SC 50 X 100 ml', 'Chlordin 100/200 SC adalah insektisida sistemik ganda berbentuk pekatan suspensi (SC) dari PT Mitra Kreasidharma yang diformulasikan untuk mengendalikan berbagai jenis hama pada tanaman pertanian dan hortikultura. Produk ini memiliki kombinasi bahan aktif yang kuat sehingga efektif terhadap hama yang sudah resisten.\r\n\r\nSpesifikasi Produk :\r\nJenis : Insektisida sistemik, kontak, dan lambung\r\nFormulasi : SC (Suspension Concentrate)\r\nBahan Aktif :\r\n\r\nKlorantraniliprol 100 g/L\r\nKlorfenapir 200 g/L\r\n\r\nCara Kerja :\r\nChlordin 100/200 SC bekerja dengan cara diserap dan disebarkan ke seluruh jaringan tanaman (sistemik), serta bekerja sebagai racun kontak dan lambung. Hama akan mati saat terkena langsung maupun ketika memakan jaringan tanaman yang sudah terpapar bahan aktif.', 'chlordin_100ml.jpeg', 149100, 144840, 142000, 7040, 0, NULL, 'Botol', 'Box', '50', '1', 120, 1, '2026-06-19 12:56:01', 0),
(782, 9, 'C1Z4X2MI1120000066', 'Colam 141/106 ZC 48 X 250 ml', 'Colam 141/106 ZC adalah insektisida berspektrum luas berbentuk pekatan suspensi campuran (ZC) yang bekerja sebagai racun kontak dan lambung untuk mengendalikan berbagai hama tanaman.\r\n\r\nSpesifikasi Produk :\r\nJenis : Insektisida kontak dan lambung\r\nFormulasi : ZC (Suspension Concentrate campuran)\r\nBentuk : Cairan pekat berwarna putih\r\nBahan Aktif :\r\n\r\nTiametoksam 141 g/L\r\nLamda-sihalotrin 106 g/L\r\n\r\nCara Kerja :\r\nColam 141/106 ZC bekerja dengan dua mekanisme utama:\r\n\r\nTiametoksam bersifat sistemik, diserap tanaman dan melindungi dari dalam jaringan.\r\nLamda-sihalotrin bekerja cepat sebagai racun kontak yang melumpuhkan hama.', NULL, 126000, 122400, 120000, 624, 0, NULL, 'Botol', 'Box', '48', '1', 270, 1, '2026-06-19 13:04:26', 0),
(783, 9, 'C1Z6X1MI554000188', 'Colam 141/106 ZC 64 X 100 ml', 'Colam 141/106 ZC adalah insektisida berspektrum luas berbentuk pekatan suspensi campuran (ZC) yang bekerja sebagai racun kontak dan lambung untuk mengendalikan berbagai hama tanaman.\r\n\r\nSpesifikasi Produk :\r\nJenis : Insektisida kontak dan lambung\r\nFormulasi : ZC (Suspension Concentrate campuran)\r\nBentuk : Cairan pekat berwarna putih\r\nBahan Aktif :\r\n\r\nTiametoksam 141 g/L\r\nLamda-sihalotrin 106 g/L\r\n\r\nCara Kerja :\r\nColam 141/106 ZC bekerja dengan dua mekanisme utama:\r\n\r\nTiametoksam bersifat sistemik, diserap tanaman dan melindungi dari dalam jaringan.\r\nLamda-sihalotrin bekerja cepat sebagai racun kontak yang melumpuhkan hama.', NULL, 56700, 55080, 54000, 448, 0, NULL, 'Botol', 'Box', '64', '1', 120, 1, '2026-06-19 13:06:28', 0),
(784, 1, 'C7W4X4GF990000081', 'Copcide 77 WP 40 X 400 gr', 'Copcide 77 WP adalah fungisida sekaligus bakterisida protektif berbentuk tepung (WP) berwarna biru yang dapat disuspensikan dalam air. Produk ini diproduksi oleh Cap Kapal Terbang dan digunakan untuk mengendalikan penyakit jamur serta bakteri pada berbagai tanaman budidaya.\r\n\r\nSpesifikasi Produk :\r\nJenis : Fungisida + bakterisida kontak (protektif)\r\nFormulasi : WP (Wettable Powder / tepung yang dapat disuspensikan)\r\nBahan Aktif : Tembaga Hidroksida 77% (setara Cu ±50%)\r\n\r\nCara Kerja :\r\nCopcide 77 WP bekerja secara kontak dan protektif, membentuk lapisan pelindung pada permukaan tanaman yang mencegah masuknya spora jamur dan bakteri penyebab penyakit.', 'copcide.jpeg', 94500, 91800, 90000, 3260, 0, NULL, 'Pcs', 'Box', '40', '1', 420, 1, '2026-06-19 15:18:01', 0),
(785, 9, 'C5E2X4MI658500797', 'Cowin 550 EC 25 X 400 ml', 'Cowin 550 EC adalah insektisida racun kontak dan lambung berbentuk pekatan yang dapat diemulsikan (EC) dengan kombinasi dua bahan aktif yang bekerja sinergis untuk mengendalikan berbagai jenis hama pada tanaman.\r\n\r\nSpesifikasi Produk :\r\nJenis : Insektisida kontak dan lambung\r\nFormulasi : EC (Emulsifiable Concentrate / pekatan yang dapat diemulsikan)\r\nBahan Aktif :\r\n\r\nKlorpirifos 500 g/L\r\nSipermetrin 50 g/L\r\n\r\nCara Kerja :\r\nCowin 550 EC bekerja melalui dua mekanisme:\r\n\r\nRacun kontak → membunuh hama saat terkena langsung oleh larutan semprot.\r\nRacun lambung → membunuh hama ketika memakan bagian tanaman yang telah diaplikasikan.', NULL, 61425, 59670, 58500, 26, 0, NULL, 'Botol', 'Box', '25', '1', 420, 1, '2026-06-20 13:09:57', 0),
(786, 18, 'C2X5MB664000183', 'Cuprinomat 24 X 500 ml', 'Cuprinomat adalah pupuk/biostimulan tanaman yang menggabungkan asam amino, senyawa humat (asam humat dan asam fulvat), serta unsur mikro untuk membantu meningkatkan pertumbuhan, memperbaiki kondisi tanaman, dan memperkuat ketahanan alami tanaman terhadap stres lingkungan.\r\n\r\nSpesifikasi Produk :\r\nJenis : Biostimulan / nutrisi tanaman\r\nKomponen utama :\r\n\r\nAsam Amino\r\nAsam Humat\r\nAsam Fulvat\r\nUnsur mikro (Tembaga & Seng)\r\n\r\nKomposisi & Manfaat Utama :\r\n\r\n45% Asam Amino\r\n\r\nMembantu mempercepat pertumbuhan tanaman\r\nMendukung pembentukan tunas dan jaringan baru\r\nMembantu pemulihan tanaman akibat stres cuaca, pindah tanam, atau gangguan hama\r\n\r\n22% Senyawa Humat\r\nTerdiri dari:\r\n\r\n14% Asam Humat → membantu memperbaiki struktur tanah, meningkatkan perkembangan akar, dan meningkatkan kemampuan tanaman menyerap nutrisi\r\n8% Asam Fulvat → membantu proses penyerapan unsur hara agar lebih cepat dan optimal\r\n\r\nNutrisi Mikro (Tembaga & Seng)\r\n\r\nMembantu meningkatkan imunitas alami tanaman\r\nMendukung proses metabolisme dan pertumbuhan tanaman\r\nMembantu tanaman lebih tahan terhadap gangguan penyakit akibat jamur, bakteri, dan virus', NULL, 67200, 65280, 64000, 2388, 0, NULL, 'Botol', 'Box', '24', '1', 520, 1, '2026-06-20 13:49:43', 0),
(787, 9, 'C3G1X2KI548250457', 'Curaterr 3 GR 10 X 2 kg', 'Curaterr 3GR adalah insektisida sekaligus nematisida sistemik berbentuk butiran (granule) yang diaplikasikan dengan cara ditaburkan pada area perakaran tanaman. Produk ini mengandung bahan aktif Karbofuran 3% dan efektif untuk mengendalikan hama yang menyerang bagian akar, batang, maupun jaringan tanaman.\r\n\r\nSpesifikasi Produk :\r\nJenis : Insektisida + nematisida sistemik\r\nFormulasi : 3GR (Granule / butiran tabur)\r\nBahan Aktif : Karbofuran 3%', 'curaterr.jpeg', 50663, 49215, 48250, 3812, 0, NULL, 'Pcs', 'Box', '10', '1', 5, 1, '2026-06-20 13:54:17', 0),
(788, 9, 'C5E2X1LI1135000675', 'Cyperban 590 EC 20 X 1 ltr', 'Cyber Ban 590 EC adalah insektisida sekaligus akarisida berbentuk pekatan emulsi (EC) yang diformulasikan untuk mengendalikan berbagai jenis hama pada tanaman, khususnya padi. Produk ini didistribusikan oleh PT Kapal Terbang Nusantara.\r\n\r\nSpesifikasi Produk :\r\nJenis : Insektisida + akarisida sistemik\r\nFormulasi : EC (Emulsifiable Concentrate / pekatan yang dapat diemulsikan)\r\nBahan Aktif : Klorantraniliprol 590 g/L\r\n\r\nCara Kerja :\r\nCyber Ban 590 EC bekerja secara sistemik, yaitu bahan aktif diserap oleh tanaman dan menyebar ke jaringan tanaman sehingga mampu mengendalikan hama yang berada atau bersembunyi di dalam bagian tanaman. Produk ini juga memiliki efek kontak dengan kemampuan knock-down terhadap hama.', NULL, 141750, 137700, 135000, 100, 0, NULL, 'Pcs', 'Box', '20', '1', 1200, 1, '2026-06-20 13:57:55', 0),
(789, 9, 'C5E2X5MI770000741', 'Cyperban 590 EC 20 X 500 ml', 'Cyber Ban 590 EC adalah insektisida sekaligus akarisida berbentuk pekatan emulsi (EC) yang diformulasikan untuk mengendalikan berbagai jenis hama pada tanaman, khususnya padi. Produk ini didistribusikan oleh PT Kapal Terbang Nusantara.\r\n\r\nSpesifikasi Produk :\r\nJenis : Insektisida + akarisida sistemik\r\nFormulasi : EC (Emulsifiable Concentrate / pekatan yang dapat diemulsikan)\r\nBahan Aktif : Klorantraniliprol 590 g/L\r\n\r\nCara Kerja :\r\nCyber Ban 590 EC bekerja secara sistemik, yaitu bahan aktif diserap oleh tanaman dan menyebar ke jaringan tanaman sehingga mampu mengendalikan hama yang berada atau bersembunyi di dalam bagian tanaman. Produk ini juga memiliki efek kontak dengan kemampuan knock-down terhadap hama.', NULL, 73500, 71400, 70000, 100, 0, NULL, 'Botol', 'Box', '20', '1', 520, 1, '2026-06-20 13:59:01', 0),
(790, 9, 'D1E1X1LI2207500215', 'Damex 18 EC 10 X 1 ltr', 'Damex 18 EC adalah insektisida berbentuk pekatan yang dapat diemulsikan (EC) dengan sifat racun kontak dan lambung. Produk ini diproduksi oleh PT Maju Makmur Utomo dan digunakan untuk mengendalikan berbagai jenis hama pada tanaman pertanian.\r\n\r\nSpesifikasi Produk :\r\nJenis : Insektisida kontak dan lambung\r\nFormulasi : EC (Emulsifiable Concentrate)\r\nBentuk : Cairan berwarna kuning kecokelatan\r\nBahan Aktif : Abamektin 18 g/L', 'Damex_1_liter.jpg', 217875, 211650, 207500, 119, 0, NULL, 'Botol', 'Box', '10', '1', 1200, 1, '2026-06-20 14:06:55', 0),
(791, 9, 'D1E3X5MI1115500344', 'Damex 18 EC 30 X 500 ml', 'Damex 18 EC adalah insektisida berbentuk pekatan yang dapat diemulsikan (EC) dengan sifat racun kontak dan lambung. Produk ini diproduksi oleh PT Maju Makmur Utomo dan digunakan untuk mengendalikan berbagai jenis hama pada tanaman pertanian.\r\n\r\nSpesifikasi Produk :\r\nJenis : Insektisida kontak dan lambung\r\nFormulasi : EC (Emulsifiable Concentrate)\r\nBentuk : Cairan berwarna kuning kecokelatan\r\nBahan Aktif : Abamektin 18 g/L', 'Damex_500ml.jpg', 121275, 117810, 115500, 312, 0, NULL, 'Botol', 'Box', '30', '1', 520, 1, '2026-06-20 14:09:04', 0),
(792, 2, 'D1S4X5LH1145000702', 'Danaxone 135 SL 4 X 5 ltr', 'Danaxone 135 SL adalah herbisida kontak purna tumbuh berbentuk larutan (SL) berwarna hijau tua yang digunakan untuk mengendalikan berbagai jenis gulma pada lahan pertanian maupun perkebunan. Produk ini mengandung bahan aktif Parakuat Diklorida 135 g/L yang bekerja cepat pada bagian tanaman yang terkena semprotan.\r\n\r\nSpesifikasi Produk :\r\nJenis : Herbisida kontak non-selektif\r\nFormulasi : SL (Soluble Liquid / larutan dalam air)\r\nBahan Aktif : Parakuat Diklorida 135 g/L', NULL, 152250, 147900, 145000, 12, 0, NULL, 'Botol', 'Box', '4', '1', 5200, 1, '2026-06-20 14:15:02', 0),
(793, 9, 'D4S1X1LI11013500874', 'Dekapirim 400 SC 12 X 1 ltr', 'Dekapirim 400 SC adalah insektisida berspektrum luas berbentuk Suspension Concentrate (SC) yang bekerja sebagai racun kontak, lambung, dan sistemik untuk mengendalikan berbagai jenis hama pada tanaman pangan, sayuran, dan buah-buahan.\r\n\r\nSpesifikasi Produk :\r\nJenis : Insektisida kontak, lambung, dan sistemik\r\nFormulasi : SC (Suspension Concentrate)\r\nBahan Aktif :\r\n\r\nKlorfenapir 200 g/L\r\nImidakloprid 200 g/L\r\n\r\nCara Kerja :\r\nDekapirim 400 SC memiliki kombinasi dua bahan aktif dengan mekanisme berbeda:\r\n\r\nKlorfenapir\r\nBekerja sebagai racun kontak dan lambung yang mengganggu proses metabolisme energi serangga sehingga menyebabkan hama berhenti makan dan mati.\r\nImidakloprid\r\nBersifat sistemik dari golongan neonicotinoid, diserap oleh tanaman dan menyebar ke jaringan tanaman untuk mengendalikan hama penghisap.', NULL, 1064175, 1033770, 1013500, 12, 0, NULL, 'Botol', 'Box', '12', '1', 1200, 1, '2026-06-20 14:17:54', 0),
(794, 9, 'D4S2X5MI5523000351', 'Dekapirim 400 SC 20 X 500 ml', 'Dekapirim 400 SC adalah insektisida berspektrum luas berbentuk Suspension Concentrate (SC) yang bekerja sebagai racun kontak, lambung, dan sistemik untuk mengendalikan berbagai jenis hama pada tanaman pangan, sayuran, dan buah-buahan.\r\n\r\nSpesifikasi Produk :\r\nJenis : Insektisida kontak, lambung, dan sistemik\r\nFormulasi : SC (Suspension Concentrate)\r\nBahan Aktif :\r\n\r\nKlorfenapir 200 g/L\r\nImidakloprid 200 g/L\r\n\r\nCara Kerja :\r\nDekapirim 400 SC memiliki kombinasi dua bahan aktif dengan mekanisme berbeda:\r\n\r\nKlorfenapir\r\nBekerja sebagai racun kontak dan lambung yang mengganggu proses metabolisme energi serangga sehingga menyebabkan hama berhenti makan dan mati.\r\nImidakloprid\r\nBersifat sistemik dari golongan neonicotinoid, diserap oleh tanaman dan menyebar ke jaringan tanaman untuk mengendalikan hama penghisap.', 'Dekapirim_500ml.jpg', 549150, 533460, 523000, 38, 0, NULL, 'Botol', 'Box', '20', '1', 520, 1, '2026-06-20 14:25:51', 0),
(795, 9, 'D4S5X1MI1112000424', 'Dekapirim 400 SC 50 X 100 ml', 'Dekapirim 400 SC adalah insektisida berspektrum luas berbentuk Suspension Concentrate (SC) yang bekerja sebagai racun kontak, lambung, dan sistemik untuk mengendalikan berbagai jenis hama pada tanaman pangan, sayuran, dan buah-buahan.\r\n\r\nSpesifikasi Produk :\r\nJenis : Insektisida kontak, lambung, dan sistemik\r\nFormulasi : SC (Suspension Concentrate)\r\nBahan Aktif :\r\n\r\nKlorfenapir 200 g/L\r\nImidakloprid 200 g/L\r\n\r\nCara Kerja :\r\nDekapirim 400 SC memiliki kombinasi dua bahan aktif dengan mekanisme berbeda:\r\n\r\nKlorfenapir\r\nBekerja sebagai racun kontak dan lambung yang mengganggu proses metabolisme energi serangga sehingga menyebabkan hama berhenti makan dan mati.\r\nImidakloprid\r\nBersifat sistemik dari golongan neonicotinoid, diserap oleh tanaman dan menyebar ke jaringan tanaman untuk mengendalikan hama penghisap.', 'Dekapirim_100ml.jpg', 117600, 114240, 112000, 150, 0, NULL, 'Botol', 'Box', '50', '1', 120, 1, '2026-06-20 14:27:04', 0),
(796, 9, 'D3W1X5GI7750000815', 'Dektin 30 WG 12 X 500 gr', 'Dektin 30 WG adalah insektisida berspektrum luas berbentuk butiran yang dapat didispersikan dalam air (WG) yang bekerja sebagai racun kontak dan lambung untuk mengendalikan berbagai hama pada tanaman, terutama hama ulat dan serangga penghisap.\r\n\r\nSpesifikasi Produk :\r\nJenis : Insektisida kontak dan lambung\r\nFormulasi : WG (Water Dispersible Granule / butiran mudah larut dalam air)\r\nBahan Aktif :\r\n\r\nTiametoksam (Thiamethoxam) 20%\r\nEmamektin Benzoat (Emamectin Benzoate) 10%', 'Dektin_500gr.jpg', 787500, 765000, 750000, 181, 0, NULL, 'Pcs', 'Box', '12', '1', 520, 1, '2026-06-20 14:33:35', 0),
(797, 9, 'D3W5X5GI989000435', 'Dektin 30 WG 50 X 50 gr', 'Dektin 30 WG adalah insektisida berspektrum luas berbentuk butiran yang dapat didispersikan dalam air (WG) yang bekerja sebagai racun kontak dan lambung untuk mengendalikan berbagai hama pada tanaman, terutama hama ulat dan serangga penghisap.\r\n\r\nSpesifikasi Produk :\r\nJenis : Insektisida kontak dan lambung\r\nFormulasi : WG (Water Dispersible Granule / butiran mudah larut dalam air)\r\nBahan Aktif :\r\n\r\nTiametoksam (Thiamethoxam) 20%\r\nEmamektin Benzoat (Emamectin Benzoate) 10%', 'Dektin_50gr.jpg', 93450, 90780, 89000, 1327, 0, NULL, 'Pcs', 'Box', '50', '1', 70, 1, '2026-06-20 14:43:55', 0),
(798, 19, 'DD2X5MPC332400078', 'Dewa Dewi 20 X 500 ml', 'Dewa Dewi adalah pupuk pelengkap cair (PPC) dengan kandungan kalium (K) tinggi 60,38% yang dilengkapi zat pengatur tumbuh (ZPT), perekat, dan anti-jamur. Produk ini diformulasikan sebagai booster fase generatif untuk membantu pembentukan, pembesaran, dan peningkatan kualitas buah maupun umbi.\r\n\r\nSpesifikasi Produk :\r\nJenis : Pupuk pelengkap cair / booster tanaman\r\nKandungan Utama : Kalium (KCl) 60,38%\r\nKomponen tambahan :\r\n\r\nZat Pengatur Tumbuh (ZPT)\r\nPerekat\r\nAnti-jamur', 'Dewa_dewi_500ml.jpg', 34020, 33048, 32400, 282, 0, NULL, 'Botol', 'Box', '20', '1', 520, 1, '2026-06-20 14:54:38', 0),
(799, 9, 'D4E2X5MI1125000430', 'Dimacide 400 EC 20 X 500 ml', 'Dimacide 400 EC adalah insektisida sistemik berbentuk pekatan emulsi (EC) yang bekerja sebagai racun kontak dan lambung untuk mengendalikan berbagai jenis hama pada tanaman. Produk ini mengandung bahan aktif Dimetoat 400 g/L dan berbentuk cairan pekat berwarna merah yang mudah dicampurkan dengan air.\r\n\r\nSpesifikasi Produk :\r\nJenis : Insektisida sistemik, kontak, dan lambung\r\nFormulasi : EC (Emulsifiable Concentrate / pekatan yang dapat diemulsikan)\r\nBahan Aktif : Dimetoat 400 g/L\r\nWarna : Pekatan cair merah', NULL, 131250, 127500, 125000, 420, 0, NULL, 'Botol', 'Box', '20', '1', 520, 1, '2026-06-22 13:23:50', 0),
(800, 9, 'E1S4X1MI885000581', 'Efficon 120 SL 48 X 100 ml', 'Efficon 120 SL adalah insektisida sistemik modern dari BASF yang diformulasikan khusus untuk mengendalikan hama kutu-kutuan pada tanaman. Produk ini menggunakan teknologi Axalion® Active dengan bahan aktif Dimpropyridaz yang bekerja melalui mekanisme unik untuk mengganggu fungsi sensorik serangga.\r\n\r\nSpesifikasi Produk :\r\nJenis : Insektisida sistemik\r\nFormulasi : SL (Soluble Liquid / larutan)\r\nTeknologi : Axalion® Active\r\nBahan Aktif : Dimpropyridaz', 'WhatsApp_Image_2026-06-22_at_14_32_21.jpeg', 89250, 86700, 85000, 9420, 0, NULL, 'Botol', 'Box', '48', '1', 120, 1, '2026-06-22 14:33:01', 0),
(801, 13, 'ET(1X1LLL224000895', 'EM-4 Tambak (LM) 15 X 1 ltr', 'EM-4 Perikanan dan Tambak adalah produk probiotik cair berbasis mikroorganisme efektif (Effective Microorganisms) yang diformulasikan khusus untuk mendukung budidaya perikanan seperti udang dan ikan pada sistem air payau maupun tambak. Produk ini bekerja dengan membantu keseimbangan ekosistem air, mempercepat penguraian bahan organik, dan menjaga kualitas lingkungan budidaya.\r\n\r\nSpesifikasi Produk :\r\nJenis : Probiotik perikanan / kultur mikroorganisme\r\nBentuk : Cair\r\nMedia : Molase dan air filtrasi\r\nFungsi utama : Pengurai bahan organik dan perbaikan kualitas air', 'WhatsApp_Image_2026-02-21_at_11_38_48.jpeg', 25200, 24480, 24000, 2185, 0, NULL, 'Botol', 'Box', '15', '', 1200, 1, '2026-06-22 14:38:15', 0),
(802, 13, 'ET(1X1LLL224000288', 'EM-4 Ternak (LC) 15 X 1 ltr', 'EM4 Peternakan (Effective Microorganisms 4) adalah produk bio-organik berbentuk cair yang mengandung kultur campuran mikroorganisme menguntungkan untuk mendukung kesehatan dan produktivitas hewan ternak. Produk ini diformulasikan untuk membantu memperbaiki sistem pencernaan, mengoptimalkan kualitas pakan, serta menjaga kebersihan lingkungan kandang.\r\n\r\nSpesifikasi Produk :\r\nJenis : Probiotik / bio-organik peternakan\r\nBentuk : Cair\r\nKandungan : Kultur mikroorganisme efektif (EM)\r\nMikroorganisme utama :\r\n\r\nLactobacillus / bakteri asam laktat\r\nRagi (Yeast)\r\nMikroorganisme fermentasi menguntungkan lainnya', 'WhatsApp_Image_2026-02-21_at_11_38_49.jpeg', 25200, 24480, 24000, 7575, 0, NULL, 'Botol', 'Box', '0', '1', 1200, 1, '2026-06-22 14:44:48', 0),
(803, 0, 'EG0D4X2G446000435', 'Eros Gold 0.75/30 DF 40 X 250 gr', 'Eros Gold 0.75/30 DF adalah herbisida sistemik dan selektif produksi UPL yang diformulasikan khusus untuk mengendalikan gulma pada tanaman padi sawah. Produk ini bekerja dengan menghambat pertumbuhan gulma tanpa mengganggu pertumbuhan tanaman padi apabila digunakan sesuai anjuran.\r\n\r\nSpesifikasi Produk :\r\nJenis : Herbisida sistemik selektif\r\nFormulasi : DF (Dispersible Granule / butiran yang dapat terdispersi dalam air)\r\nBahan Aktif :\r\n\r\nPirazosulfuron Etil 0,75%\r\nPretilaklor 30%', 'Eros_Gold_250_gram.jpg', 48300, 46920, 46000, 71120, 0, NULL, 'Pcs', 'Box', '40', '1', 270, 1, '2026-06-22 14:47:15', 0),
(804, 18, 'EGAA4X2MB330000553', 'Ever Green Asam Amino 40 X 250 ml', 'Evergreen Asam Amino adalah pupuk bio-stimulan cair yang mengandung protein, asam amino, serta unsur hara makro dan mikro yang berfungsi sebagai nutrisi tambahan untuk membantu meningkatkan pertumbuhan dan produktivitas tanaman.\r\n\r\nSpesifikasi Produk :\r\nJenis : Pupuk bio-stimulan cair\r\nKandungan Utama :\r\n\r\nAsam amino\r\nProtein\r\nNitrogen (N)\r\nZinc (Zn)\r\nBesi (Fe)\r\nNutrisi mikro lainnya\r\n\r\nCara Kerja :\r\nEvergreen Asam Amino menyediakan sumber energi dan nutrisi yang mudah diserap tanaman sehingga membantu mempercepat proses metabolisme, pertumbuhan, dan pemulihan tanaman.', NULL, 31500, 30600, 30000, 1849, 0, NULL, 'Botol', 'Box', '40', '1', 270, 1, '2026-06-22 14:49:13', 0),
(805, 1, 'F7W1X1KF1123500978', 'Fargo 70 WP 16 X 1 kg', 'Fargo 70 WP adalah fungisida kontak protektif berbentuk tepung (WP) berwarna krem/putih yang mudah dilarutkan dalam air. Produk ini digunakan untuk mencegah dan mengendalikan berbagai penyakit akibat jamur pada tanaman dengan membentuk lapisan perlindungan pada permukaan tanaman.\r\n\r\nSpesifikasi Produk :\r\nJenis : Fungisida kontak protektif\r\nFormulasi : WP (Wettable Powder / tepung yang dapat disuspensikan dalam air)\r\nBahan Aktif : Propineb 70%\r\n\r\nCara Kerja :\r\nFargo 70 WP bekerja secara kontak dan protektif, yaitu:\r\n\r\nMembentuk lapisan pelindung pada permukaan tanaman.\r\nMenghambat perkecambahan spora jamur sebelum masuk ke jaringan tanaman.\r\nMembantu mencegah perkembangan penyakit sejak awal serangan.', NULL, 129675, 125675, 123500, 32, 0, NULL, 'Pcs', 'Box', '16', '1', 1200, 1, '2026-06-22 14:56:18', 0),
(806, 1, 'F7W2X5GF665000105', 'Fargo 70 WP 20 X 500 gr', 'Fargo 70 WP adalah fungisida kontak protektif berbentuk tepung (WP) berwarna krem/putih yang mudah dilarutkan dalam air. Produk ini digunakan untuk mencegah dan mengendalikan berbagai penyakit akibat jamur pada tanaman dengan membentuk lapisan perlindungan pada permukaan tanaman.\r\n\r\nSpesifikasi Produk :\r\nJenis : Fungisida kontak protektif\r\nFormulasi : WP (Wettable Powder / tepung yang dapat disuspensikan dalam air)\r\nBahan Aktif : Propineb 70%\r\n\r\nCara Kerja :\r\nFargo 70 WP bekerja secara kontak dan protektif, yaitu:\r\n\r\nMembentuk lapisan pelindung pada permukaan tanaman.\r\nMenghambat perkecambahan spora jamur sebelum masuk ke jaringan tanaman.\r\nMembantu mencegah perkembangan penyakit sejak awal serangan.', NULL, 68250, 66300, 65000, 20, 0, NULL, 'Pcs', 'Box', '20', '1', 520, 1, '2026-06-22 14:58:25', 0),
(807, 1, 'F7W4X2GF332500146', 'Fargo 70 WP 40 X 250 gr', 'Fargo 70 WP adalah fungisida kontak protektif berbentuk tepung (WP) berwarna krem/putih yang mudah dilarutkan dalam air. Produk ini digunakan untuk mencegah dan mengendalikan berbagai penyakit akibat jamur pada tanaman dengan membentuk lapisan perlindungan pada permukaan tanaman.\r\n\r\nSpesifikasi Produk :\r\nJenis : Fungisida kontak protektif\r\nFormulasi : WP (Wettable Powder / tepung yang dapat disuspensikan dalam air)\r\nBahan Aktif : Propineb 70%\r\n\r\nCara Kerja :\r\nFargo 70 WP bekerja secara kontak dan protektif, yaitu:\r\n\r\nMembentuk lapisan pelindung pada permukaan tanaman.\r\nMenghambat perkecambahan spora jamur sebelum masuk ke jaringan tanaman.\r\nMembantu mencegah perkembangan penyakit sejak awal serangan.', NULL, 34125, 33150, 32500, 110, 0, NULL, 'Pcs', 'Box', '40', '1', 270, 1, '2026-06-22 14:59:06', 0),
(808, 13, 'FP2X5MLL666250933', 'Fitomic Plus 20 X 500 ml', 'Fitomic Plus adalah pupuk mikro majemuk cair keluaran Cap Kapal Terbang yang diformulasikan dengan kandungan Kalsium (Ca), Boron (B), dan unsur mikro lainnya untuk mendukung pertumbuhan tanaman terutama pada fase pembungaan hingga pembentukan buah.\r\n\r\nSpesifikasi Produk :\r\nJenis : Pupuk mikro majemuk cair\r\nKandungan Utama :\r\n\r\nKalsium (Ca)\r\nBoron (B)\r\nUnsur mikro pendukung lainnya', NULL, 69563, 67575, 66250, 15, 0, NULL, 'Botol', 'Box', '20', '1', 520, 1, '2026-06-22 15:12:13', 0),
(809, 9, 'F7S4X2MI1145000103', 'Flonipro 75/75 SE 40 X 250 ml', 'Flonipro 75/75 SE adalah insektisida berbentuk Suspo-Emulsion (SE) yang bekerja sebagai racun kontak dan lambung untuk mengendalikan berbagai hama serangga pada tanaman. Formulasi ini menggabungkan partikel bahan aktif padat dan cair yang tersuspensi dalam air sehingga mudah diaplikasikan.\r\n\r\nSpesifikasi Produk :\r\nJenis : Insektisida\r\nFormulasi : SE (Suspo-Emulsion)\r\nCara Kerja :\r\n\r\nRacun kontak → membunuh hama saat terkena langsung larutan semprot.\r\nRacun lambung → bekerja ketika hama memakan bagian tanaman yang telah diaplikasikan.', 'flonipro_250ml.jpeg', 152250, 147900, 145000, 897, 0, NULL, 'Botol', 'Box', '0', '1', 270, 1, '2026-06-22 15:31:43', 0),
(810, 2, 'FU4S2X1LH550000228', 'Fost Up 486 SL 20 X 1 ltr', 'FOST UP 486 SL adalah herbisida sistemik purna tumbuh berbentuk larutan dalam air yang digunakan untuk mengendalikan berbagai jenis gulma pada lahan tanpa tanaman. Produk ini bekerja dengan cara diserap melalui daun gulma kemudian ditranslokasikan ke seluruh bagian tanaman hingga menyebabkan gulma mati.\r\n\r\nSpesifikasi Produk :\r\nJenis : Herbisida sistemik purna tumbuh\r\nFormulasi : SL (Soluble Liquid / larutan dalam air)\r\nBahan Aktif : Isopropil Amina Glifosat 486 g/L', NULL, 52500, 51000, 50000, 100, 0, NULL, 'Botol', 'Box', '20', '1', 1200, 1, '2026-06-22 15:33:48', 0),
(811, 20, 'GC2X5MZ335000498', 'GA Cabe 20 X 500 ml', 'GA pada cabai umumnya merujuk pada GA3 (Asam Giberelat), yaitu salah satu Zat Pengatur Tumbuh (ZPT) yang digunakan untuk membantu meningkatkan pertumbuhan dan produktivitas tanaman cabai.\r\n\r\nSpesifikasi Singkat :\r\nJenis : ZPT (Zat Pengatur Tumbuh)\r\nNama aktif : GA3 (Giberelin / Asam Giberelat)\r\n\r\nCara Kerja :\r\nGA3 bekerja dengan merangsang aktivitas pembelahan dan pemanjangan sel pada tanaman sehingga pertumbuhan menjadi lebih cepat dan optimal.\r\n\r\nManfaat GA3 pada cabai :\r\nMemacu Pertumbuhan Tanaman\r\nMembantu mempercepat pertumbuhan vegetatif, termasuk batang dan daun.\r\nMerangsang Pembungaan\r\nMembantu pembentukan bunga lebih banyak dan seragam.\r\nMengurangi Kerontokan Bunga & Buah\r\nMembantu bunga dan buah muda lebih stabil sehingga tidak mudah gugur.\r\nMembesarkan Buah Cabai\r\nMeningkatkan proses pembelahan sel sehingga buah cabai bisa lebih panjang, besar, dan seragam.', NULL, 36750, 35700, 35000, 40, 0, NULL, 'Botol', 'Box', '20', '1', 520, 1, '2026-06-22 15:38:18', 0);
INSERT INTO `products` (`id`, `category_id`, `sku`, `name`, `description`, `picture_name`, `price`, `price_3`, `price_2`, `stock`, `current_discount`, `product_unit`, `product_unit_1`, `product_unit_2`, `product_unit_value`, `product_type`, `product_unit_weight`, `is_available`, `add_date`, `user_level`) VALUES
(812, 20, 'GP2X5MZ335000848', 'GA Padi 20 X 500 ml', 'GA (Asam Giberelat / GA3) pada padi adalah Zat Pengatur Tumbuh (ZPT) yang berfungsi untuk membantu mengatur dan meningkatkan proses pertumbuhan tanaman padi, terutama pada fase vegetatif dan generatif.\r\n\r\nSpesifikasi Singkat :\r\nJenis : ZPT (Zat Pengatur Tumbuh)\r\nBahan aktif : GA3 (Asam Giberelat)\r\n\r\nCara Kerja :\r\nGA3 bekerja dengan merangsang pembelahan dan pemanjangan sel tanaman, sehingga membantu percepatan pertumbuhan, pembentukan anakan, dan perkembangan malai padi.\r\n\r\nManfaat GA3 pada Padi :\r\nMemperbanyak Anakan\r\nMembantu meningkatkan jumlah anakan produktif pada fase vegetatif.\r\nMemperpanjang Malai\r\nMembantu malai padi menjadi lebih panjang sehingga berpotensi meningkatkan jumlah gabah.\r\nMerangsang Pembungaan Serempak\r\nMembantu proses pembungaan berlangsung lebih seragam dan optimal.\r\nMeningkatkan Hasil Gabah\r\nMendukung proses fotosintesis dan pengisian bulir agar hasil panen lebih maksimal.', NULL, 36750, 35700, 35000, 20, 0, NULL, 'Botol', 'Box', '20', '1', 520, 1, '2026-06-22 15:44:08', 0),
(813, 20, 'GSD2X5MZ335000192', 'GA Sayur Daun 20 X 500 ml', 'GA Sayur Daun adalah pupuk cair atau Zat Pengatur Tumbuh (ZPT) berbahan Gibberellic Acid (GA3) yang diformulasikan khusus untuk tanaman sayuran daun seperti bayam, kangkung, sawi, dan selada. Produk ini digunakan untuk mendukung pertumbuhan vegetatif agar daun lebih cepat besar, lebat, dan hijau segar.\r\n\r\nSpesifikasi Singkat :\r\nJenis : Pupuk cair / ZPT\r\nBahan aktif : GA3 (Gibberellic Acid)\r\n\r\nCara Kerja : GA Sayur Daun bekerja dengan merangsang pembelahan dan pemanjangan sel tanaman, sehingga pertumbuhan daun menjadi lebih cepat, lebar, dan optimal dalam menyerap cahaya untuk fotosintesis.\r\n\r\nManfaat Utama :\r\nMempercepat Pertumbuhan Daun\r\nMembantu tanaman sayuran daun tumbuh lebih cepat dan subur.\r\nMembesarkan Ukuran Daun\r\nDaun menjadi lebih lebar, tebal, dan hijau segar.\r\nMeningkatkan Produktivitas Panen\r\nHasil panen lebih banyak karena pertumbuhan vegetatif lebih optimal.\r\nMeningkatkan Kualitas Tanaman\r\nTanaman tampak lebih sehat, segar, dan bernilai jual lebih tinggi.', NULL, 36750, 35700, 35000, 200, 0, NULL, 'Botol', 'Box', '20', '1', 520, 1, '2026-06-22 15:49:52', 0),
(814, 9, 'G4S1X1LI447000387', 'Gallery 403 SL 10 X 1 ltr', 'Gallery 403 SL adalah insektisida sistemik berbentuk pekatan cair berwarna cokelat kekuningan yang diproduksi oleh PT Maju Makmur Utomo. Insektisida ini berbahan aktif Dimehipo (Dimehypo) 403 g/l yang bekerja sebagai racun kontak dan lambung untuk membasmi berbagai hama serangga.Detail UtamaFungsi: Mengendalikan hama pada tanaman seperti padi dan kelapa sawit.Hama Sasaran: Wereng cokelat (Nilaparvata lugens), penggerek batang padi (Tryporyza incertulas), ulat, belalang, dan lalat daun.Keunggulan: Cepat melumpuhkan hama sekaligus meningkatkan imunitas tanaman dan kualitas gabah.', NULL, 49350, 47940, 47000, 50, 0, NULL, 'Botol', 'Box', '10', '1', 1200, 1, '2026-06-22 15:53:07', 0),
(815, 9, 'G4S3X5MI447000627', 'Gallery 403 SL 30 X 500 ml', 'Gallery 403 SL adalah insektisida sistemik berbentuk pekatan cair (SL) dengan warna cokelat kekuningan yang efektif mengendalikan berbagai jenis hama serangga pada tanaman. Produk ini mengandung bahan aktif Dimehipo (Dimehypo) 403 g/l yang bekerja sebagai racun kontak dan racun lambung, sehingga mampu melumpuhkan serta membasmi hama secara efektif.\r\n\r\nDetail Produk\r\n\r\nNama Produk: Gallery 403 SL\r\nJenis: Insektisida sistemik\r\nFormulasi: Pekatan cair (SL)\r\nBahan Aktif: Dimehipo (Dimehypo) 403 g/l\r\nWarna: Cokelat kekuningan', 'Gallery_500ml.jpg', 49350, 47940, 47000, 90, 0, NULL, 'Botol', 'Box', '30', '1', 520, 1, '2026-06-23 13:20:27', 0),
(816, 9, 'G4S5X2M(I223500690', 'Gallery 403 SL 50 X 200 ml (M2U)', 'Gallery 403 SL adalah insektisida sistemik berbentuk pekatan cair (SL) dengan warna cokelat kekuningan yang efektif mengendalikan berbagai jenis hama serangga pada tanaman. Produk ini mengandung bahan aktif Dimehipo (Dimehypo) 403 g/l yang bekerja sebagai racun kontak dan racun lambung, sehingga mampu melumpuhkan serta membasmi hama secara efektif.\r\n\r\nDetail Produk\r\n\r\nNama Produk: Gallery 403 SL\r\nJenis: Insektisida sistemik\r\nFormulasi: Pekatan cair (SL)\r\nBahan Aktif: Dimehipo (Dimehypo) 403 g/l\r\nWarna: Cokelat kekuningan', 'Gallery_403_200ml.jpg', 24675, 23970, 23500, 100, 0, NULL, 'Botol', 'Box', '50', '1', 220, 1, '2026-06-23 13:21:30', 0),
(817, 14, 'GPF2X1X1GB329000782', 'Gambas Puspita F1 20 X 12 X 10 gr', 'Gambas Puspita F1 (Cap Kapal Terbang/BISI) adalah benih varietas unggul tanaman oyong/gambas yang banyak diminati petani karena memiliki produktivitas tinggi, pertumbuhan cepat, serta kualitas buah yang seragam. Varietas ini cocok ditanam di dataran rendah hingga menengah dan memiliki daya adaptasi yang baik terhadap berbagai kondisi lahan.\r\n\r\nDetail Produk\r\n\r\nNama Produk: Gambas Puspita F1\r\nJenis Tanaman: Oyong / Gambas\r\nProdusen: Cap Kapal Terbang / BISI\r\nTipe Varietas: Hibrida F1', NULL, 30450, 29580, 29000, 0, 0, NULL, 'Pcs', 'Box', '240', '1', 12, 1, '2026-06-23 13:23:02', 0),
(818, 9, 'G1E1X1LI994000201', 'Gemilang 110 EC 16 X 1 ltr', 'Gemilang 110 EC adalah insektisida dengan formulasi pekatan yang dapat diemulsikan (EC) berwarna kekuningan yang bekerja sebagai racun kontak dan racun lambung untuk mengendalikan berbagai jenis hama serangga pada tanaman. Produk ini diproduksi oleh PT Sari Kresna Kimia dengan kandungan bahan aktif Sipermetrin 110 g/L yang efektif melumpuhkan hama.\r\n\r\nDetail Produk\r\n\r\nNama Produk: Gemilang 110 EC\r\nJenis: Insektisida\r\nFormulasi: Emulsifiable Concentrate (EC)\r\nBahan Aktif: Sipermetrin 110 g/L\r\nWarna: Kekuningan', 'Gemilang.jpg', 98700, 95880, 94000, 176, 0, NULL, 'Botol', 'Box', '16', '1', 1200, 1, '2026-06-23 13:30:01', 0),
(819, 2, 'G4S2X1LH658500456', 'Gempur 480 SL 20 X 1 ltr', 'Gempur 480 SL adalah herbisida sistemik purna tumbuh dengan bahan aktif Isopropilamina Glifosat 480 g/l yang efektif mengendalikan berbagai jenis gulma hingga ke bagian akar. Produk ini diproduksi oleh PT Petrokimia Kayaku dan bekerja dengan cara diserap melalui daun kemudian ditranslokasikan ke seluruh jaringan tanaman gulma.\r\n\r\nDetail Produk\r\n\r\nNama Produk: Gempur 480 SL\r\nJenis: Herbisida sistemik purna tumbuh\r\nFormulasi: Larutan (SL)\r\nBahan Aktif: Isopropilamina Glifosat 480 g/l\r\nProdusen: PT Petrokimia Kayaku', 'Gempur.jpeg', 61425, 59670, 58500, 7220, 0, NULL, 'Botol', 'Box', '20', '1', 1200, 1, '2026-06-23 13:34:16', 0),
(820, 20, 'G1S2X4X1GZ33600729', 'Gibgro 10 SP 25 X 40 X 1 gr', 'Gibgro 10 SP adalah Zat Pengatur Tumbuh (ZPT) dengan kandungan Asam Giberelat (GA3) 10% yang diformulasikan khusus untuk membantu mengoptimalkan pertumbuhan dan produktivitas tanaman, terutama pada tanaman padi. Produk ini bekerja dengan merangsang proses pertumbuhan tanaman sehingga mampu membantu meningkatkan potensi hasil panen.\r\n\r\nDetail Produk\r\n\r\nNama Produk: Gibgro 10 SP\r\nJenis: Zat Pengatur Tumbuh (ZPT)\r\nBahan Aktif: Asam Giberelat (GA3) 10%\r\nFormulasi: Serbuk larut (SP)', 'Gibgro_1gr.jpg', 3780, 3672, 3600, 135675, 0, NULL, 'Pcs', 'Box', '1000', '1', 3, 1, '2026-06-23 13:38:49', 0),
(821, 2, 'G2E2X5MH1147000016', 'Glove 240 EC 20 X 500 ml', 'Glove 240 EC adalah herbisida selektif dengan formulasi EC (Emulsifiable Concentrate) yang bekerja sebagai herbisida kontak pra-tumbuh dan purna-tumbuh untuk mengendalikan berbagai jenis gulma berdaun lebar maupun berdaun sempit. Produk ini banyak digunakan dalam budidaya pertanian, terutama pada komoditas seperti bawang merah.\r\n\r\nDetail Produk\r\n\r\nNama Produk: Glove 240 EC\r\nJenis: Herbisida selektif\r\nFormulasi: Emulsifiable Concentrate (EC)\r\nBahan Aktif: Oksifluorfen (Oxyfluorfen) 240 g/l', 'Glove_500ml.jpg', 154350, 149940, 147000, 205, 0, NULL, 'Botol', 'Box', '20', '1', 520, 1, '2026-06-23 13:43:36', 0),
(822, 2, 'G2E4X2MH879000081', 'Glove 240 EC 40 X 250 ml', 'Glove 240 EC adalah herbisida selektif dengan formulasi EC (Emulsifiable Concentrate) yang bekerja sebagai herbisida kontak pra-tumbuh dan purna-tumbuh untuk mengendalikan berbagai jenis gulma berdaun lebar maupun berdaun sempit. Produk ini banyak digunakan dalam budidaya pertanian, terutama pada komoditas seperti bawang merah.\r\n\r\nDetail Produk\r\n\r\nNama Produk: Glove 240 EC\r\nJenis: Herbisida selektif\r\nFormulasi: Emulsifiable Concentrate (EC)\r\nBahan Aktif: Oksifluorfen (Oxyfluorfen) 240 g/l', 'Glove_250ml.jpg', 82950, 80580, 79000, 1214, 0, NULL, 'Botol', 'Box', '40', '1', 270, 1, '2026-06-23 13:44:41', 0),
(823, 2, 'G2S2X1LH665000124', 'Glufa 200 SL 20 X 1 ltr', 'Glufa 200 SL adalah herbisida dengan formulasi SL (Soluble Liquid) yang mengandung bahan aktif Amonium Glufosinat 200 g/L. Produk ini bekerja sebagai herbisida kontak dengan sistemik terbatas yang efektif membakar dan mengendalikan berbagai jenis gulma (rumput liar) pada area pertanian maupun perkebunan.\r\n\r\nDetail Produk\r\n\r\nNama Produk: Glufa 200 SL\r\nJenis: Herbisida\r\nFormulasi: Larutan (SL)\r\nBahan Aktif: Amonium Glufosinat 200 g/L', NULL, 68250, 66300, 65000, 16680, 0, NULL, 'Botol', 'Box', '20', '1', 1200, 1, '2026-06-23 14:02:04', 0),
(824, 2, 'G2S4X5LH3320000476', 'Glufa 200 SL 4 X 5 ltr', 'Glufa 200 SL adalah herbisida dengan formulasi SL (Soluble Liquid) yang mengandung bahan aktif Amonium Glufosinat 200 g/L. Produk ini bekerja sebagai herbisida kontak dengan sistemik terbatas yang efektif membakar dan mengendalikan berbagai jenis gulma (rumput liar) pada area pertanian maupun perkebunan.\r\n\r\nDetail Produk\r\n\r\nNama Produk: Glufa 200 SL\r\nJenis: Herbisida\r\nFormulasi: Larutan (SL)\r\nBahan Aktif: Amonium Glufosinat 200 g/L', NULL, 336000, 326400, 320000, 0, 0, NULL, 'Botol', 'Box', '0', '1', 5200, 1, '2026-06-23 14:41:16', 0),
(825, 2, 'G2E5X1MH553500627', 'Goal 240 EC 50 X 100 ml', 'Goal 240 EC adalah herbisida selektif dengan formulasi EC (Emulsifiable Concentrate) yang bekerja sebagai herbisida kontak pra-tumbuh dan purna-tumbuh awal. Produk ini mengandung bahan aktif Oksifluorfen 240 g/l yang efektif mengendalikan berbagai jenis gulma sebelum tumbuh maupun saat gulma masih muda.\r\n\r\nDetail Produk\r\n\r\nNama Produk: Goal 240 EC\r\nJenis: Herbisida kontak selektif\r\nFormulasi: Emulsifiable Concentrate (EC)\r\nBahan Aktif: Oksifluorfen 240 g/l', 'Goal.jpg', 56175, 54570, 53500, 1, 0, NULL, 'Botol', 'Box', '50', '1', 120, 1, '2026-06-23 14:43:47', 0),
(826, 2, 'G2W2GH55000716', 'Grandally 25 WP 25 gr', 'Grandally 25 WP adalah herbisida sistemik selektif purna tumbuh berbentuk tepung (WP) berwarna putih/krem yang efektif mengendalikan berbagai jenis gulma berdaun lebar dan teki-tekian pada tanaman padi sawah. Produk ini mengandung bahan aktif Metil Metsulfuron 25% yang bekerja dengan menghambat pertumbuhan sel gulma sehingga gulma berhenti berkembang, menguning, lalu mati.\r\n\r\nDetail Produk\r\n\r\nNama Produk: Grandally 25 WP\r\nJenis: Herbisida sistemik selektif\r\nFormulasi: Tepung yang dapat disuspensikan (WP)\r\nBahan Aktif: Metil Metsulfuron 25%\r\nWarna: Putih/krem', 'Grandally.jpg', 5250, 5100, 5000, 33533, 0, NULL, 'Pcs', 'Box', '100', '1', 27, 1, '2026-06-23 14:45:16', 0),
(827, 2, 'G2W5GH33000768', 'Grandally 25 WP 5 gr', 'Grandally 25 WP adalah herbisida sistemik selektif purna tumbuh berbentuk tepung (WP) berwarna putih/krem yang efektif mengendalikan berbagai jenis gulma berdaun lebar dan teki-tekian pada tanaman padi sawah. Produk ini mengandung bahan aktif Metil Metsulfuron 25% yang bekerja dengan menghambat pertumbuhan sel gulma sehingga gulma berhenti berkembang, menguning, lalu mati.\r\n\r\nDetail Produk\r\n\r\nNama Produk: Grandally 25 WP\r\nJenis: Herbisida sistemik selektif\r\nFormulasi: Tepung yang dapat disuspensikan (WP)\r\nBahan Aktif: Metil Metsulfuron 25%\r\nWarna: Putih/krem', 'Grandally1.jpg', 3150, 3060, 3000, 115901, 0, NULL, 'Pcs', 'Box', '100', '1', 7, 1, '2026-06-23 14:46:08', 0),
(828, 1, 'G2S4X2MF1145000858', 'Grandprix 200/125 SC 40 X 250 ml', 'Grand Prix 200/125 SC adalah fungisida sistemik spektrum luas dengan kombinasi dua bahan aktif unggulan yaitu Azoksistrobin 200 g/l dan Difenokonazol 125 g/l. Produk ini bekerja secara protektif dan kuratif untuk mengendalikan berbagai penyakit yang disebabkan oleh jamur sekaligus membantu meningkatkan kualitas serta potensi hasil panen.\r\n\r\nDetail Produk\r\n\r\nNama Produk: Grand Prix 200/125 SC\r\nJenis: Fungisida sistemik\r\nFormulasi: Suspensi pekat (SC)\r\nBahan Aktif:\r\n\r\nAzoksistrobin 200 g/l\r\nDifenokonazol 125 g/l', NULL, 152250, 147900, 145000, 1195, 0, NULL, 'Botol', 'Box', '40', '1', 270, 1, '2026-06-23 14:47:38', 0),
(829, 1, 'G2S5X1MF661000912', 'Grandprix 200/125 SC 50 X 100 ml', 'Grand Prix 200/125 SC adalah fungisida sistemik spektrum luas dengan kombinasi dua bahan aktif unggulan yaitu Azoksistrobin 200 g/l dan Difenokonazol 125 g/l. Produk ini bekerja secara protektif dan kuratif untuk mengendalikan berbagai penyakit yang disebabkan oleh jamur sekaligus membantu meningkatkan kualitas serta potensi hasil panen.\r\n\r\nDetail Produk\r\n\r\nNama Produk: Grand Prix 200/125 SC\r\nJenis: Fungisida sistemik\r\nFormulasi: Suspensi pekat (SC)\r\nBahan Aktif:\r\n\r\nAzoksistrobin 200 g/l\r\nDifenokonazol 125 g/l', NULL, 64050, 62220, 61000, 950, 0, NULL, 'Botol', 'Box', '50', '1', 120, 1, '2026-06-23 14:48:32', 0),
(830, 2, 'G4S2X1LH550000002', 'Grasso 480 SL 20 X 1 ltr', 'Grasso 480 SL adalah herbisida sistemik purna tumbuh yang efektif mengendalikan berbagai jenis gulma hingga ke bagian akar. Produk ini mengandung bahan aktif Isopropil amina glifosat 480 g/l yang bekerja dengan cara diserap melalui daun dan kemudian menyebar ke seluruh jaringan gulma.\r\n\r\nDetail Produk\r\n\r\nNama Produk: Grasso 480 SL\r\nJenis: Herbisida sistemik purna tumbuh\r\nFormulasi: Larutan (SL)\r\nBahan Aktif: Isopropil amina glifosat 480 g/l', 'Grasso_1ltr.jpg', 52500, 51000, 50000, 15753, 0, NULL, 'Botol', 'Box', '20', '1', 1200, 1, '2026-06-23 14:50:02', 0),
(831, 19, 'GVB1X1MPC332000442', 'GW Vit B1+B6 100 X 100 ml', 'GW Vit B1+B6 (Green World Vitamin B1+B6) adalah pupuk mikro majemuk cair anti-stress yang diformulasikan untuk membantu pemulihan dan meningkatkan pertumbuhan tanaman, terutama tanaman hias, bonsai, dan tanaman yang mengalami gangguan pertumbuhan.\r\n\r\nSpesifikasi Produk :\r\nJenis : Pupuk mikro majemuk cair / vitamin tanaman\r\nKandungan Utama :\r\n\r\nVitamin B1\r\nVitamin B6\r\nUnsur mikro pendukung pertumbuhan tanaman', NULL, 33600, 32640, 32000, 3690, 0, NULL, 'Botol', 'Box', '100', '1', 120, 1, '2026-06-24 14:17:22', 0),
(832, 9, 'HP1S6X1MI772000572', 'Herole Plus 100/20 SC 64 X 100 ml', 'Herole Plus 100/20 SC adalah insektisida berspektrum luas dengan kombinasi dua bahan aktif yang bekerja secara sinergis untuk mengendalikan berbagai jenis hama, terutama hama ulat dan perusak daun pada tanaman hortikultura.\r\n\r\nSpesifikasi Produk :\r\nJenis : Insektisida\r\nFormulasi : SC (Suspension Concentrate / pekatan suspensi)\r\nBahan Aktif :\r\n\r\nKlorfenapir 100 g/L\r\nEmamektin Benzoat 20 g/L', NULL, 75600, 73440, 72000, 0, 0, NULL, 'Botol', 'Box', '0', '1', 120, 1, '2026-06-24 14:36:12', 0),
(833, 1, 'H7W2X4GF1116500459', 'Hexagold 75 WP 25 X 400 gr', 'Hexagold 75 WP adalah fungisida campuran bersifat fungitoksik, kontak, dan sistemik berbentuk tepung yang dapat disuspensikan dalam air. Produk ini digunakan untuk membantu mengendalikan berbagai penyakit yang disebabkan oleh jamur pada tanaman.\r\n\r\nSpesifikasi Produk :\r\nJenis : Fungisida campuran\r\nFormulasi : WP (Wettable Powder / tepung yang dapat disuspensikan)\r\nBahan Aktif :\r\n\r\nKaptan 70%\r\nHekzakonazol 5%', 'Hexagold_400_gram.jpg', 122325, 118830, 116500, 150, 0, NULL, 'Pcs', 'Box', '25', '1', 420, 1, '2026-06-24 14:50:59', 0);
